window.QBANK={"1":[{"y":2015,"e":"국가직 9급","qn":1,"i":"N92015-01-1","t":"적법절차를 위반한 수사행위에 기초하여 수집한 증거라도 적법 절차에 위배되는 행위의 영향이 차단되거나 소멸되었다고 볼 수 있는 상태에서 수집한 것이라면 유죄 인정의 증거로 사용할 수 있다.","ox":"O","m":"①","c":"A","tp":"형사소송의 이념과 목적"},{"y":2015,"e":"국가직 9급","qn":1,"i":"N92015-01-2","t":"대법원의 파기환송 판결에 의하여 사건을 환송받은 법원이 2월의 구속기간의 만료에 따라 구속기간을 갱신하는 것은 신체의 자유를 제한하는 것이므로 무죄추정원칙에 위배된다.","ox":"X","m":"②","c":"A","tp":"형사소송의 이념과 목적"},{"y":2015,"e":"국가직 9급","qn":1,"i":"N92015-01-3","t":"헌법 제12조 제3항에 규정된 영장주의는 구속의 개시시점 뿐만 아니라 구속영장의 취소 또는 실효의 여부도 법관의 판단에 의하여 결정되어야 한다는 것을 의미한다.","ox":"O","m":"③","c":"A","tp":"형사소송의 이념과 목적"},{"y":2015,"e":"국가직 9급","qn":1,"i":"N92015-01-4","t":"신속한 재판을 받을 권리는 주로 피고인의 이익을 보호하기 위한 기본권이지만 동시에 실체적 진실발견, 소송경제 등의 공공의 이익에도 근거가 있다.","ox":"O","m":"④","c":"A","tp":"형사소송의 이념과 목적"},{"y":2015,"e":"국가직 9급","qn":2,"i":"N92015-02-1","t":"법원은 공소제기된 사건에 대하여 군사법원이 재판권을 가졌음이 판명된 때는 결정으로 사건을 재판권이 있는 같은 심급의 군사 법원으로 이송하여야 한다.","ox":"O","m":"①","c":"A","tp":"법원의 관할"},{"y":2015,"e":"국가직 9급","qn":2,"i":"N92015-02-2","t":"단독판사 관할 피고사건의 항소사건이 지방법원 합의부에 계속 중일 때 그 변론종결 시까지 청구된 치료감호사건의 관할법원은 고등법원이고, 이 때 피고사건의 관할법원도 고등법원이 된다.","ox":"O","m":"②","c":"A","tp":"법원의 관할"},{"y":2015,"e":"국가직 9급","qn":2,"i":"N92015-02-3","t":"고유관할사건 계속 중 고유관할 법원에 관련 사건이 계속된 이상 그 후 양 사건이 병합심리되지 아니한 채 고유사건에 대한 심리가 먼저 종결되었더라도 관련 사건에 대한 관할권은 유지된다.","ox":"O","m":"③","c":"A","tp":"법원의 관할"},{"y":2015,"e":"국가직 9급","qn":2,"i":"N92015-02-4","t":"제1심 공판절차에서 합의부 관할사건이 공소장변경에 의하여 단독판사 관할사건으로 변경된 경우 사건을 단독판사에게 재배당하여야 한다.","ox":"X","m":"④","c":"A","tp":"법원의 관할"},{"y":2015,"e":"국가직 9급","qn":3,"i":"N92015-03-1","t":"검사가 공소장을 제출하지 아니하고서 행한 공소제기는 무효 이지만 추완이 허용된다.","ox":"X","m":"①","c":"A","tp":"소송행위"},{"y":2015,"e":"국가직 9급","qn":3,"i":"N92015-03-2","t":"반의사불벌죄 사건에서 피해자인 청소년의 처벌희망 의사표시의 철회는 법정대리인의 동의가 있거나 법정대리인의 대리에 의하여야 효력이 있다.","ox":"X","m":"②","c":"A","tp":"소송행위"},{"y":2015,"e":"국가직 9급","qn":3,"i":"N92015-03-3","t":"기피신청을 받은 법관이 본안의 소송절차를 정지해야 함에도 그대로 소송을 진행해서 이루어진 소송행위는 그 후 기피 신청에 대한 기각결정이 확정되었더라도 무효이다.","ox":"O","m":"③","c":"A"},{"y":2015,"e":"국가직 9급","qn":3,"i":"N92015-03-4","t":"법원에서 피고인이 국민참여재판을 원하는지에 관한 의사의 확인절차를 거치지 아니한 채 통상의 공판절차로 재판을 진행한 경우 그 공판절차에서 이루어진 소송행위는 유효하다.","ox":"X","m":"④","c":"A"},{"y":2015,"e":"국가직 9급","qn":11,"i":"N92015-11-1","t":"재판절차진술권은 피해자의 사망에 의하여 소멸되므로 교통 사고로 사망한 사람의 부모는 재판절차진술권이 인정되는 형사피해자에 해당되지 않는다.","ox":"X","m":"①","c":"A","tp":"형사소송법 상 범죄피해자의 지위"},{"y":2015,"e":"국가직 9급","qn":11,"i":"N92015-11-2","t":"피해자를 증인으로 신문하는 경우 피고인의 처벌에 관한 의견을 포함하여 당해 사건에 관한 의견을 진술할 기회를 주어야 한다.","ox":"O","m":"②","c":"A","tp":"형사소송법 상 범죄피해자의 지위"},{"y":2015,"e":"국가직 9급","qn":11,"i":"N92015-11-3","t":"진술해야 할 피해자가 13세 미만이거나, 신체적 또는 정신적 장애로 사물을 변별하거나 의사를 결정할 능력이 미약한 경우라도 부득이한 사정이 있는 때에는 신뢰관계에 있는 자를 동석시키지 않을 수 있다.","ox":"O","m":"③","c":"A","tp":"형사소송법 상 범죄피해자의 지위"},{"y":2015,"e":"국가직 9급","qn":11,"i":"N92015-11-4","t":"피해자의 공판기록 열람·등사신청이 있는 때에 재판장은 등사한 소송기록의 사용목적을 제한하거나 조건을 부가하여 이를 허가할 수 있으며, 이에 관한 재판에 대하여는 불복할 수 없다.","ox":"O","m":"④","c":"A","tp":"형사소송법 상 범죄피해자의 지위"},{"y":2015,"e":"국가직 9급","qn":12,"i":"N92015-12-1","t":"형사소송법은 구속·불구속 피의자의 신문 시 변호인 또는 변호인이 되려는 자의 참여권을 인정하고 있다.","ox":"X","m":"①","c":"A"},{"y":2015,"e":"국가직 9급","qn":12,"i":"N92015-12-2","t":"피의자신문에 참여하고자 하는 변호인이 2인 이상인 경우 검사는 피의자의 의견을 물어 신문에 참여할 변호인을 지정 하여야 한다.","ox":"X","m":"②","c":"A"},{"y":2015,"e":"국가직 9급","qn":12,"i":"N92015-12-3","t":"피고인의 법정대리인, 특별대리인, 보조인은 피고인의 위임장이나 신분관계증명문서 중 하나를 제출하면 소송계속 중의 관계 서류 또는 증거물을 열람·등사할 수 있다.","ox":"X","m":"③","c":"A"},{"y":2015,"e":"국가직 9급","qn":12,"i":"N92015-12-4","t":"판례에 따르면 피고인의 공판조서 열람·등사의 청구에 법원이 응하지 아니한 것이 피고인의 방어권이나 변호인의 변호권을 본질적으로 침해한 정도에 이르지는 않은 경우 그 공판조서는 증거로 사용할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"국가직 9급","qn":1,"i":"N92016-01-1","t":"검사, 피고인, 변호인은 기피신청을 할 수 있지만, 변호인은 피고인의 명시한 의사에 반하는 경우에는 법관에 대한 기피 신청을 할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"국가직 9급","qn":1,"i":"N92016-01-2","t":"기피원인에 관한 형사소송법 제18조 제1항 제2호 소정의 ‘법관이 불공평한 재판을 할 염려가 있는 때’라고 함은 당사자가 불공평한 재판이 될지도 모른다고 추측할 만한 주관적인 사정이 있는 때를 의미한다.","ox":"X","m":"②","c":"A","tp":"기피신청"},{"y":2016,"e":"국가직 9급","qn":1,"i":"N92016-01-3","t":"소송지연을 목적으로 함이 명백한 기피신청인지의 여부는 기피신청인이 제출한 소명 방법만으로 판단할 것은 아니고 당해 법원에 현저한 사실이거나 당해 사건기록에 나타나 있는 제반 사정들을 종합하여 판단할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"국가직 9급","qn":1,"i":"N92016-01-4","t":"기피신청을 받은 법관이 형사소송법 제22조에 위반하여 본안의 소송절차를 정지하지 않은 채 그대로 소송을 진행 하여서 한 소송행위는 그 효력이 없고, 이는 그 후 그 기피 신청에 대한 기각결정이 확정되었다고 하더라도 마찬가지이다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"국가직 9급","qn":6,"i":"N92016-06","t":"형사소송의 이념과 목적에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"형사소송의 이념과 목적에 대한 설명으로 옳지 않은 것은?","d":"","o":["헌법이 보장하는 공정한 재판을 받을 권리 속에는 원칙적으로 당사자주의와 구두변론주의가 보장되어 당사자가 공소사실에 대한 답변과 입증 및 반증하는 등 공격․방어권이 충분히 보장되는 재판을 받을 권리가 포함되어 있다.","형사소송에 관한 절차법에서 소극적 진실주의의 요구를 외면한 채 범인필벌의 요구만을 앞세워 합리성과 정당성을 갖추지 못한 방법이나 절차에 의한 증거수집과 증거조사를 허용하는 것은 적법절차의 원칙 및 공정한 재판을 받을 권리에 위배된다.","헌법상 보장되는 ‘변호인의 조력을 받을 권리’는 변호인의 ‘충분한 조력’을 받을 권리를 의미하므로, 일정한 경우 피고인 에게 국선변호인의 조력을 받을 권리를 보장하여야 할 국가의 의무에는 형사소송절차에서 단순히 국선변호인을 선정하여 주는 데 그치지 않고 한 걸음 더 나아가 피고인이 국선변호인의 실질적인 조력을 받을 수 있도록 필요한 업무 감독과 절차적 조치를 취할 책무까지 포함된다.","공소장일본주의를 위반하는 것은 소송절차의 생명이라 할 수 있는 공정한 재판의 원칙에 치명적인 손상을 가하는 것이고, 이를 위반한 공소제기는 법률의 규정에 위배된 것으로 치유될 수 없는 것이므로 소송절차의 시기 및 위반의 정도와 무관하게 항상 공소기각의 판결을 해야한다. 형사소송법개론 2 책형 2 쪽"],"a":4}},{"y":2017,"e":"국가직 9급","qn":5,"i":"N92017-05-1","t":"제1심 공판기일에서 증거조사를 하고 그 증거들이 제1심 판결에서 유죄의 증거로 사용되었으나 판결은 그 이후 경질된 판사가 하였다면, 제1심에서 증거조사를 한 판사가 항소심 재판을 하는 것은 제척사유에 해당하지 않는다.","ox":"X","m":"①","c":"A"},{"y":2017,"e":"국가직 9급","qn":5,"i":"N92017-05-2","t":"선거관리위원장으로서 공직선거법위반 혐의사실에 대하여 수사기관에 수사의뢰를 한 법관이 당해 형사피고사건의 재판을 하는 것은 제척사유에 해당하지 않는다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"국가직 9급","qn":5,"i":"N92017-05-3","t":"통역인이 사건에 관하여 증인으로 증언한 때에는 직무집행에서 제척되나, 통역인이 피해자의 사실혼 배우자인 경우에는 통역인에게 제척사유가 있다고 할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"국가직 9급","qn":5,"i":"N92017-05-4","t":"약식명령을 발부한 법관이 정식재판절차의 제1심 판결에 관여하는 경우는 제척사유에 해당하지 않으나, 약식명령을 한 판사가 그에 대한 정식재판 절차의 항소심판결에 관여하는 경우는 제척사유에 해당한다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"국가직 9급","qn":12,"i":"N92017-12","t":"법원의 관할에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"법원의 관할에 대한 설명으로 옳지 않은 것은?","d":"","o":["동일사건이 사물관할을 달리하는 수개의 법원에 계속된 때에는 법원합의부가 심판하고, 심판하지 않게 된 법원은 판결로 공소를 기각하여야 한다.","사물관할을 달리하는 수개의 관련사건이 각각 법원합의부와 단독판사에 계속된 때에는 합의부는 결정으로 단독판사에 속한 사건을 병합하여 심리할 수 있다.","토지관할을 달리하는 수개의 제1심 법원들에 관련사건이 계속된 경우에 그 소속 고등법원이 같은 때에는 그 고등법원이, 그 소속 고등법원이 다른 때에는 대법원이 제1심 법원들의 공통되는 직근상급법원으로서 토지관할 병합심리 신청사건의 관할법원이 된다.","단독판사의 관할사건이 공소장변경에 의하여 합의부 관할사건 으로 변경된 경우에 법원은 결정으로 관할권이 있는 법원에 이송한다. 형사"],"a":1}},{"y":2018,"e":"국가직 9급","qn":5,"i":"N92018-05-1","t":"소추기관과 재판기관이 분리되었는지 여부에 따라 규문주의와 탄핵주의로 구별된다.","ox":"O","m":"①","c":"A","tp":"형사소송의 구조"},{"y":2018,"e":"국가직 9급","qn":5,"i":"N92018-05-2","t":"소송의 스포츠화 또는 합법적 도박이 야기될 수 있다는 점은 당사자주의에 대한 비판이고, 사건의 심리가 국가기관의 자의적 판단이나 독단으로 흐를 수 있다는 점은 직권주의에 대한 비판이다.","ox":"O","m":"②","c":"A","tp":"형사소송의 구조"},{"y":2018,"e":"국가직 9급","qn":5,"i":"N92018-05-3","t":"증인에 대한 교호신문절차, 증거동의제도는 당사자주의적 요소이다.","ox":"O","m":"③","c":"A","tp":"형사소송의 구조"},{"y":2018,"e":"국가직 9급","qn":5,"i":"N92018-05-4","t":"피고인신문제도, 법원의 공소장변경 요구의무, 공소장일본주의는 직권주의적 요소이다.","ox":"X","m":"④","c":"A","tp":"형사소송의 구조"},{"y":2018,"e":"국가직 9급","qn":10,"i":"N92018-10-1","t":"피고인 및 피의자와 형사소송법 제30조제2항에 규정된 자뿐만 아니라 피고인 및 피의자로부터 그 선임권을 위임받은 자도 피고인이나 피의자를 대리하여 변호인을 선임할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2018,"e":"국가직 9급","qn":10,"i":"N92018-10-2","t":"국선변호인 선정을 청구한 피고인이 빈곤으로 인하여 변호인을 선임할 수 없다고 인정할 여지가 충분한 경우, 법원은 특별한 사정이 없는 한 국선변호인 선정결정을 하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"국가직 9급","qn":10,"i":"N92018-10-3","t":"공범관계에 있지 않은 공동피고인들 사이에서 공소사실로 보아 어느 피고인에 대하여는 유리한 변론이 다른 피고인에 대하여는 불리한 결과를 초래하는 사건의 경우, 그 공동 피고인들에 대하여 선정된 동일한 국선변호인이 공동피고인들을 함께 변론하였다면 위법하다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"국가직 9급","qn":10,"i":"N92018-10-4","t":"구속 전 피의자심문에서 심문할 피의자에게 변호인이 없는 때에는 지방법원판사는 직권으로 변호인을 선정하여야 하며, 이 경우 변호인의 선정은 피의자에 대한 구속영장 청구가 기각된 경우를 제외하고, 제1심까지 효력이 있다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"국가직 9급","qn":11,"i":"N92018-11-1","t":"법원사무관등과 통역인에 대한 기피재판은, 소송지연의 목적이 명백하거나 관할위반의 경우를 제외하고, 그 소속법원이 결정으로 하여야 한다.","ox":"O","m":"①","c":"A","tp":"제척, 기피제도"},{"y":2018,"e":"국가직 9급","qn":11,"i":"N92018-11-2","t":"약식명령을 발령한 법관이 정식재판절차의 제1심 판결에 관여하였다고 하여 제척의 원인이 된다고 볼 수는 없다.","ox":"O","m":"②","c":"A","tp":"제척, 기피제도"},{"y":2018,"e":"국가직 9급","qn":11,"i":"N92018-11-3","t":"기피신청을 인용한 결정 및 기각한 결정에 대하여는 즉시항고가 허용된다.","ox":"X","m":"③","c":"A","tp":"제척, 기피제도"},{"y":2018,"e":"국가직 9급","qn":11,"i":"N92018-11-4","t":"기피당한 법관은 기피에 관한 결정에 관여하지 못하며, 기피당한 법관의 소속법원이 합의부를 구성하지 못하는 때에는 직근 상급법원이 결정하여야 한다.","ox":"O","m":"④","c":"A","tp":"제척, 기피제도"},{"y":2018,"e":"국가직 9급","qn":18,"i":"N92018-18","t":"피해자에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"피해자에 대한 설명으로 옳지 않은 것은?","d":"","o":["고소의 주체가 되는 피해자에는 법인, 법인격 없는 사단이나 재단도 포함된다.","고소를 하지 않은 피해자라고 하더라도 검사의 불기소처분에 대하여 항고할 수 있다.","성폭력범죄의 처벌 등에 관한 특례법 제30조제1항에 따라 촬영한 영상물에 수록된 피해자의 진술에 대해서는 증거로 사용할 수 있는 특례가 마련되어 있다.","법원은 범죄로 인한 피해자를 증인으로 신문하는 경우 당해 피해자․법정대리인 또는 검사의 신청에 따라 피해자의 신변 보호를 위하여 필요하다고 인정하는 때에는 결정으로 심리를 공개하지 아니할 수 있다. 형사"],"a":2}},{"y":2019,"e":"국가직 9급","qn":5,"i":"N92019-05-1","t":"기피신청을 받은 법관이 소송진행 정지에 대한 예외 사유가 없음에도 불구하고 본안의 소송절차를 정지하지 않은 채 그대로 진행한 소송행위는 효력이 없지만, 그 후 기피신청에 대한 기각결정이 확정되었다면 유효하다.","ox":"X","m":"①","c":"A"},{"y":2019,"e":"국가직 9급","qn":5,"i":"N92019-05-2","t":"원심 합의부원인 법관이 원심 재판장에 대한 기피신청 사건의 심리와 기각결정에 관여한 사실이 있다면, 이는 형사소송법 제17조제7호 소정의 ‘법관이 사건에 관하여 그 기초되는 조사, 심리에 관여한 때’에 해당하여 기피사유가 인정된다.","ox":"X","m":"②","c":"A"},{"y":2019,"e":"국가직 9급","qn":5,"i":"N92019-05-3","t":"법관이 피고인의 증거신청을 채택하지 아니하거나 이미 한 증거결정을 취소한 사정만으로도 기피사유에 해당한다.","ox":"X","m":"③","c":"A"},{"y":2019,"e":"국가직 9급","qn":5,"i":"N92019-05-4","t":"법관에 대한 기피신청이 있는 경우 형사소송법 제22조에 따라 정지되는 소송진행에 판결의 선고는 포함되지 아니한다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"국가직 9급","qn":8,"i":"N92020-08","t":"필요적 변호사건에 대한 설명으로 옳은 것만을 모두 고르면?","c":"A","mc":{"s":"필요적 변호사건에 대한 설명으로 옳은 것만을 모두 고르면?","d":"(다툼이 있는 경우 판례에 의함)\nㄱ. 필요적 변호사건과 다른 사건을 병합하여 심리하는 경우에 변호인의 관여 없이 공판절차를 진행한 위법은 필요적 변호사건이 아닌 다른 사건 부분에는 미치지 않는다.\nㄴ. 필요적 변호사건에서 항소법원이 국선변호인을 선정하고 피고인과 그 변호인에게 소송기록접수통지를 한 다음 피고인이 새로이 사선변호인을 선임함에 따라 국선 변호인의 선정을 취소한 경우, 항소법원은 사선변호인에게 소송기록접수통지를 다시 하여야 한다.\nㄷ. 필요적 변호사건의 항소심에서는, 원심법원이 피고인 본인의 항소이유서 제출기간 경과 후 국선변호인을 선정하고 그에게 소송기록접수통지를 하였으나 국선 변호인이 법정기간 내에 항소이유서를 제출하지 아니한 경우, 국선변호인의 항소이유서 불제출에 대하여 피고인의 귀책사유가 밝혀지지 아니한 이상 피고인의 항소를 기각할 것이 아니라 국선변호인의 선정을 취소하고 새로운 국선변호인을 선정하는 조치를 취하여야 한다.\nㄹ. 필요적 변호사건이라 하여도 피고인이 재판거부의사를 표시하고 재판장의 허가 없이 퇴정한 후 변호인마저 이에 동조하여 퇴정해 버린 경우, 피고인과 변호인이 출석하지 않은 상태에서 증거조사를 할 수밖에 없는 때에는 피고인의 증거동의가 있는 것으로 간주한다.","o":["ㄱ, ㄴ","ㄴ, ㄷ","ㄷ, ㄹ","ㄱ, ㄷ, ㄹ"],"a":3}},{"y":2020,"e":"국가직 9급","qn":11,"i":"N92020-11","t":"법원의 관할에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"법원의 관할에 대한 설명으로 옳지 않은 것은?","d":"","o":["동일 사건이 사물관할을 달리하는 수 개의 제1심 법원에 계속된 때에는 법원 합의부가 심판하게 되는데, 이 경우 단독판사는 즉시 공소기각의 결정을 하여야 하지만 만일 단독판사의 판결이 먼저 확정되었다면 합의부는 면소판결을 하여야 한다.","토지관할의 기준으로서 피고인의 현재지는 공소제기 당시 피고인이 현재한 장소를 의미하며, 여기에는 임의에 의한 현재지뿐만 아니라 적법한 강제에 의한 현재지도 포함된다.","지방법원 본원에 제1심 토지관할이 인정된다고 볼 특별한 사정이 없다면, 지방법원 지원에 제1심 토지관할이 인정된다는 사정만으로 지방법원 본원에도 제1심 토지관할이 당연히 인정된다고 볼 수 없다.","일반 국민이 범한 수 개의 죄 가운데 특정 군사범죄와 그 밖의 일반 범죄가 형법 제37조 전단의 경합범 관계에 있다고 보아 하나의 사건으로 일반법원에 기소된 경우, 그 일반법원은 재판권이 없는 군사범죄를 포함하여 기소된 사건 전부를 심판할 수 있다. 2020년도 국가공무원 9급 공채 필기시험 형사"],"a":4}},{"y":2021,"e":"국가직 9급","qn":2,"i":"N92021-02","t":"대한민국헌법 에서 형사절차와 관련하여 명시적으로 규정하고 있는 것만을 모두 고르면?","c":"A","mc":{"s":"대한민국헌법 에서 형사절차와 관련하여 명시적으로 규정하고 있는 것만을 모두 고르면?","d":"ㄱ. 누구든지 체포 또는 구속을 당한 때에는 적부의 심사를 법원에 청구할 권리를 가진다.\nㄴ. 적법한 절차에 따르지 아니하고 수집한 증거는 증거로 할 수 없다.\nㄷ. 형사피의자 또는 형사피고인으로서 구금되었던 자가 법률이 정하는 불기소처분을 받거나 무죄판결을 받은 때에는 법률이 정하는 바에 의하여 국가에 정당한 보상을 청구할 수 있다.\nㄹ. 피고인의 자백이 고문․폭행․협박․구속의 부당한 장기화 또는 기망 기타의 방법에 의하여 자의로 진술된 것이 아니라고 인정될 때 또는 정식재판에 있어서 피고인의 자백이 그에게 불리한 유일한 증거일 때에는 이를 유죄의 증거로 삼거나 이를 이유로 처벌할 수 없다.\nㅁ. 영장에 의한 체포․긴급체포 또는 현행범인의 체포에 따라 체포된 피의자에 대하여 구속영장을 청구받은 판사는 지체 없이 피의자를 심문하여야 한다.","o":["ㄱ, ㄷ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㄹ","ㄴ, ㄹ, ㅁ"],"a":2}},{"y":2021,"e":"국가직 9급","qn":4,"i":"N92021-04-1","t":"단독판사의 관할사건이 공소장변경에 의하여 합의부 관할 사건으로 변경된 경우에 법원은 결정으로 사건을 관할권이 있는 법원에 이송하여야 한다.","ox":"O","m":"①","c":"A","tp":"소송주체"},{"y":2021,"e":"국가직 9급","qn":4,"i":"N92021-04-2","t":"변호인의 선임은 심급마다 변호인과 연명날인한 서면으로 제출하여야 하며, 공소제기 전의 변호인 선임은 제1심에도 그 효력이 있다.","ox":"O","m":"②","c":"A","tp":"소송주체"},{"y":2021,"e":"국가직 9급","qn":4,"i":"N92021-04-3","t":"검사는 부패범죄, 경제범죄 등 대통령령으로 정하는 중요범죄, 경찰공무원이 범한 범죄에 대하여 수사를 개시할 수 있다.","ox":"O","m":"③","c":"A","tp":"소송주체","t0":"검사는 부패범죄, 경제범죄, 공직자범죄, 선거범죄, 방위사업 범죄, 대형참사 등 검사의 수사개시 범죄 범위에 관한 규정이 정하는 중요범죄, 경찰공무원이 범한 범죄에 대하여 수사를 개시할 수 있다.","ox0":"O","rv":"개정 반영"},{"y":2021,"e":"국가직 9급","qn":4,"i":"N92021-04-4","t":"반의사불벌죄의 피해자는 피의자나 피고인 및 그들의 변호인에게 자신을 대리하여 수사기관이나 법원에 자신의 처벌불원의사를 표시할 수 있는 권한을 수여할 수 없다.","ox":"X","m":"④","c":"A","tp":"소송주체"},{"y":2023,"e":"국가직 9급","qn":5,"i":"N92023-05-1","t":"기피원인으로서의 ‘불공평한 재판을 할 염려가 있는 때’란 당사자가 불공평한 재판이 될지도 모른다고 추측할 만한 주관적인 사정이 있는 때를 말한다.","ox":"X","m":"①","c":"A","tp":"법관의 기피"},{"y":2023,"e":"국가직 9급","qn":5,"i":"N92023-05-2","t":"재판부가 당사자의 증거신청을 채택하지 않았다는 것만으로는 기피사유가 되지 않지만, 이미 행한 증거결정을 취소하였다는 것은 그 자체로서 기피사유가 된다.","ox":"X","m":"②","c":"A","tp":"법관의 기피"},{"y":2023,"e":"국가직 9급","qn":5,"i":"N92023-05-3","t":"재판장이 피고인의 증인신문권의 본질적인 부분을 침해하였다고 볼 만한 소명자료가 없더라도, 재판장이 증인에 대한 피고인의 신문을 제지한 사실이 있다는 것은 그 자체로서 기피사유가 된다.","ox":"X","m":"③","c":"A","tp":"법관의 기피"},{"y":2023,"e":"국가직 9급","qn":5,"i":"N92023-05-4","t":"재판부가 형사소송법에 정한 기간 내에 재정신청사건의 결정을 하지 아니하였다는 사유만으로는 기피사유가 되지 않는다.","ox":"O","m":"④","c":"A","tp":"법관의 기피"},{"y":2023,"e":"국가직 9급","qn":11,"i":"N92023-11-1","t":"피고인이 법인일 때는 법인의 대표자가 제삼자에게 변호인 선임을 위임하여 그로 하여금 법인을 위한 변호인을 선임하도록 할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2023,"e":"국가직 9급","qn":11,"i":"N92023-11-2","t":"변호인이 되려는 자가 변호인 선임서를 제출하지 않은 채 상고 이유서만을 제출하고 상고이유서 제출기간이 지난 후에 변호인 선임서를 제출하였더라도 그 상고이유서는 적법ㆍ유효하다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"국가직 9급","qn":11,"i":"N92023-11-3","t":"필요적 변호사건에서 변호인 없이 개정하여 심리를 진행한 다음 무죄판결을 한 경우, 이는 소송절차의 법령위반에 해당하므로 당해 판결은 무효이다.","ox":"X","m":"③","c":"A"},{"y":2023,"e":"국가직 9급","qn":11,"i":"N92023-11-4","t":"구속된 피고인에 대한 변호인이 여러 명인 경우, 변호인의 접견교통권 행사가 그 한계를 일탈한 것인지의 여부는 해당 변호인을 기준으로 하여 개별적으로 판단하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"국가직 9급","qn":17,"i":"N92023-17-1","t":"형사재판의 증거법칙과 관련하여서는 소극적 진실주의가 헌법적으로 보장되어 있으므로, 피고인은 형사소송절차에서 검사에 대하여 무기대등의 원칙이 보장되는 절차를 향유할 헌법적 권리를 가진다.","ox":"O","m":"①","c":"A","tp":"형사소송의 기본원칙"},{"y":2023,"e":"국가직 9급","qn":17,"i":"N92023-17-2","t":"형사소송법 제57조제1항은 “공무원이 작성하는 서류에는 법률에 다른 규정이 없는 때에는 작성 연월일과 소속 공무소를 기재하고 기명날인 또는 서명하여야 한다.”라고 규정하고 있다. 여기에서 ‘법률의 다른 규정’에 검찰사건사무규칙은 포함되지 않는다.","ox":"O","m":"②","c":"A","tp":"형사소송의 기본원칙"},{"y":2023,"e":"국가직 9급","qn":17,"i":"N92023-17-3","t":"지방법원 본원과 지방법원 지원 사이의 관할의 분배는 토지관할의 분배가 아니라 지방법원 내부의 사법행정사무로서 행해진 지방법원 본원과 지원 사이의 단순한 사무분배에 해당한다.","ox":"X","m":"③","c":"A","tp":"형사소송의 기본원칙"},{"y":2023,"e":"국가직 9급","qn":17,"i":"N92023-17-4","t":"우리나라 군인이 전시(戰時)에 범한 성폭력범죄의 처벌 등에 관한 특례법 제2조의 성폭력범죄에 대해서는 우리나라 군사법원이 재판권을 가진다.","ox":"O","m":"④","c":"A","tp":"형사소송의 기본원칙"},{"y":2024,"e":"국가직 9급","qn":1,"i":"N92024-01-1","t":"공소제기 전에 검사의 증거보전청구에 의하여 증인신문을 한 법관이 공소제기 후 제1심 법관으로 관여한 경우, 이는 형사소송법상 제척사유에 해당한다.","ox":"X","m":"①","c":"A","tp":"제척과 기피"},{"y":2024,"e":"국가직 9급","qn":1,"i":"N92024-01-2","t":"약식명령을 한 법관이 그 정식재판 절차의 항소심 판결에 관여한 경우, 이는 형사소송법상 제척사유에 해당한다.","ox":"O","m":"②","c":"A","tp":"제척과 기피"},{"y":2024,"e":"국가직 9급","qn":1,"i":"N92024-01-3","t":"법관에 대한 기피신청이 소송의 지연을 목적으로 함이 명백한 경우에는 그 신청 자체가 부적법한 것이므로 신청을 받은 법관은 이를 결정으로 기각할 수 있고, 소송지연을 목적으로 함이 명백한 기피신청인지의 여부는 기피신청인이 제출한 소명방법만에 의하여 판단할 것은 아니고, 당해 법원에 현저한 사실이거나 당해 사건기록에 나타나 있는 제반 사정들을 종합하여 판단할 수 있다.","ox":"O","m":"③","c":"A","tp":"제척과 기피"},{"y":2024,"e":"국가직 9급","qn":1,"i":"N92024-01-4","t":"형사소송법은 전문심리위원의 중립성ㆍ공평성을 확보하기 위하여 법관의 제척 및 기피에 관한 형사소송법 제17조부터 제20조까지 및 제23조를 전문심리위원에 대하여 준용하도록 규정하고 있다.","ox":"O","m":"④","c":"A","tp":"제척과 기피"},{"y":2024,"e":"국가직 9급","qn":6,"i":"N92024-06-1","t":"무죄추정의 원칙은 형사절차뿐만 아니라 기타 일반 법생활영역 에서의 기본권 제한과 같은 경우에도 적용된다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"국가직 9급","qn":6,"i":"N92024-06-2","t":"형사소송법 상의 구속기간은 헌법상의 무죄추정의 원칙에서 파생되는 불구속수사원칙에 대한 예외로서 설정된 기간이다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"국가직 9급","qn":6,"i":"N92024-06-3","t":"구금시설의 소장이 마약류사범인 미결수용자에 대하여 시설의 안전과 질서유지를 위하여 필요한 범위에서 계호를 엄중히 하는 등 다른 미결수용자와 달리 관리할 수 있도록 한 형의 집행 및 수용자의 처우에 관한 법률 규정은 무죄추정의 원칙에 반하지 않는다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"국가직 9급","qn":6,"i":"N92024-06-4","t":"법무부장관이 형사사건으로 공소가 제기된 변호사에 대하여 그 판결이 확정될 때까지 업무정지를 명할 수 있도록 하는 구 변호사법 규정은 무죄추정의 원칙에 반하지 않는다.","ox":"X","m":"④","c":"A"},{"y":2024,"e":"국가직 9급","qn":14,"i":"N92024-14-1","t":"피고인은 소송계속 중의 관계 서류 또는 증거물을 열람하거나 복사할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"국가직 9급","qn":14,"i":"N92024-14-2","t":"피고인은 증인신문에 참여할 수 있으나 증인을 직접 신문할 수 없고 그를 대신하여 변호인이 신문하여야 한다.","ox":"X","m":"②","c":"A"},{"y":2024,"e":"국가직 9급","qn":14,"i":"N92024-14-3","t":"피고인은 증거조사에 관하여 법령의 위반이 있거나 상당하지 아니함을 이유로 하여 이의신청을 할 수 있고, 증거조사의 결과에 대하여 의견을 개진할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"국가직 9급","qn":14,"i":"N92024-14-4","t":"피고인은 피고인신문절차에서 진술하지 아니하거나 개개의 질문에 대하여 진술을 거부할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"국가직 9급","qn":4,"i":"N92025-04-1","t":"재판기관과 수사기관ㆍ소추기관을 분리하여 소추기관의 공소제기에 의하여 법원이 절차를 개시하는 형사소송구조를 탄핵주의라고 한다.","ox":"O","m":"①","c":"A","tp":"형사절차"},{"y":2025,"e":"국가직 9급","qn":4,"i":"N92025-04-2","t":"형사소송법에 따르면 검사는 형법 제51조(양형의 조건)의 사항을 참작하여 공소를 제기하지 않을 수 있지만, 일단 공소를 제기하여 공소장 부본이 피고인 또는 변호인에게 송달된 후에는 제1심 판결의 선고 전이라도 공소를 취소할 수 없다.","ox":"X","m":"②","c":"A","tp":"형사절차"},{"y":2025,"e":"국가직 9급","qn":4,"i":"N92025-04-3","t":"변호인은 피고인의 명시한 의사에 반하지 않는 때만 법관에 대한 기피의 신청을 할 수 있다.","ox":"O","m":"③","c":"A","tp":"형사절차"},{"y":2025,"e":"국가직 9급","qn":4,"i":"N92025-04-4","t":"공정거래위원회의 고발을 소추조건으로 하는 독점규제및공정 거래에관한법률위반죄에는 고소의 주관적 불가분의 원칙이 유추 적용되지 않는다.","ox":"O","m":"④","c":"A","tp":"형사절차"},{"y":2025,"e":"국가직 9급","qn":11,"i":"N92025-11-1","t":"형사소송규칙에 따르면 공소장에는 소정의 서류 외에 사건에 관하여 법원에 예단이 생기게 할 수 있는 서류 기타 물건을 첨부하거나 그 내용을 인용하여서는 안 되는바, 이는 당사자주의 소송구조의 표지이다.","ox":"O","m":"①","c":"A","tp":"당사자주의 및 직권주의"},{"y":2025,"e":"국가직 9급","qn":11,"i":"N92025-11-2","t":"치료감호 등에 관한 법률에 따르면 법원은 공소제기된 사건의 심리 결과 치료감호를 할 필요가 있다고 인정할 때에는 검사에게 치료감호 청구를 요구할 수 있는바, 이는 치료감호사건의 절차에 관해 직권주의적 요소를 가미한 것이다.","ox":"O","m":"②","c":"A","tp":"당사자주의 및 직권주의"},{"y":2025,"e":"국가직 9급","qn":11,"i":"N92025-11-3","t":"형사소송의 구조를 당사자주의와 직권주의 중 어느 것으로 할 것인가는 입법정책의 문제다.","ox":"O","m":"③","c":"A","tp":"당사자주의 및 직권주의"},{"y":2025,"e":"국가직 9급","qn":11,"i":"N92025-11-4","t":"검사가 공소를 제기한 후 참고인을 소환하여 피고인에게 불리한 진술을 기재한 진술조서를 작성하여 이를 공판절차에 증거로 제출할 수 있게 하더라도 당사자주의에 반하지 않는다.","ox":"X","m":"④","c":"A","tp":"당사자주의 및 직권주의"},{"y":2025,"e":"국가직 9급","qn":12,"i":"N92025-12","t":"이해가 상반된 피고인 甲, 乙 중 甲이 법무법인을 변호인 으로 선임하고, 법무법인이 담당 변호사를 지정하였을 때, 법원이 그 담당 변호사 중 1인을 乙을 위한 국선변호인으로 선정하는 것은 국선변호인의 조력을 받을 乙의 권리를 침해하는 것이다.","c":"A","mc":{"s":"이해가 상반된 피고인 甲, 乙 중 甲이 법무법인을 변호인 으로 선임하고, 법무법인이 담당 변호사를 지정하였을 때, 법원이 그 담당 변호사 중 1인을 乙을 위한 국선변호인으로 선정하는 것은 국선변호인의 조력을 받을 乙의 권리를 침해하는 것이다.","d":"국선변호인에 대한 설명으로 옳은 것만을 모두 고르면?\nㄱ. 단기 3년 이상의 징역에 해당하는 사건으로 기소된 피고인 에게 변호인이 없으면 법원은 직권으로 변호인을 선정해야 하며, 이에 따라 변호인이 선정된 사건에 관하여는 변호인 없이는 개정할 수 없고 이는 판결만을 선고하는 경우에도 마찬가지이다.\nㄴ. 법원은 피고인이 빈곤이나 그 밖의 사유로 변호인을 선임할 수 없는 경우에 피고인이 청구하면 변호인을 선정하여야 한다.\nㄷ. 구속 전 피의자심문에서 심문할 피의자에게 변호인이 없는 때에는 지방법원판사는 직권으로 변호인을 선정하여야 하며, 이 경우 변호인의 선정은 피의자에 대한 구속영장 청구가 기각되어 효력이 소멸한 경우를 제외하고는 제1심 까지 효력이 있다. ㄹ.","o":["ㄷ","ㄱ, ㄴ","ㄱ, ㄹ","ㄴ, ㄷ, ㄹ 2025년도 국가공무원 9급 공채 필기시험 형"],"a":4}},{"y":2025,"e":"국가직 9급","qn":13,"i":"N92025-13-1","t":"형사소송법 제15조제1호에 따르면 관할법원이 법률상의 이유 또는 특별한 사정으로 재판권을 행할 수 없는 때 피고인은 관할 이전의 신청을 할 수 있지만, 항소심에서 유죄판결을 선고받고 이에 불복하여 상고를 제기한 피고인을 교도소 소장이 검사의 이송지휘 없이 다른 교도소로 이송처분한 경우에는 피고인은 이에 대하여 관할이전신청을 할 수 없다.","ox":"O","m":"①","c":"A","tp":"법원의 관할"},{"y":2025,"e":"국가직 9급","qn":13,"i":"N92025-13-2","t":"항소심에서 공소장변경에 따라 단독판사 관할사건이 합의부 관할사건으로 변경된 경우, 그 합의부 관할사건에 대한 관할권이 있는 법원은 고등법원이라고 보아야 한다.","ox":"O","m":"②","c":"A","tp":"법원의 관할"},{"y":2025,"e":"국가직 9급","qn":13,"i":"N92025-13-3","t":"제1심에서 합의부 관할사건이 공소장변경에 따라 단독판사 관할 사건으로 변경된 경우, 사건을 배당받은 합의부는 이를 단독판사에게 재배당해야 한다.","ox":"X","m":"③","c":"A","tp":"법원의 관할"},{"y":2025,"e":"국가직 9급","qn":13,"i":"N92025-13-4","t":"형사소송법 제5조에 따르면 토지관할을 달리하는 여러 개의 사건이 관련된 때에는 1개의 사건에 관하여 관할권 있는 법원은 다른 사건까지 관할할 수 있는바, 이에 따른 관련 사건의 관할은, 이른바 고유관할사건 및 그 관련 사건이 반드시 병합기소되거나 병합되어 심리될 것을 전제 요건으로 하는 것은 아니다.","ox":"O","m":"④","c":"A","tp":"법원의 관할"}],"4":[{"y":2015,"e":"국가직 9급","qn":4,"i":"N92015-04-1","t":"교도소 또는 구치소에 구속된 자에 대한 송달은 그 소장에게 송달하면 구속된 자에게 전달되었는지 여부와 관계없이 효력이 발생한다.","ox":"O","m":"①","c":"A","tp":"공소장의 송달"},{"y":2015,"e":"국가직 9급","qn":4,"i":"N92015-04-2","t":"공소장변경 허가신청서가 제출된 경우 법원은 그 부본을 피고인과 변호인에게 각각 즉시 송달하여야 한다.","ox":"X","m":"②","c":"A","tp":"공소장의 송달"},{"y":2015,"e":"국가직 9급","qn":4,"i":"N92015-04-3","t":"피고인이 주소지인 사무소에 나가지 아니하여 그 사무소로 송달된 약식명령을 송달받지 못한 것은 정식재판청구권회복 청구의 사유가 될 수 없다.","ox":"O","m":"③","c":"A","tp":"공소장의 송달"},{"y":2015,"e":"국가직 9급","qn":4,"i":"N92015-04-4","t":"법원은 주거, 사무소, 현재지 등 소재가 확인되지 않는 피고인에 대하여 공시송달을 할 때에는 검사에게 주소보정을 요구하거나 기타 필요한 조치를 취하여 피고인의 수감 여부를 확인할 필요가 있다.","ox":"O","m":"④","c":"A","tp":"공소장의 송달"},{"y":2015,"e":"국가직 9급","qn":15,"i":"N92015-15","t":"공소사실의 특정이 인정되는 것은?","c":"A","mc":{"s":"공소사실의 특정이 인정되는 것은?","d":"","o":["마약류 관리에 관한 법률 위반사건에서 범행일시를 모발감정 결과에 기초하여 투약가능기간을 역으로 추정한 ‘2010. 11.경’ 으로, 투약장소를 시(市)와 구(區)까지 기재한 때","변호사법 위반사건에서 ‘2006. 12. 14.경부터 2007. 2. 15.경 까지 2회에 걸쳐 합계 5,000만원을 받았다’고 기재한 때","각 세금계산서마다 하나의 죄가 성립하는 구 조세범처벌법 상 무거래 세금계산서 교부죄에 있어서 세금계산서의 총 매수와 그 공급가액의 합계액만을 기재한 때","수인의 피해자에 대하여 각 별로 기망행위를 하여 각각 재물을 편취한 사기죄에 있어서 ‘일정한 기간 사이에 성명불상의 고객들에게 1일 평균 매상액 상당을 판매하여 그 대금 상당액을 편취하였다’고 기재한 때"],"a":2}},{"y":2016,"e":"국가직 9급","qn":3,"i":"N92016-03-1","t":"형법에 의하여 형을 가중 또는 감경하는 경우에는 가중 또는 감경한 형에 의하여 공소시효 기간을 정한다.","ox":"X","m":"①","c":"A"},{"y":2016,"e":"국가직 9급","qn":3,"i":"N92016-03-2","t":"공범의 1인에 대한 공소시효의 정지는 다른 공범자에게 효력이 미치고, 당해 사건의 최종행위가 종료한 때로부터 진행한다.","ox":"X","m":"②","c":"A"},{"y":2016,"e":"국가직 9급","qn":3,"i":"N92016-03-3","t":"공소시효의 정지사유인 ‘범인이 형사처분을 면할 목적으로 국외에 있는 경우’에는 범인이 국외에서 범죄를 저지르고 형사처분을 면할 목적으로 국외에서 체류를 계속하는 경우가 포함되지 아니한다.","ox":"X","m":"③","c":"A"},{"y":2016,"e":"국가직 9급","qn":3,"i":"N92016-03-4","t":"형사소송법 제253조 제2항에서 말하는 공소시효 정지의 효력이 미치는 ‘공범’에는 뇌물공여죄와 뇌물수수죄 사이와 같은 대향범 관계에 있는 자는 포함되지 않는다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"국가직 9급","qn":4,"i":"N92016-04-1","t":"살인죄의 공소사실을 폭행치사죄의 범죄사실로 인정하는 경우 축소사실의 인정이므로 공소장변경은 필요하지 않다.","ox":"X","m":"①","c":"A"},{"y":2016,"e":"국가직 9급","qn":4,"i":"N92016-04-2","t":"공소사실 또는 적용법조의 추가, 철회 또는 변경의 허가에 관한 결정은 판결 전의 소송절차에 관한 결정이라 할 것이므로, 그 결정을 함에 있어서 저지른 위법이 판결에 영향을 미친 경우에 한하여 그 판결에 대하여 상소를 하여 다툼으로써 불복 하는 외에는 당사자가 이에 대하여 독립하여 상소할 수 없다.","ox":"O","m":"②","c":"A","tp":"공소장변경"},{"y":2016,"e":"국가직 9급","qn":4,"i":"N92016-04-3","t":"공소장변경은 제1심뿐만 아니라 항소심에서도 허용된다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"국가직 9급","qn":4,"i":"N92016-04-4","t":"법원은 심리의 경과에 비추어 상당하다고 인정할 때에는 공소사실 또는 적용법조의 추가 또는 변경을 요구하여야 한다.","ox":"O","m":"④","c":"A","tp":"공소장변경"},{"y":2016,"e":"국가직 9급","qn":11,"i":"N92016-11-1","t":"기소유예 처분에 대해서도 재정신청을 할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"국가직 9급","qn":11,"i":"N92016-11-2","t":"공동신청권자 중 1인의 신청은 그 전원을 위하여 효력을 발생하나, 그 취소의 경우에는 다른 공동신청권자에게 효력을 미치지 아니한다.","ox":"O","m":"②","c":"A","tp":"재정신청"},{"y":2016,"e":"국가직 9급","qn":11,"i":"N92016-11-3","t":"법원은 재정신청서를 송부받은 때에는 송부받은 날부터 10일 이내에 피의자에게 그 사실을 통지하여야 한다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"국가직 9급","qn":11,"i":"N92016-11-4","t":"법원의 공소제기 결정에 따라 검사가 공소를 제기한 경우에도 검사는 공소를 취소할 수 있다.","ox":"X","m":"④","c":"A","tp":"재정신청"},{"y":2017,"e":"국가직 9급","qn":13,"i":"N92017-13-1","t":"범죄 후 법률의 개정에 의하여 법정형이 가벼워진 경우에는 형법 제1조제2항에 의하여 당해 범죄사실에 적용될 가벼운 신법의 법정형이 공소시효기간의 기준이 된다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"국가직 9급","qn":13,"i":"N92017-13-2","t":"정보통신망을 이용한 명예훼손의 경우 게재행위만으로 범죄가 성립하고 종료하므로 그때부터 공소시효를 기산해야 하고, 게시물이 삭제된 시점을 범죄의 종료시기로 보아서 그때부터 공소시효를 기산해야 하는 것은 아니다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"국가직 9급","qn":13,"i":"N92017-13-3","t":"공범 중 1인에 대해 약식명령이 확정된 후 그에 대한 정식재판 청구권회복결정이 있었다면 그 사이의 기간 동안에는 특별한 사정이 없는 한 다른 공범자에 대한 공소시효가 정지된다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"국가직 9급","qn":13,"i":"N92017-13-4","t":"변호사법위반죄의 공소시효가 완성되었다고 하여도 그 죄와 상상적 경합관계에 있는 사기죄의 공소시효까지 완성되는 것은 아니다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"국가직 9급","qn":14,"i":"N92017-14-1","t":"고등법원은 재정신청서를 송부받은 날부터 3개월 이내에 항고의 절차에 준하여 기각 또는 공소제기의 결정을 하여야 하고, 필요한 때에는 증거를 조사할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"국가직 9급","qn":14,"i":"N92017-14-2","t":"고등법원이 공소제기를 결정한 경우 검사는 그 결정에 대해서는 불복할 수 없으며, 기각결정이 확정된 사건에 대하여는 다른 중요한 증거를 발견한 경우를 제외하고는 소추할 수 없다.","ox":"O","m":"②","c":"A","tp":"재정신청"},{"y":2017,"e":"국가직 9급","qn":14,"i":"N92017-14-3","t":"재정신청인이 그 신청을 취소한 경우 고등법원은 결정으로 재정신청인에게 신청절차에 의하여 생긴 비용의 전부 또는 일부를 부담하게 할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"국가직 9급","qn":14,"i":"N92017-14-4","t":"재정신청인이 교도소에 수감되어 있는 경우 재정신청 기각결정에 대한 재항고의 법정기간 준수 여부는 재항고장을 교도소장에게 제출한 시점을 기준으로 판단하여야 한다.","ox":"X","m":"④","c":"A"},{"y":2018,"e":"국가직 9급","qn":4,"i":"N92018-04-1","t":"피의자가 다른 사람의 성명을 모용하였기 때문에 공소장에 피모용자가 피고인으로 표시되었다고 하면, 검사는 모용자에 대하여 공소를 제기한 것이므로 모용자가 피고인이 된다.","ox":"O","m":"①","c":"A","tp":"피고인의 특정"},{"y":2018,"e":"국가직 9급","qn":4,"i":"N92018-04-2","t":"성명을 모용한 사실이 재판 중에 밝혀진 경우 검사는 공소장 변경절차를 거쳐 피고인의 인적사항을 변경하여야 한다.","ox":"X","m":"②","c":"A","tp":"피고인의 특정"},{"y":2018,"e":"국가직 9급","qn":4,"i":"N92018-04-3","t":"피모용자가 약식명령에 대하여 정식재판을 청구함으로써 정식재판 절차에서 성명모용사실이 판명된 경우와 같이 피모용자에게 사실상의 소송계속이 발생하고 형식상 또는 외관상 피고인의 지위를 갖게 된 경우 법원은 그에게 공소기각의 판결을 선고하여야 한다.","ox":"O","m":"③","c":"A","tp":"피고인의 특정"},{"y":2018,"e":"국가직 9급","qn":4,"i":"N92018-04-4","t":"검사가 공소장의 피고인 성명모용을 바로잡지 아니한 경우에는 공소제기의 방식이 형사소송법의 규정에 위반하여 무효이므로 법원은 공소기각의 판결을 선고하여야 한다.","ox":"O","m":"④","c":"A","tp":"피고인의 특정"},{"y":2018,"e":"국가직 9급","qn":6,"i":"N92018-06","t":"공소제기에 대한 설명으로 옳은 것은?","c":"A","mc":{"s":"공소제기에 대한 설명으로 옳은 것은?","d":"","o":["현행법은 기소편의주의를 취하고 있기 때문에 설사 검사가 고의로 공소권을 남용해서 피고인에게 실질적인 불이익을 주더라도 공소제기의 효력을 부인할 수는 없다.","수소법원은 늦어도 제1회 공판기일 전 5일까지는 피고인 또는 변호인에게 공소장 부본을 송달하여야 한다.","검사가 기명날인만 있고 자필서명이 없는 공소장을 법원에 제출한 경우, 공소를 제기한 검사가 제1심의 제1회 공판기일에 공판검사로 출석해서 기소요지를 진술하고 공소장에 서명을 추가하더라도 이러한 공소제기는 무효이다.","동일한 사건에 대해 동일한 법원에 이중으로 공소가 제기된 때에는 법원으로서는 후소에 대해 공소기각의 결정을 하여야 한다. 형사"],"a":2}},{"y":2019,"e":"국가직 9급","qn":6,"i":"N92019-06","t":"소송행위에 대한 설명으로 옳은 것은?","c":"A","mc":{"s":"소송행위에 대한 설명으로 옳은 것은?","d":"","o":["송달 당시 영수인이 10세 정도라면 송달로 인하여 생기는 형사소송절차에 있어서의 효력까지 이해하였다고 볼 수는 없으나 그 송달 자체의 취지를 이해하고 이를 아버지인 피고인 에게 교부하는 것을 기대할 수 있으므로 피고인에 대한 소송 기록접수통지서의 송달은 적법하다.","피고인이 공판정에 재정하지 않더라도 피고인에게 이익이 되는 경우라면 구술에 의한 공소장변경을 허가할 수 있다.","경찰서장의 청구에 의해 즉결심판을 받은 피고인으로부터 적법한 정식재판의 청구가 있는 경우, 경찰서장의 즉결심판 청구는 공소제기와 동일한 소송행위라고 할 수 없고 검사의 공소제기에 의하여 심판하여야 한다.","검사가 공소사실의 일부가 되는 범죄일람표를 컴퓨터 프로그램을 통하여 열어보거나 출력할 수 있는 전자적 형태의 문서로 작성한 후, 종이문서로 출력하여 제출하지 아니하고 위 전자적 형태의 문서가 저장된 저장매체 자체를 서면인 공소장에 첨부하여 제출한 경우, 그 저장매체나 전자적 형태의 문서를 공소장의 일부로서의 ‘서면’으로 볼 수 있다. 2019년도 국가공무원 9급 공채 필기시험 형사"],"a":1}},{"y":2019,"e":"국가직 9급","qn":7,"i":"N92019-07-1","t":"약식명령에 대한 정식재판청구가 제기되었음에도 법원이 증거서류 및 증거물을 검사에게 반환하지 않고 보관하고 있다고 하여 그 이전에 이미 적법하게 제기된 공소제기의 절차가 위법하게 된다고 할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"국가직 9급","qn":7,"i":"N92019-07-2","t":"포괄일죄에서 공소장변경 허가 여부를 결정할 때는 포괄일죄를 구성하는 개개 공소사실별로 종전 것과의 동일성 여부를 판단하여야 한다.","ox":"X","m":"②","c":"A","tp":"공소제기"},{"y":2019,"e":"국가직 9급","qn":7,"i":"N92019-07-3","t":"살인, 방화 등의 경우 범죄의 직접적인 동기 또는 공소범죄 사실과 밀접불가분의 관계에 있는 동기를 공소사실에 기재하는 것이 공소장일본주의 위반이 아님은 명백하고, 설사 범죄의 직접적인 동기가 아닌 경우에도 동기의 기재는 공소장의 효력에 영향을 미치지 아니한다.","ox":"O","m":"③","c":"A","tp":"공소제기"},{"y":2019,"e":"국가직 9급","qn":7,"i":"N92019-07-4","t":"불특정 다수 인터넷 이용자들의 컴퓨터에 자신들의 프로그램을 설치하여 경쟁업체 프로그램이 정상적으로 사용되거나 설치 되지 못하도록 함으로써 인터넷 이용자들의 인터넷 이용에 관한 업무를 방해하였다고 하여 ‘컴퓨터등장애업무방해’로 기소된 경우, 공소장 기재만으로는 업무 주체인 구체적인 피해자와 방해된 업무 내용을 알 수 없는 때는 공소사실이 특정되지 않은 것이다.","ox":"O","m":"④","c":"A","tp":"공소제기"},{"y":2019,"e":"국가직 9급","qn":9,"i":"N92019-09-1","t":"검사가 형이보다 가벼운 일반법의 법조를 적용하여 그 죄명으로 기소한 경우, 공소사실에 변경이 없고 그 적용법조의 구성요건이 완전히 동일하다면 법원은 공소장변경 없이 형이 더 무거운 특별법의 법조를 적용하여 처벌할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2019,"e":"국가직 9급","qn":9,"i":"N92019-09-2","t":"단독범으로 기소된 것을 다른 사람과 공모하여 동일한 내용으로 공동정범의 범행을 한 것으로 인정하는 경우, 이로 말미암아 피고인에게 예기치 않은 타격을 주어 방어권 행사에 실질적 불이익을 줄 우려가 없더라도 공소장변경이 필요하다.","ox":"X","m":"②","c":"A"},{"y":2019,"e":"국가직 9급","qn":9,"i":"N92019-09-3","t":"기소된 공소사실의 재산상 피해자와 공소장에 기재된 피해자가 다른 것으로 판명된 경우에는 공소사실의 동일성을 해하지 않고 피고인의 방어권 행사에 실질적 불이익을 주지 않는 한 공소장변경 없이 공소장 기재의 피해자와 다른 실제의 피해자를 적시하여 이를 유죄로 인정해야 한다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"국가직 9급","qn":9,"i":"N92019-09-4","t":"동일한 범죄사실에 대하여 포괄일죄로 기소된 것을 법원이 공소장변경 없이 실체적 경합관계에 있는 수죄로 인정하는 것은 피고인의 방어권 행사에 실질적으로 불이익을 초래할 우려가 있어서 허용되지 아니한다.","ox":"X","m":"④","c":"A"},{"y":2019,"e":"국가직 9급","qn":14,"i":"N92019-14-1","t":"재정신청 기각결정에 대한 재항고나 그 재항고 기각결정에 대한 즉시항고로서의 재항고에 대한 법정기간의 준수 여부는 재항고장이나 즉시항고장이 법원에 도달한 시점을 기준으로 판단하여야 하고, 거기에 재소자 피고인 특칙은 준용되지 아니한다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"국가직 9급","qn":14,"i":"N92019-14-2","t":"재정신청사건의 심리 중에는 관련 서류 및 증거물을 열람 또는 등사할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2019,"e":"국가직 9급","qn":14,"i":"N92019-14-3","t":"공동신청권자 중 1인의 재정신청 및 취소는 전원을 위하여 효력을 발생한다.","ox":"X","m":"③","c":"A"},{"y":2019,"e":"국가직 9급","qn":14,"i":"N92019-14-4","t":"법원이 재정신청 대상 사건이 아닌 공직선거법 제251조의 후보자비방죄에 관한 재정신청임을 간과한 채 공소제기결정을 한 관계로 그에 따른 공소가 제기되어 본안사건의 절차가 개시되었다면, 다른 특별한 사정이 없는 한 그 본안사건에서 그 잘못을 다툴 수 있다.","ox":"X","m":"④","c":"A"},{"y":2020,"e":"국가직 9급","qn":4,"i":"N92020-04-1","t":"약속어음거래에서 백지식 배서나 교부에 의한 양도를 한 경우라도 위조유가증권행사죄의 범죄사실에 어음거래의 상대방이나 이로 인한 피해자가 성명불상자로만 표시되어 있다면 공소사실의 특정은 인정되지 않는다.","ox":"X","m":"①","c":"A"},{"y":2020,"e":"국가직 9급","qn":4,"i":"N92020-04-2","t":"사문서변조의 공소사실에 변조행위의 일시·장소와 방법, 변조의 실행행위자 등이 기재되지 않은 경우라면 공소사실의 특정은 인정되지 않는다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"국가직 9급","qn":4,"i":"N92020-04-3","t":"저작재산권 침해행위에 관한 공소사실에 침해대상인 저작물 및 침해방법의 종류, 형태 등 침해행위의 내용이 명확하게 기재되어 있어 피고인의 방어권 행사에 지장이 없는 정도라면 각 저작물의 저작재산권자가 누구인지 특정되지 않더라도 공소사실의 특정은 인정될 수 있다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"국가직 9급","qn":4,"i":"N92020-04-4","t":"교사범이나 방조범의 경우에는 교사나 방조의 사실뿐만 아니라 정범의 범죄구성을 충족하는 구체적 사실을 공소장에 기재하여야 한다.","ox":"O","m":"④","c":"A","tp":"공소사실의 특정"},{"y":2020,"e":"국가직 9급","qn":17,"i":"N92020-17","t":"수사가 장차 고소나 고발의 가능성이 없는 상태 하에서 행해졌다는 등의 특단의 사정이 없는 한, 고소나 고발이 있기 전에 수사를 하였다는 이유만으로 그 수사가 위법하게 되는 것은 아니다.","c":"A","mc":{"s":"수사가 장차 고소나 고발의 가능성이 없는 상태 하에서 행해졌다는 등의 특단의 사정이 없는 한, 고소나 고발이 있기 전에 수사를 하였다는 이유만으로 그 수사가 위법하게 되는 것은 아니다.","d":"친고죄의 고소에 대한 설명으로 옳은 것만을 모두 고르면? (다툼이 있는 경우 판례에 의함)\nㄱ. 친고죄가 아닌 범죄로 기소되었으나 항소심에서 공소장의 변경에 의하여 친고죄로 인정된 경우, 고소인이 공소제기 전에 행한 고소를 항소심에서 취소하면 법원은 공소기각의 판결을 선고하여야 한다.\nㄴ. 수사기관이 고소권이 있는 자를 증인 또는 피해자로서 신문한 경우에는 그 진술에 범인의 처벌을 요구하는 의사표시가 포함되어 있고 그 의사표시가 조서에 기재되어 있더라도 이는 고소로서 유효하지 않다.\nㄷ.\nㄹ. 친고죄에 있어서 피해자의 고소권은 공법상의 권리로서 법이 특히 명문으로 인정하는 경우를 제외하고는 고소 전에 고소권을 포기할 수 없다.","o":["ㄱ, ㄴ","ㄴ, ㄷ","ㄷ, ㄹ","ㄱ, ㄷ, ㄹ 2020년도 국가공무원 9급 공채 필기시험 형사"],"a":3}},{"y":2021,"e":"국가직 9급","qn":3,"i":"N92021-03-1","t":"2개 이상의 형을 병과하거나 2개 이상의 형에서 그 1개를 과할 범죄에는 중한 형에 의하여 공소시효의 기간을 결정한다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"국가직 9급","qn":3,"i":"N92021-03-2","t":"범인이 국외에서 범죄를 저지르고 형사처분을 면할 목적으로 국외에서 체류를 계속하는 경우에도 공소시효는 정지된다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"국가직 9급","qn":3,"i":"N92021-03-3","t":"공범 중 1인에 대해 약식명령이 확정된 후 그에 대한 정식재판 청구권회복결정이 있었다고 하더라도 그 사이의 기간 동안에는 특별한 사정이 없는 한 다른 공범자에 대한 공소시효는 정지함이 없이 계속 진행한다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"국가직 9급","qn":3,"i":"N92021-03-4","t":"공소제기 후 공소장이 변경된 경우 변경된 공소사실에 대한 공소시효의 완성여부는 공소장 변경시점을 기준으로 판단하여야 한다.","ox":"X","m":"④","c":"A"},{"y":2021,"e":"국가직 9급","qn":12,"i":"N92021-12","t":"공소장변경에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"공소장변경에 대한 설명으로 옳지 않은 것은?","d":"","o":["약식명령에 대하여 피고인만 정식재판을 청구한 사건에서 법정형에 유기징역형만 있는 범죄로 공소장을 변경하는 것은 공소사실의 동일성이 인정되더라도 허용될 수 없다.","법원은 공소사실의 동일성이 인정되는 범위 내에서 심리의 경과 등에 비추어 피고인의 방어권 행사에 실질적인 불이익을 주는 것이 아니라면 공동정범으로 기소된 범죄사실을 방조사실로 인정할 수 있다.","공소사실의 동일성이 인정되지 않는 등의 사유로 공소장변경 허가결정에 위법사유가 있는 경우에는 공소장변경허가를 한 법원 스스로 이를 취소할 수 있다.","검사의 공소장변경 신청이 공소사실의 동일성을 해하지 아니하는 한 법원은 이를 허가하여야 한다. 2021년도 국가공무원 9급 공채 필기시험 형사"],"a":1}},{"y":2021,"e":"국가직 9급","qn":16,"i":"N92021-16-1","t":"친고죄에서 고소취소의 의사표시는 공소제기 전에는 고소사건을 담당하는 수사기관에, 공소제기 후에는 고소사건의 수소법원에 대하여 이루어져야 한다.","ox":"O","m":"①","c":"A","tp":"소송조건"},{"y":2021,"e":"국가직 9급","qn":16,"i":"N92021-16-2","t":"고소를 함에 있어서 고소인은 범죄사실을 특정하여 신고하면 족하며, 범인이 누구인지, 나아가 범인 중 처벌을 구하는 자가 누구인지를 적시할 필요는 없다.","ox":"O","m":"②","c":"A","tp":"소송조건"},{"y":2021,"e":"국가직 9급","qn":16,"i":"N92021-16-3","t":"친고죄의 공범 중 그 일부에 대하여 제1심 판결이 선고된 후에는 제1심 판결 선고 전의 다른 공범자에 대하여는 그 고소를 취소할 수 없고, 그 고소의 취소가 있다 하더라도 그 효력을 발생할 수 없으며, 이러한 법리는 필요적 공범과 임의적 공범 모두에 적용된다.","ox":"O","m":"③","c":"A","tp":"소송조건"},{"y":2021,"e":"국가직 9급","qn":16,"i":"N92021-16-4","t":"친고죄에서 고소는 제1심 판결 선고 전까지 취소할 수 있으므로, 상소심에서 제1심 공소기각판결을 파기하고 이 사건을 제1심 법원에 환송함에 따라 다시 제1심 절차가 진행된 때에는 환송 후의 제1심 판결 선고 전이라도 고소를 취소할 수 없다.","ox":"X","m":"④","c":"A","tp":"소송조건"},{"y":2023,"e":"국가직 9급","qn":2,"i":"N92023-02-1","t":"피고인이 타인의 성명을 모용한 경우 검사가 공소장의 피고인 표시를 정정함에 있어 공소장변경의 절차를 밟을 필요는 없지만 법원의 허가를 요한다.","ox":"X","m":"①","c":"A","tp":"피고인의 특정 및 성명모용"},{"y":2023,"e":"국가직 9급","qn":2,"i":"N92023-02-2","t":"피고인이 타인의 성명을 모용한 사실이 공판심리 중에 밝혀졌는데도 검사가 공소장의 피고인 표시를 정정하여 모용관계를 바로잡지 아니하면 법원은 공소기각의 판결을 하여야 한다.","ox":"O","m":"②","c":"A","tp":"피고인의 특정 및 성명모용"},{"y":2023,"e":"국가직 9급","qn":2,"i":"N92023-02-3","t":"검사는 공소장에 피고인을 특정할 수 있는 사항을 기재해야 하고, 공소제기의 효력은 검사가 피고인으로 지정한 사람에게만 미친다.","ox":"O","m":"③","c":"A","tp":"피고인의 특정 및 성명모용"},{"y":2023,"e":"국가직 9급","qn":2,"i":"N92023-02-4","t":"법원이 성명모용사실을 알지 못하여 외형상으로는 피모용자에 대해 유죄판결을 선고하거나 판결이 확정되어도 그 판결의 효력은 모용자에게만 미치고 피모용자에게는 미치지 않는다.","ox":"O","m":"④","c":"A","tp":"피고인의 특정 및 성명모용"},{"y":2023,"e":"국가직 9급","qn":3,"i":"N92023-03-1","t":"반의사불벌죄의 피해자는 피의자나 피고인 및 그들의 변호인에게 자신을 대리하여 수사기관이나 법원에 자신의 처벌불원의사를 표시할 수 있는 권한을 수여할 수 없다.","ox":"X","m":"①","c":"A"},{"y":2023,"e":"국가직 9급","qn":3,"i":"N92023-03-2","t":"항소심에 이르러 반의사불벌죄가 아닌 죄에서 반의사불벌죄로 공소장이 변경된 경우에는 예외적으로 항소심에서도 처벌을 희망하는 의사표시를 철회할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"국가직 9급","qn":3,"i":"N92023-03-3","t":"반의사불벌죄에서 피고인 또는 피의자의 처벌을 희망하지 않는다는 의사표시 또는 처벌희망 의사표시 철회의 유무나 그 효력 여부에 관한 사실은 엄격한 증명의 대상이다.","ox":"X","m":"③","c":"A"},{"y":2023,"e":"국가직 9급","qn":3,"i":"N92023-03-4","t":"반의사불벌죄의 경우에 처벌불원의 의사표시는 의사능력이 있는 피해자가 단독으로 할 수 있는 것이고, 피해자가 사망한 후 그 상속인이 피해자를 대신하여 처벌불원의 의사표시를 할 수는 없다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"국가직 9급","qn":7,"i":"N92023-07","t":"공소장변경에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"공소장변경에 대한 설명으로 옳지 않은 것은?","d":"","o":["검사가 제출한 공소장변경허가신청서 부본을 즉시 피고인에게 송달하지 않은 채 법원이 공판절차를 진행한 조치는 절차상의 법령위반에 해당하나, 그러한 경우에도 피고인의 방어권이나 변호인의 변호권 등이 본질적으로 침해되었다고 볼 정도에 이르지 않는 한 그것만으로 판결에 영향을 미친 위법이라고 할 수 없다.","포괄일죄인 영업범에서 공소제기된 범죄사실과 공판심리 중에 추가로 발견된 범죄사실 사이에 그 범죄사실들과 동일성이 인정되는 또 다른 범죄사실에 대한 유죄의 확정판결이 있더라도 추가로 발견된 범죄사실을 공소장변경절차에 의하여 공소사실로 추가 할 수 있다.","상고심에서 원심판결을 파기하고 사건을 항소심에 환송한 경우, 환송받은 항소심에서도 공소장변경이 허용된다.","검사가 공소장변경을 하고자 하는 경우, 피고인이 재정하는 공판정에서는 피고인에게 이익이 되거나 피고인이 동의하면 법원은 구술에 의한 공소장변경을 허가할 수 있다. 2023년도 국가공무원 9급 공채 필기시험 형사"],"a":2}},{"y":2023,"e":"국가직 9급","qn":10,"i":"N92023-10-1","t":"법원은 재정신청서를 송부받은 때에는 송부받은 날부터 7일 이내에 피의자에게 그 사실을 통지하여야 하고, 재정신청서를 송부받은 날부터 3개월 이내에 항고의 절차에 준하여 결정한다.","ox":"X","m":"①","c":"A"},{"y":2023,"e":"국가직 9급","qn":10,"i":"N92023-10-2","t":"검사의 불기소처분은 물론 진정사건에 대한 입건 전 조사(내사) 종결처분도 재정신청의 대상이 된다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"국가직 9급","qn":10,"i":"N92023-10-3","t":"재정신청인이 자기 또는 대리인이 책임질 수 없는 사유로 인하여 재정신청 기각결정에 대한 재항고 제기기간을 준수하지 못한 경우, 형사소송법 제345조(상소권회복청구권자)에 따라 재항고권 회복을 청구할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"국가직 9급","qn":10,"i":"N92023-10-4","t":"재소자인 재정신청인이 재정신청 기각결정에 불복하여 재항고를 제기하는 경우, 그 제기기간 내에 교도소장이나 구치소장 또는 그 직무를 대리하는 사람에게 재항고장을 제출한 때에 재항고를 한 것으로 간주한다.","ox":"X","m":"④","c":"A"},{"y":2024,"e":"국가직 9급","qn":2,"i":"N92024-02-1","t":"공소장변경이 있는 경우에 공소시효의 완성 여부는 당초의 공소 제기가 있었던 시점을 기준으로 판단할 것이고 공소장변경 시를 기준으로 삼을 것은 아니다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"국가직 9급","qn":2,"i":"N92024-02-2","t":"사기죄가 변호사법위반죄와 상상적 경합관계에 있는 경우, 변호사법위반죄의 공소시효가 완성되었다고 하여 사기죄의 공소 시효까지 완성되는 것은 아니다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"국가직 9급","qn":2,"i":"N92024-02-3","t":"형사소송법 제253조제2항의 ‘공범’을 해석할 때에는 이 조항이 공소제기 효력의 인적 범위를 확장하는 예외를 마련하여 놓은 것이므로 원칙적으로 엄격하게 해석하여야 하고 피고인에게 불리한 방향으로 확장하여 해석해서는 아니 된다.","ox":"O","m":"③","c":"A","tp":"공소시효"},{"y":2024,"e":"국가직 9급","qn":2,"i":"N92024-02-4","t":"형사소송법 제253조제3항이 정한 ‘범인이 형사처분을 면할 목적으로 국외에 있는 경우’는 범인이 국내에서 범죄를 저지르고 형사처분을 면할 목적으로 국외로 도피한 경우에 한정되고, 국외에서 범죄를 저지르고 형사처분을 면할 목적으로 국외에서 체류를 계속하는 경우는 포함되지 않는다.","ox":"X","m":"④","c":"A","tp":"공소시효"},{"y":2024,"e":"국가직 9급","qn":4,"i":"N92024-04-1","t":"피해자가 고소장을 제출하여 처벌을 희망하는 의사를 분명히 표시한 후 고소를 취소한 바 없다면, 비록 고소 전에 피해자가 처벌을 원치 않았다고 하더라도 그 후에 한 피해자의 고소는 유효하다.","ox":"O","m":"①","c":"A","tp":"친고죄의 고소"},{"y":2024,"e":"국가직 9급","qn":4,"i":"N92024-04-2","t":"친고죄에서 피해자의 고소가 없거나 고소가 취소되었음에도 친고죄로 기소되었다가 그 후 당초에 기소된 공소사실과 동일성이 인정되는 비친고죄로 공소장변경이 허용된 경우 그 공소제기의 흠은 치유된다.","ox":"O","m":"②","c":"A","tp":"친고죄의 고소"},{"y":2024,"e":"국가직 9급","qn":4,"i":"N92024-04-3","t":"친고죄의 공범 중 그 일부에 대하여 제1심판결이 선고된 후에는 제1심판결 선고 전의 다른 공범자에 대하여는 그 고소를 취소할 수 없다.","ox":"O","m":"③","c":"A","tp":"친고죄의 고소"},{"y":2024,"e":"국가직 9급","qn":4,"i":"N92024-04-4","t":"친고죄의 공범자 간 고소불가분의 원칙은 반의사불벌죄에서 처벌을 희망하지 아니하는 의사표시나 처벌을 희망하는 의사표시의 철회에 관하여도 적용된다.","ox":"X","m":"④","c":"A","tp":"친고죄의 고소"},{"y":2024,"e":"국가직 9급","qn":13,"i":"N92024-13","t":"공소제기와 법원의 심판대상에 대한 설명으로 옳은 것은?","c":"A","mc":{"s":"공소제기와 법원의 심판대상에 대한 설명으로 옳은 것은?","d":"","o":["공소장일본주의에 위반되는 공소제기에 대하여 피고인 측으로부터 유효한 이의가 제기되어 있더라도 법원이 그대로 공판절차를 진행한 결과 증거조사절차가 마무리되어 법관의 심증형성이 이루어진 단계에서는 공소장일본주의 위배를 주장하여 이미 진행된 소송절차의 효력을 다툴 수 없다.","항소법원은 항소이유에 포함된 사유에 관하여 심판하여야 하므로 판결에 영향을 미친 사유에 해당하더라도 항소이유서에 포함되지 아니한 경우에는 심판할 수 없다.","하나의 형이 확정된 경합범 중 일부 범죄사실에 대해 재심사유가 있는 경우 재심개시결정의 효력은 재심사유가 없는 범죄사실을 형식적으로 심판의 대상에 포함시키는 것에 불과하므로 재심법원 으로서는 재심사유가 없는 범죄사실을 다시 심리하여 유죄 인정을 파기할 수 없고, 양형을 위하여 필요한 범위에 한하여만 심리할 수 있다.","동일한 사실관계에 대하여 서로 양립할 수 없는 적용법조의 적용을 주위적ㆍ예비적으로 구하는 경우, 예비적 공소사실만 유죄로 인정되고 그 부분에 대하여 피고인만 상소하였다면, 주위적 공소사실은 상소심의 심판대상에 포함되지 않는다. 2024년도 국가공무원 9급 공채 필기시험 형"],"a":3}},{"y":2025,"e":"국가직 9급","qn":5,"i":"N92025-05-1","t":"공소장변경이 있는 경우에 공소시효의 완성 여부는 당초의 공소 제기가 있었던 시점을 기준으로 판단할 것이고 공소장변경 시를 기준으로 삼을 것은 아니고, 공소장변경절차에 의하여 공소사실이 변경됨에 따라 그 법정형에 차이가 있는 경우에는 변경된 공소 사실에 대한 법정형이 공소시효기간의 기준이 된다.","ox":"O","m":"①","c":"A","tp":"공판심리의 범위와 공소장변경"},{"y":2025,"e":"국가직 9급","qn":5,"i":"N92025-05-2","t":"법원은 공소사실의 동일성이 인정되는 범위 내에서 심리의 경과에 비추어 피고인의 방어권 행사에 실질적인 불이익을 초래할 염려가 없다고 인정되는 때에는 공소장이 변경되지 않았더라도 직권으로 공소장에 기재된 공소사실과 다른 범죄사실을 인정할 수 있다.","ox":"O","m":"②","c":"A","tp":"공판심리의 범위와 공소장변경"},{"y":2025,"e":"국가직 9급","qn":5,"i":"N92025-05-3","t":"공소사실의 동일성은 그 사실의 기초가 되는 사회적 사실관계가 기본적인 점에서 동일하면 그대로 유지되는 것이나, 이러한 기본적 사실관계의 동일성을 판단할 때에는 그 사실의 동일성이 갖는 기능을 염두에 두고 피고인의 행위와 그 사회적 사실관계를 기본으로 하되 규범적 요소도 아울러 고려하여야 한다.","ox":"O","m":"③","c":"A","tp":"공판심리의 범위와 공소장변경"},{"y":2025,"e":"국가직 9급","qn":5,"i":"N92025-05-4","t":"공소사실의 동일성이 인정되지 않는 등의 사유로 공소장변경허가 결정에 위법사유가 있는 경우에 공소장변경허가를 한 법원이 스스로 이를 취소할 수는 없다.","ox":"X","m":"④","c":"A","tp":"공판심리의 범위와 공소장변경"},{"y":2025,"e":"국가직 9급","qn":14,"i":"N92025-14-1","t":"소송절차가 분리된 공범인 공동피고인에 대하여 증인적격이 인정된다고 하더라도 법정에서 그 자신의 범죄사실에 대하여 신문하는 것은 피고인의 지위에서 보장받는 진술거부권이나 자기부죄거부특권을 침해하는 것이라고 보아야 한다.","ox":"X","m":"①","c":"A"},{"y":2025,"e":"국가직 9급","qn":14,"i":"N92025-14-2","t":"피의자가 다른 사람의 성명을 모용하여 공소장에 피모용자가 피고인으로 표시되었더라도, 검사는 모용자에 대하여 공소를 제기한 것이므로 모용자가 피고인이 되고 피모용자에게 공소의 효력이 미친다고는 할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"국가직 9급","qn":14,"i":"N92025-14-3","t":"甲에 대하여 발하여진 약식명령에 대하여 甲이 정식재판을 청구함으로써 甲을 상대로 심리를 하는 과정에서 甲이 성명을 모용당한 사실이 발각된 경우, 검사는 법원의 허가를 받아 공소장에 기재된 피고인의 표시를 모용자로 정정하여야 한다.","ox":"X","m":"③","c":"A"},{"y":2025,"e":"국가직 9급","qn":14,"i":"N92025-14-4","t":"법인세체납 등으로 공소제기되어 그 피고사건의 공판계속 중에 그 법인의 청산결료의 등기가 경료되었다면 법인의 청산사무는 종료된 것이라 할 수 있고, 그 사건이 종결되지 아니하는 동안이라도 형사소송법상 법인의 당사자능력은 소멸한다.","ox":"X","m":"④","c":"A","tp":"피고인"},{"y":2025,"e":"국가직 9급","qn":19,"i":"N92025-19-1","t":"공소시효는 범죄행위가 종료한 때부터 진행하지만, 정보통신망을 이용한 명예훼손의 경우에는 게재행위의 종료만으로 범죄행위가 종료하는 것이 아니고 원래 게시물이 삭제되어 정보의 송수신이 불가능해지는 시점을 범죄의 종료시기로 보아야 한다.","ox":"X","m":"①","c":"A"},{"y":2025,"e":"국가직 9급","qn":19,"i":"N92025-19-2","t":"미수범의 범죄행위는 행위를 종료하지 못하였거나 결과가 발생 하지 아니하여 더 이상 범죄가 진행될 수 없는 때에 종료하고, 그때부터 미수범의 공소시효가 진행한다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"국가직 9급","qn":19,"i":"N92025-19-3","t":"공범 중 1인에 대해 약식명령이 확정된 후 그에 대한 정식재판 청구권회복결정이 있었다고 하더라도 그 사이의 기간 동안에는 특별한 사정이 없는 한 다른 공범자에 대한 공소시효는 정지함이 없이 계속 진행한다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"국가직 9급","qn":19,"i":"N92025-19-4","t":"공범의 1인에 대한 공소제기에 따른 시효정지는 다른 공범자에게도 효력이 있고, 당해 사건의 재판이 확정된 때로부터 진행한다.","ox":"O","m":"④","c":"A","tp":"공소시효"}],"6":[{"y":2015,"e":"국가직 9급","qn":5,"i":"N92015-05-1","t":"피고인이 공시송달의 방법에 의한 공판기일의 소환을 2회 이상 받고도 출석하지 아니하여 법원이 피고인의 출정 없이 증거 조사를 하는 경우 피고인의 진의와는 관계없이 증거동의가 있는 것으로 간주된다.","ox":"O","m":"①","c":"A"},{"y":2015,"e":"국가직 9급","qn":5,"i":"N92015-05-2","t":"증거물인 서면의 경우 원칙적으로 증거신청인으로 하여금 그 서면을 제시하면서 낭독하게 하거나 이에 갈음하여 그 내용을 고지 또는 열람하도록 하여야 한다.","ox":"O","m":"②","c":"A","tp":"증거조사"},{"y":2015,"e":"국가직 9급","qn":5,"i":"N92015-05-3","t":"녹음테이프에 수록된 대화내용이 녹취록의 기재와 일치한다거나 녹음테이프의 대화내용이 중단되었다고 볼 만한 사정이 없다는 점만 인정되면 인위적 개작 없이 원본의 내용 그대로 복사된 사본임이 증명되었다고 할 수 있다.","ox":"X","m":"③","c":"A","tp":"증거조사"},{"y":2015,"e":"국가직 9급","qn":5,"i":"N92015-05-4","t":"피고인이 출석한 공판기일에서 증거로 함에 부동의한다는 의견을 진술한 경우 그 후 피고인이 출석하지 아니한 공판기일에 변호인만이 출석하여 종전 의견을 번복하여 증거로 함에 동의하였더라도 특별한 사정이 없는 한 효력이 없다.","ox":"O","m":"④","c":"A","tp":"증거조사"},{"y":2015,"e":"국가직 9급","qn":6,"i":"N92015-06","t":"‘필요성’이 인정될 수 있는 것만을 모두 고른 것은?","c":"A","mc":{"s":"‘필요성’이 인정될 수 있는 것만을 모두 고른 것은?","d":"형사소송법 제314조는 ‘필요성’과 ‘신용성의 정황적 보장’을 요건으로 예외적으로 진술조서의 증거능력을 인정하고 있다.  (다툼이 있는 경우 판례에 의함)\nㄱ. 노인성치매로 인하여 기억력에 장애가 있는 경우\nㄴ. 피해자인 증인이 출산을 앞두고 있다는 이유로 출석하지 않은 경우\nㄷ. 증인으로 출석해야 할 자가 외국에 거주하면서 법원의 소환에 계속 불응하고, 구인장 집행도 불가능한 상태에 있는 등 가능하고 상당한 수단을 다하더라도 그 진술을 요할 자를 법정에 출석하게 할 수 없는 경우\nㄹ. 증인이 형사소송법 에서 정한 바에 따라 정당하게 증언거부권을 행사하여 증언을 거부하는 경우","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄷ, ㄹ","ㄱ, ㄷ, ㄹ 형사"],"a":2}},{"y":2015,"e":"국가직 9급","qn":16,"i":"N92015-16","t":"A와 B에 대한 설명으로 옳은 것은?","c":"A","mc":{"s":"A와 B에 대한 설명으로 옳은 것은?","d":"사법경찰관은 甲과 乙을 강도상해죄의 공범으로 신문한 후 조서 (A)를 작성하여 검사에게 송치하였고, 검사는 다시 甲과 乙을 신문한 후 조서(B)를 작성하였다. 이후 검사는 甲에 대해서는 불기소처분을 하고, 乙만을 기소하였다.  (다툼이 있는 경우 판례에 의함)","o":["甲에 대한 A조서는 乙이 공판정에서 그 내용을 부인하더라도 甲이 공판정에서 성립의 진정을 인정하고 특신상태가 인정되면 증거로 사용할 수 있다.","乙에 대한 A조서는 乙이 공판정에서 그 내용을 인정한 때에 한하여 증거로 사용할 수 있다.","甲에 대한 B조서는 乙이 공판정에서 그 내용을 인정한 때에 한하여 증거로 사용할 수 있다.","乙에 대한 B조서는 乙이 공판정에서 성립의 진정을 부인하면 증거로 사용할 수 없다."],"a":2}},{"y":2016,"e":"국가직 9급","qn":8,"i":"N92016-08-1","t":"사인(私人)이 녹음한 녹음테이프의 검증조서 기재 중 피고인의 진술내용을 증거로 하기 위해서는 피고인이 내용을 인정하여야 한다.","ox":"X","m":"①","c":"A","tp":"특수한 증거방법의 증거능력"},{"y":2016,"e":"국가직 9급","qn":8,"i":"N92016-08-2","t":"디지털 녹음기에 녹음된 내용을 전자적 방법으로 테이프에 전사한 사본인 녹음테이프를 대상으로 법원이 검증절차를 진행하여, 녹음된 내용이 녹취록의 기재와 일치하고 그 음성이 진술자의 음성임을 확인하였더라도, 그것만으로 녹음테이프의 증거능력을 인정할 수 없다.","ox":"O","m":"②","c":"A","tp":"특수한 증거방법의 증거능력"},{"y":2016,"e":"국가직 9급","qn":8,"i":"N92016-08-3","t":"무인장비에 의한 속도위반차량 단속은 제한속도를 위반하여 차량을 주행하는 범죄가 현재 행하여지고 있고, 긴급하게 증거보전을 할 필요가 있는 상태에서 일반적으로 허용되는 한도를 넘지 않는 상당한 방법에 의한 것이므로 차량번호 등을 촬영한 사진은 증거능력이 인정된다.","ox":"O","m":"③","c":"A","tp":"특수한 증거방법의 증거능력"},{"y":2016,"e":"국가직 9급","qn":8,"i":"N92016-08-4","t":"피고인이 범행 후 피해자에게 전화를 걸어오자 피해자가 증거를 수집하려고 그 전화내용을 녹음한 경우 그것이 피고인 모르게 녹음된 것이라 하여 이를 위법하게 수집된 증거라고 할 수 없다.","ox":"O","m":"④","c":"A","tp":"특수한 증거방법의 증거능력"},{"y":2016,"e":"국가직 9급","qn":10,"i":"N92016-10","t":"자백의 보강 증거에 대한 설명으로 옳은 것만을 모두 고른 것은?","c":"A","mc":{"s":"자백의 보강 증거에 대한 설명으로 옳은 것만을 모두 고른 것은?","d":"(다툼이 있는 경우 판례에 의함)\nㄱ. 피고인 甲이 업무수행에 필요한 자금을 지출하면서, 스스로 그 지출한 자금내역을 자료로 남겨두기 위해 뇌물자금과 기타자금을 구별하지 아니하고 그 지출 내역을 그때그때 계속적, 기계적으로 수첩에 직접 기재한 기재내용은 뇌물 공여사실에 대한 보강증거가 될 수 있다.\nㄴ. 형사소송법 제310조 소정의 ‘피고인의 자백’에 공범인 공동피고인의 진술은 포함되지 아니하므로 공범인 공동 피고인의 진술은 다른 공동피고인에 대한 범죄사실을 인정하는 증거로 할 수 있을 뿐만 아니라 공범인 공동 피고인들의 각 진술은 상호 간에 서로 보강증거가 될 수 있다.\nㄷ. 피고인 甲이 乙로부터 필로폰을 매수하면서 그 대금을 乙이 지정하는 은행계좌로 송금한 사실에 대한 압수․ 수색․검증영장 집행보고는 피고인 甲의 필로폰 매수 행위와 실체적 경합범 관계에 있는 필로폰 투약행위에 대한 보강증거가 될 수 있다.\nㄹ. 자백에 대한 보강증거는 범죄사실 전부나 그 중요부분의 전부에 일일이 그 보강증거를 필요로 하는 것이며, 간접증거 내지 정황증거는 보강증거가 될 수 없다.","o":["ㄱ, ㄴ","ㄴ, ㄷ","ㄷ, ㄹ","ㄱ, ㄴ, ㄹ"],"a":1}},{"y":2016,"e":"국가직 9급","qn":14,"i":"N92016-14-1","t":"뇌물죄에서의 수뢰액은 그 다과에 따라 범죄구성요건이 되므로 엄격한 증명의 대상이 된다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"국가직 9급","qn":14,"i":"N92016-14-2","t":"공동정범에서 공모관계를 인정하기 위해서는 엄격한 증명이 요구된다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"국가직 9급","qn":14,"i":"N92016-14-3","t":"주취정도의 계산을 위한 위드마크 공식의 경우 그 적용을 위한 자료로 섭취한 알코올의 양, 음주 시각, 체중 등이 필요하며 그런 전제사실에 대하여는 자유로운 증명으로 족하다.","ox":"X","m":"③","c":"A"},{"y":2016,"e":"국가직 9급","qn":14,"i":"N92016-14-4","t":"몰수대상이 되는지 여부나 추징액의 인정 등 몰수·추징의 사유는 범죄구성요건 사실에 관한 것이 아니어서 엄격한 증명은 필요 없다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"국가직 9급","qn":17,"i":"N92016-17","t":"증거능력에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"증거능력에 대한 설명으로 옳지 않은 것은?","d":"","o":["제척사유가 있는 통역인이 통역한 증인의 증인신문조서는 유죄 인정의 증거로 사용할 수 없다.","압수된 디지털 저장매체로부터 출력한 문건을 진술증거로 사용하는 경우에 그 기재 내용의 진실성에 관하여는 전문 법칙이 적용된다.","어떤 진술이 기재된 서류가 그 진술의 진실성과 관계없는 간접사실에 대한 정황증거로 사용될 경우 반드시 전문증거가 되는 것은 아니다.","체포․구속인접견부는 특히 신용할 만한 정황에 의하여 작성된 문서로서 형사소송법 제315조 제2호, 제3호에 규정된 ‘당연히 증거능력이 있는 서류’에 해당된다. 형사소송법개론 2 책형 4 쪽"],"a":4}},{"y":2016,"e":"국가직 9급","qn":19,"i":"N92016-19","t":"전문법칙에 대한 설명으로 옳은 것만을 모두 고른 것은?","c":"A","mc":{"s":"전문법칙에 대한 설명으로 옳은 것만을 모두 고른 것은?","d":"(다툼이 있는 경우 판례에 의함)\nㄱ. 사인(私人)인 제3자가 절취한 업무일지를 소송사기의 피해자가 대가를 지급하고 취득한 경우, 그 업무일지는 사기죄에 대한 증거로 사용될 수 있다.\nㄴ. 상업장부․항해일지․사인(私人)인 의사의 진단서와 같이 기타 업무상 필요로 작성한 문서는 형사소송법 제315조에 의하여 당연히 증거능력이 인정된다.\nㄷ. 사법경찰리 작성의 피해자에 대한 진술조서가 피해자의 화상으로 인한 서명불능을 이유로 입회하고 있던 피해자의 동생에게 대신 읽어 주고 그 동생으로 하여금 서명날인 하게 하는 방법으로 작성된 경우 형사소송법 제313조 제1항에 의하여 증거능력이 인정된다.\nㄹ. 피고인 甲이 공판정에서 공범 乙에 대한 사법경찰관 작성의 피의자신문조서의 내용을 부인하면 乙이 법정 에서 그 조서의 내용을 인정하더라도 그 조서를 피고인 甲의 공소사실에 대한 증거로 사용할 수 없다.","o":["ㄱ, ㄴ","ㄱ, ㄹ","ㄴ, ㄷ","ㄷ, ㄹ"],"a":2}},{"y":2017,"e":"국가직 9급","qn":1,"i":"N92017-01-1","t":"‘외국거주’라 함은 진술을 요할 자가 외국에 있다는 것만으로는 부족하고, 그를 공판정에 출석시켜 진술하게 할 모든 수단을 강구하는 등 가능하고 상당한 수단을 다하더라도 그 진술을 요할 자를 법정에 출석하게 할 수 없는 사정이 있는 예외적인 경우를 말한다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"국가직 9급","qn":1,"i":"N92017-01-2","t":"증인이 ‘소재불명이거나 그 밖에 이에 준하는 사유로 인하여 진술할 수 없는 때’에 해당한다고 인정할 수 있으려면 증인의 법정 출석을 위한 가능하고도 충분한 노력을 다하였음에도 불구하고 부득이 증인의 법정 출석이 불가능하게 되었다는 사정이 있어야 하며, 이는 검사가 증명하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"국가직 9급","qn":1,"i":"N92017-01-3","t":"수사기관에서 진술한 피해자인 유아가 공판정에서 진술을 하였더라도 증인신문 당시 일정한 사항에 관하여 기억이 나지 않는다는 취지로 진술하여 그 진술의 일부가 재현 불가능하게 된 경우는 ‘원진술자가 진술을 할 수 없는 때’에 해당하지 않는다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"국가직 9급","qn":1,"i":"N92017-01-4","t":"법정에 출석한 증인이 정당하게 증언거부권을 행사하여 증언을 거부한 경우는 ‘그 밖에 이에 준하는 사유로 인하여 진술할 수 없는 때’에 해당하지 않는다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"국가직 9급","qn":3,"i":"N92017-03-1","t":"탄핵증거로 사용될 수 있는 전문증거에는 전문서류만이 포함 되며 전문진술은 제외된다.","ox":"X","m":"①","c":"A"},{"y":2017,"e":"국가직 9급","qn":3,"i":"N92017-03-2","t":"탄핵증거로 사용되기 위해서는 상대방이 증거로 함에 동의함을 요한다.","ox":"X","m":"②","c":"A"},{"y":2017,"e":"국가직 9급","qn":3,"i":"N92017-03-3","t":"탄핵증거는 진술의 증명력을 감쇄하기 위해서 뿐만 아니라 범죄사실 또는 그 간접사실의 인정증거로서도 허용된다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"국가직 9급","qn":3,"i":"N92017-03-4","t":"탄핵증거의 제출에 있어서는 증명력을 다투고자 하는 증거의 어느 부분에 의하여 진술의 어느 부분을 다투려고 한다는 것을 사전에 상대방에게 알려야 한다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"국가직 9급","qn":6,"i":"N92017-06","t":"증거조사에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"증거조사에 대한 설명으로 옳지 않은 것은?","d":"","o":["법원은 직권 또는 검사, 피고인이나 변호인의 신청에 의하여 공무소 또는 공사단체에 조회하여 필요한 사항의 보고 또는 그 보관서류의 송부를 요구할 수 있다.","증거물인 서면을 조사하기 위해서는 증거서류의 조사방식인 낭독․내용고지 또는 열람의 절차와 증거물의 조사방식인 제시의 절차가 함께 이루어져야 한다.","법원은 검사, 피고인 또는 변호인의 신청에 의하여 공판준비에 필요하다고 인정한 때에는 공판기일 전에 피고인 또는 증인을 신문할 수 있다.","검사, 피고인 또는 변호인은 증거조사에 관하여 이의신청을 할 수 있고, 증거결정에 대한 이의신청은 법령의 위반이 있거나 상당하지 아니함을 이유로 이를 할 수 있다. 형사"],"a":4}},{"y":2017,"e":"국가직 9급","qn":16,"i":"N92017-16","t":"이에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"이에 대한 설명으로 옳지 않은 것은?","d":"甲과 乙은 “공모하여 마약류취급자가 아니면서 2017년 1월에서 3월 사이 일자불상 03 : 00경 S시 소재 상호불상의 모텔에서 청소년 A에게 메스암페타민(일명 필로폰)을 투약하였다”는 공소 사실로 기소되었다. 경찰수사 과정에서 甲은 “乙과 함께 A에게 필로폰을 투약하였다”고 자백하였으나, 乙은 “甲과 범행을 공모한 적은 없고 단지 甲이 누군가에게 투약한다고 하면서 필로폰을 구해달라고 부탁하기에 필로폰을 구해주었을 뿐이다”라고 진술 하였다.  (다툼이 있는 경우 판례에 의함)","o":["공소사실의 일시나 장소가 다소 개괄적으로 기재되었더라도 그 기재가 다른 사실과 식별이 곤란하다거나 피고인의 방어권 행사에 지장을 초래할 정도라고 보기 어렵다면 공소사실은 특정되었다고 보아야 한다.","乙에 대해 사법경찰관이 작성한 피의자신문조서는 甲이 공판 기일에 그 내용을 부인하면 증거로 할 수 없다.","甲이 乙에 대한 사법경찰관작성 피의자신문조서의 내용을 부인하더라도 乙이 법정에서 “경찰수사를 받던 중에 피의자 신문조서에 기재된 것과 같은 내용으로 진술하였다”는 취지로 증언하였다면 그 증언은 甲의 유죄 인정의 증거로 할 수 있다.","만약 甲과 乙이 모두 공소사실을 인정하는 자백을 하였다면 자백 이외에 다른 증거가 없더라도 법원은 甲과 乙에게 유죄를 선고할 수 있다."],"a":3}},{"y":2017,"e":"국가직 9급","qn":20,"i":"N92017-20","t":"이에 대한 설명으로 옳은 것은?","c":"A","mc":{"s":"이에 대한 설명으로 옳은 것은?","d":"甲은 휴대전화기를 이용하여 A에게 공포심을 유발하는 글을 반복적으로 도달하게 한 혐의로 정보통신망이용촉진및정보보호 등에관한법률위반죄로 기소되었다. 검사는 乙이 甲의 부탁을 받고 甲의 휴대전화기를 보관하고 있다는 사실을 알고 乙에게 부탁하여 甲의 휴대전화기를 임의제출 받았다. 한편 A는 B의 휴대전화기에 “甲으로부터 수차례 협박 문자메시지를 받았다”는 내용의 문자 메시지를 발송하였다.  (다툼이 있는 경우 판례에 의함)","o":["甲의 휴대전화기는 甲의 승낙이나 영장없이 위법하게 수집된 증거로서 증거능력이 부정된다.","甲의 휴대전화기 자체가 아니라 甲의 휴대전화기 화면에 표시된 문자메시지를 촬영한 사진이 증거로 제출된 경우 甲이 그 성립 및 내용의 진정을 부인하는 때에는 이를 증거로 사용할 수 없다.","甲의 휴대전화기 화면을 촬영한 사진을 증거로 사용하려면 甲의 휴대전화기를 법정에 제출할 수 없거나 그 제출이 곤란한 사정이 있고, 그 사진의 영상이 甲의 휴대전화기 화면에 표시된 문자정보와 정확하게 같다는 사실이 증명되어야 한다.","B의 휴대전화기에 저장된 문자메시지는 본래증거로서 형사 소송법 제310조의2가 정한 전문법칙이 적용될 여지가 없다."],"a":3}},{"y":2018,"e":"국가직 9급","qn":8,"i":"N92018-08-1","t":"“甲이 도둑질 하는 것을 보았다”라는 乙의 발언사실을 A가 법정에서 증언하는 경우, 乙의 명예훼손 사건에 대한 전문 증거로서 전문법칙이 적용된다.","ox":"X","m":"①","c":"A"},{"y":2018,"e":"국가직 9급","qn":8,"i":"N92018-08-3","t":"사법경찰관작성의 공동피고인(乙)에 대한 피의자신문조서를 乙이 법정에서 진정성립 및 내용을 인정한 경우, 공동피고인 (甲)이 그 피의자신문조서의 진정성립 및 내용을 인정하지 않더라도 甲에 대하여 증거능력이 있다.","ox":"X","m":"③","c":"A","tp":"전문법칙"},{"y":2018,"e":"국가직 9급","qn":8,"i":"N92018-08-4","t":"의사가 작성한 진단서는 업무상 필요에 의하여 순서적, 계속적으로 작성되는 것이고 그 작성이 특히 신빙할 만한 정황에 의하여 작성된 문서이므로 당연히 증거능력이 인정되는 서류라고 할 수 있다.","ox":"X","m":"④","c":"A","tp":"전문법칙"},{"y":2018,"e":"국가직 9급","qn":14,"i":"N92018-14-1","t":"임의성이 인정되지 아니하여 증거능력이 없는 진술증거는 피고인이 증거로 함에 동의하더라도 증거로 삼을 수 없다.","ox":"O","m":"①","c":"A","tp":"진술증거의 증거능력"},{"y":2018,"e":"국가직 9급","qn":14,"i":"N92018-14-2","t":"참고인으로 조사를 받으면서 수사기관으로부터 진술거부권을 고지받지 않았다면 그 진술조서는 위법수집증거로서 증거 능력이 없다.","ox":"X","m":"②","c":"A","tp":"진술증거의 증거능력"},{"y":2018,"e":"국가직 9급","qn":14,"i":"N92018-14-3","t":"공판기일에 피고인의 진술을 기재한 조서는 전문법칙에도 불구하고 증거로 할 수 있다.","ox":"O","m":"③","c":"A","tp":"진술증거의 증거능력"},{"y":2018,"e":"국가직 9급","qn":14,"i":"N92018-14-4","t":"공판기일에 피고인에게 유리한 증언을 한 증인을 이후 검사가 소환하여 일방적으로 번복시키는 방식으로 작성한 진술조서는 증거능력이 없다.","ox":"O","m":"④","c":"A","tp":"진술증거의 증거능력"},{"y":2018,"e":"국가직 9급","qn":15,"i":"N92018-15","t":"피고인이 범행을 자인하는 것을 들었다는 피고인 아닌 자의 진술은 피고인의 자백의 보강증거가 될 수 있다.","c":"A","mc":{"s":"피고인이 범행을 자인하는 것을 들었다는 피고인 아닌 자의 진술은 피고인의 자백의 보강증거가 될 수 있다.","d":"자백보강법칙에 대한 설명으로 옳은 것(○)과 옳지 않은 것(×)을 바르게 연결한 것은? (다툼이 있는 경우 판례에 의함)\nㄱ. 피고인이 위조신분증을 제시․행사한 사실을 자백하고 있는 때에는 그 신분증의 현존은 자백을 보강하는 간접증거가 된다.\nㄴ.\nㄷ. 즉결심판이나 소년보호사건에서는 피고인의 자백만을 증거로 범죄사실을 인정할 수 있다. ㄱ ㄴ ㄷ","o":["○ × ○","× ○ ×","× ○ ○","○ × ×"],"a":1}},{"y":2018,"e":"국가직 9급","qn":16,"i":"N92018-16-1","t":"조서말미에 피고인의 서명만 있고 간인이 없는 검사 작성의 피고인에 대한 피의자신문조서에 대해, 간인이 없는 것이 피고인이 간인을 거부하였기 때문이라는 취지가 조서말미에 기재되었다면, 그 조서의 증거능력을 인정할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2018,"e":"국가직 9급","qn":16,"i":"N92018-16-2","t":"문자메시지가 표시된 휴대전화기의 화면을 촬영한 사진을 증거로 사용하려면 그 휴대전화기를 법정에 제출할 수 없거나 제출이 곤란한 사정이 있고, 그 사진이 휴대전화기의 화면에 표시된 문자메시지와 정확하게 같다는 사실이 증명되어야 한다.","ox":"O","m":"②","c":"A","tp":"증거능력"},{"y":2018,"e":"국가직 9급","qn":16,"i":"N92018-16-3","t":"형사소송법 제314조의 ‘특신상태’와 관련된 법리는 원진술자의 소재불명 등을 전제로 하고 있는 형사소송법 제316조제2항의 ‘특신상태’에 관한 해석과 동일하다.","ox":"O","m":"③","c":"A","tp":"증거능력"},{"y":2018,"e":"국가직 9급","qn":16,"i":"N92018-16-4","t":"피고인이 아닌 자가 수사과정에서 진술서를 작성하였으나 수사기관이 그에 대한 조사과정을 기록하지 아니한 경우, 특별한 사정이 없는 한 그 진술서의 증거능력을 인정할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"국가직 9급","qn":19,"i":"N92018-19","t":"증인적격이 있는 자만을 모두 고른 것은?","c":"A","mc":{"s":"증인적격이 있는 자만을 모두 고른 것은?","d":"(다툼이 있는 경우 판례에 의함)\nㄱ. 당해 사건에서 압수․수색을 집행한 검찰수사관\nㄴ. 별개의 재판에서 이미 당해 사건에 대해 유죄판결이 확정된 공범\nㄷ. 피고인의 배우자","o":["ㄱ","ㄱ, ㄷ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":4}},{"y":2019,"e":"국가직 9급","qn":15,"i":"N92019-15-1","t":"자백하면 가벼운 형으로 처벌되도록 하겠다고 약속하거나 또는 일정한 증거가 발견되면 자백하겠다는 약속하에 이루어진 자백이라고 하여 곧 임의성이 부정되는 것은 아니다.","ox":"X","m":"①","c":"A","tp":"자백의 증거능력"},{"y":2019,"e":"국가직 9급","qn":15,"i":"N92019-15-2","t":"수사기관이 피의자를 신문함에 있어서 피의자에게 미리 진술 거부권을 고지하지 않은 경우라 하더라도 진술의 임의성이 있으면 증거능력이 인정된다.","ox":"X","m":"②","c":"A","tp":"자백의 증거능력"},{"y":2019,"e":"국가직 9급","qn":15,"i":"N92019-15-3","t":"피고인이 경찰수사 단계에서 고문 등 가혹행위로 인하여 임의성 없는 자백을 하고, 그 후에도 임의성 없는 심리상태가 검사 조사단계에서도 계속된 경우에는 검사 앞에서의 자백도 임의성이 부정된다.","ox":"O","m":"③","c":"A","tp":"자백의 증거능력"},{"y":2019,"e":"국가직 9급","qn":15,"i":"N92019-15-4","t":"공범인 공동피고인의 법정 자백은 피고인들 간에 이해관계가 상반되지 않는 경우에만 다른 공동피고인에 대하여 독립한 증거능력이 있다.","ox":"X","m":"④","c":"A","tp":"자백의 증거능력"},{"y":2019,"e":"국가직 9급","qn":16,"i":"N92019-16","t":"디지털 저장매체에 저장되어 있는 피고인 아닌 자가 작성한 문서를 출력하여 제출한 경우, 그 증거능력 인정요건에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"디지털 저장매체에 저장되어 있는 피고인 아닌 자가 작성한 문서를 출력하여 제출한 경우, 그 증거능력 인정요건에 대한 설명으로 옳지 않은 것은?","d":"(증거동의가 없음을 전제하고, 다툼이 있는 경우 판례에 의함)","o":["디지털 저장매체의 사용자 및 소유자, 로그기록 등 저장매체에 남은 흔적, 초안 문서의 존재, 작성자만의 암호 사용 여부, 전자서명의 유무 등 객관적 사정에 의하여 동일인이 작성 하였다고 볼 수 있다면 그 작성자의 부인에도 불구하고 진정성립을 인정할 수 있다.","디지털 저장매체 원본에 저장된 내용과 출력 문건의 동일성이 인정되어야 하고, 이를 위해서는 정보저장매체 원본이 압수 시부터 문건 출력 시까지 변경되지 않았다는 무결성이 담보 되어야 한다.","작성자가 자기에게 맡겨진 사무를 처리한 내역을 그때그때 계속적․기계적으로 기재하여 저장해 놓은 문서로서 업무상 필요로 작성한 통상문서에 해당하면 증거능력이 인정된다.","디지털 저장매체에 저장된 로그파일의 원본이 아니라 그 복사본의 일부 내용을 요약ㆍ정리하는 방식으로 새로운 문서 파일이 작성된 경우, 새로 작성한 파일을 출력한 문서는 로그파일의 복사본과 원본의 동일성이 인정되더라도 로그파일 원본의 내용을 증명하는 증거로 사용할 수 없다. 2019년도 국가공무원 9급 공채 필기시험 형사"],"a":4}},{"y":2019,"e":"국가직 9급","qn":17,"i":"N92019-17","t":"다음 중 전문증거에 해당하는 것은?","c":"A","mc":{"s":"다음 중 전문증거에 해당하는 것은?","d":"","o":["甲이 정보통신망을 통하여 공포심이나 불안감을 유발하는 글을 반복적으로 상대방에게 도달하게 하는 행위를 하였음을 공소사실로 하여 기소되었는데, 검사가 위 죄에 대한 유죄의 증거로 휴대전화기에 저장된 문자정보를 제출한 경우","증인이 법정에서 “甲이 ○○ 체육관 부지를 공시지가로 매입 하게 해 주겠다고 말하였다.”라고 증언하였는데, 그 증언이 甲이 그와 같이 말한 사실의 존재를 증명하기 위한 증거로 제출된 경우","甲이 반국가단체 구성원 A와 회합한 후 A로부터 지령을 받고 국가기밀을 탐지․수집하였다는 공소사실로 기소되었고, 甲의 컴퓨터에서 “A 선생 앞: 2011년 면담은 1월 30일 북경에서 하였으면 하는 의견입니다.”라는 등의 내용이 담겨져 있는 파일이 발견되었는데, 이 파일이 甲과 A의 회합을 입증하기 위한 증거로 제출된 경우","甲이 반국가단체로부터 지령을 받고 국가기밀을 탐지․수집 하였다는 공소사실로 기소되었는데 甲의 컴퓨터에 저장되어 있던 국가기밀을 담은 서류가 증거로 제출된 경우"],"a":3}},{"y":2019,"e":"국가직 9급","qn":18,"i":"N92019-18-1","t":"지문채취 대상물을 적법한 절차에 의하지 아니하고 압수한 경우에는 그 압수 이전에 범행현장에서 지문채취 대상물로부터 채취한 지문일지라도 그 지문의 증거능력은 없다.","ox":"X","m":"①","c":"A","tp":"위법수집증거"},{"y":2019,"e":"국가직 9급","qn":18,"i":"N92019-18-2","t":"위법하게 수집된 증거도 당사자의 동의가 있으면 증거능력이 인정된다.","ox":"X","m":"②","c":"A","tp":"위법수집증거"},{"y":2019,"e":"국가직 9급","qn":18,"i":"N92019-18-3","t":"증인이 친분이 있던 피해자와 통화를 마친 후 전화가 끊기지 않은 상태에서 휴대전화를 통하여 몸싸움을 연상시키는 ‘악’ 하는 소리와 ‘우당탕’ 소리를 1 ～2분 들었다고 증언한 경우, 그 소리는 통신비밀보호법에서 말하는 타인 간의 대화에 해당하지 않는다.","ox":"O","m":"③","c":"A","tp":"위법수집증거"},{"y":2019,"e":"국가직 9급","qn":18,"i":"N92019-18-4","t":"피고인이 범행 후 피해자에게 전화를 걸어오자 피해자가 증거를 수집하려고 그 전화내용을 녹음한 경우, 그 녹음테이프가 피고인 모르게 녹음된 것이면 그 녹음테이프는 위법하게 수집된 증거이다.","ox":"X","m":"④","c":"A","tp":"위법수집증거"},{"y":2020,"e":"국가직 9급","qn":3,"i":"N92020-03-1","t":"검사의 구형은 양형에 관한 의견진술에 불과하므로 법원이 그 의견에 구속되는 것은 아니지만, 법원이 피고인에 대한 형을 정함에 있어 검사의 구형에 포함되지 아니한 벌금형을 병과하는 것은 위법하다.","ox":"X","m":"①","c":"A","tp":"증거와 재판"},{"y":2020,"e":"국가직 9급","qn":3,"i":"N92020-03-2","t":"증거능력이 없는 증거도 구성요건 사실을 추인하게 하는 간접사실이나 구성요건 사실을 입증하는 직접증거의 증명력을 보강하는 보조사실의 인정자료로서는 허용된다.","ox":"X","m":"②","c":"A","tp":"증거와 재판"},{"y":2020,"e":"국가직 9급","qn":3,"i":"N92020-03-3","t":"피고인이 증거로 함에 동의한 바 없는, 공범이 아닌 공동 피고인에 대한 검사작성 피의자신문조서는 공동피고인의 증언에 의하여 그 성립의 진정이 인정되지 아니하는 한 피고인의 공소 범죄사실을 인정하는 증거로 할 수 없다.","ox":"O","m":"③","c":"A","tp":"증거와 재판"},{"y":2020,"e":"국가직 9급","qn":3,"i":"N92020-03-4","t":"법원이 적법하게 공판의 심리를 종결한 후에 피고인이 증인 신청을 하면 법원은 공판의 심리를 재개하여 증인신문을 하여야 한다.","ox":"X","m":"④","c":"A","tp":"증거와 재판"},{"y":2020,"e":"국가직 9급","qn":12,"i":"N92020-12-1","t":"공모공동정범에 있어서 공모는 엄격한 증명을 요한다.","ox":"O","m":"①","c":"A","tp":"증명의 기본원칙"},{"y":2020,"e":"국가직 9급","qn":12,"i":"N92020-12-2","t":"형법 제87조 내란죄에서 국헌문란의 목적은 범죄성립을 위하여 고의 외에 요구되는 초과주관적 위법요소이므로 엄격한 증명을 요한다.","ox":"O","m":"②","c":"A","tp":"증명의 기본원칙"},{"y":2020,"e":"국가직 9급","qn":12,"i":"N92020-12-3","t":"도로교통법위반(음주운전)죄에서 혈중 알코올농도의 추정방식으로 위드마크 공식을 이용한 경우에 그 적용을 위한 자료인 섭취한 알코올의 양, 음주시각, 체중 등의 사실은 자유로운 증명으로 족하다.","ox":"X","m":"③","c":"A","tp":"증명의 기본원칙"},{"y":2020,"e":"국가직 9급","qn":12,"i":"N92020-12-4","t":"형법 제307조제1항의 명예훼손죄 성립 여부에 있어서 동법 제310조의 위법성조각사유의 존재는 자유로운 증명으로 족하다.","ox":"O","m":"④","c":"A","tp":"증명의 기본원칙"},{"y":2020,"e":"국가직 9급","qn":13,"i":"N92020-13-1","t":"탄핵증거는 엄격한 증거조사 없이 증거로 사용할 수 있으므로, 탄핵증거를 제출하는 자는 어느 부분에 의하여 진술의 어느 부분을 다투려고 한다는 점을 사전에 상대방에게 알릴 필요가 없다.","ox":"X","m":"①","c":"A"},{"y":2020,"e":"국가직 9급","qn":13,"i":"N92020-13-2","t":"탄핵증거는 진술의 증명력을 감쇄하기 위하여 인정되는 것이고, 범죄사실 또는 그 간접사실을 인정하는 증거로는 허용되지 않는다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"국가직 9급","qn":13,"i":"N92020-13-3","t":"피고인의 공판정 외의 자백에 관하여 피고인이 그 내용을 부인하더라도 그것이 임의로 작성된 것이 아니라고 의심할 만한 사정이 없는 한, 그 자백은 피고인의 공판정에서의 진술의 증명력을 다투기 위한 탄핵증거로 사용할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"국가직 9급","qn":13,"i":"N92020-13-4","t":"진술자의 서명·날인이 없어 성립의 진정이 인정되지 아니한 증거도 탄핵증거가 될 수 있다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"국가직 9급","qn":15,"i":"N92020-15","t":"형사소송법 제315조에 규정된 당연히 증거능력 있는 서류에 해당하는 것(○)과 해당하지 않는 것(×)을 바르게 연결한 것은?","c":"A","mc":{"s":"형사소송법 제315조에 규정된 당연히 증거능력 있는 서류에 해당하는 것(○)과 해당하지 않는 것(×)을 바르게 연결한 것은?","d":"(다툼이 있는 경우 판례에 의함)\nㄱ. 보험사기 사건에서 건강보험심사평가원이 수사기관의 의뢰에 따라 그 수사기관이 보내온 자료를 토대로 작성한 입원진료의 적정성에 대한 의견을 제시하는 내용의 ‘입원진료 적정성 여부 등 검토의뢰에 대한 회신’\nㄴ. 대한민국 주중국 대사관 영사가 공무수행과정에서 작성하였지만 공적인 증명보다는 상급자에 대한 보고를 목적으로 작성한 사실확인서(공인(公印) 부분은 제외)\nㄷ. 검찰에서 피고인이 소지․탐독을 인정한 유인물에 대하여, 사법경찰관이 그 내용을 분석하고 이를 기계적으로 복사하여 그 말미에 그대로 첨부하여 작성한 수사보고서\nㄹ. 성매매업소에서 성매매 여성들이 영업에 참고하기 위하여 성매매 상대방의 아이디, 전화번호 등에 관한 정보를 입력하여 작성한 메모리카드의 내용 ㄱ ㄴ ㄷ ㄹ","o":["○ × ○ ×","× × ○ ×","○ ○ × ○","× × ○ ○"],"a":4}},{"y":2021,"e":"국가직 9급","qn":6,"i":"N92021-06","t":"전문증거의 증거능력에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"전문증거의 증거능력에 대한 설명으로 옳지 않은 것은?","d":"","o":["형사소송법 제312조제4항에서 ‘적법한 절차와 방식에 따라 작성’한다는 것은 형사소송법 이 피고인 아닌 사람의 진술에 대한 조서 작성 과정에서 지켜야 한다고 정한 여러 절차를 준수하고 조서의 작성 방식에도 어긋나지 않아야 한다는 것을 의미한다.","형사소송법 제313조에 따르면 피고인이 작성한 진술서는 공판준비나 공판기일에서의 피고인의 진술에 의하여 그 성립의 진정함이 증명된 때에만 증거로 할 수 있고, 피고인이 그 성립의 진정을 부인한 경우에는 증거로 할 수 있는 방법은 없다.","형사소송법 제314조의 ‘외국거주’는 진술을 하여야 할 사람이 외국에 있다는 사정만으로는 부족하고, 가능하고 상당한 수단을 다하더라도 그 사람을 법정에 출석하게 할 수 없는 사정이 있어야 예외적으로 그 요건이 충족될 수 있다.","형사소송법 제316조제2항에서 ‘그 진술이 특히 신빙할 수 있는 상태하에서 행하여졌음’이란 진술 내용에 허위가 개입할 여지가 거의 없고, 진술 내용의 신빙성이나 임의성을 담보할 구체적이고 외부적인 정황이 있는 경우를 의미한다. 2021년도 국가공무원 9급 공채 필기시험 형사"],"a":2}},{"y":2021,"e":"국가직 9급","qn":7,"i":"N92021-07-1","t":"사인이 위법하게 수집한 증거에 대해서는 효과적인 형사소추 및 형사소송에서의 진실발견이라는 공익과 개인의 인격적 이익 등의 보호이익을 비교형량하여 그 허용 여부를 결정하여야 한다.","ox":"O","m":"①","c":"A","tp":"위법수집증거배제법칙"},{"y":2021,"e":"국가직 9급","qn":7,"i":"N92021-07-2","t":"‘악’과 같은 대화가 아닌 사람의 목소리를 녹음하거나 청취하는 행위가 개인의 사생활의 비밀과 자유 또는 인격권을 중대하게 침해하여 사회통념상 허용되는 한도를 벗어난 것이 아니라면 위와 같은 목소리를 들었다는 진술을 형사절차에서 증거로 사용할 수 있다.","ox":"O","m":"②","c":"A","tp":"위법수집증거배제법칙"},{"y":2021,"e":"국가직 9급","qn":7,"i":"N92021-07-3","t":"압수·수색영장의 집행과정에서 별건 범죄혐의와 관련된 증거를 우연히 발견하여 압수한 경우에는 별건 범죄혐의에 대해 별도의 압수·수색영장을 발부받지 않았다 하더라도 위법한 압수·수색에 해당하지 않는다.","ox":"X","m":"③","c":"A","tp":"위법수집증거배제법칙"},{"y":2021,"e":"국가직 9급","qn":7,"i":"N92021-07-4","t":"위법수집증거배제법칙에 대한 예외를 인정하기 위해서는 예외적인 경우에 해당한다고 볼 만한 구체적이고 특별한 사정이 존재한다는 점을 검사가 증명하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"국가직 9급","qn":8,"i":"N92021-08-1","t":"범죄구성요건에 해당하는 사실을 증명하기 위한 근거가 되는 과학적인 연구 결과는 적법한 증거조사를 거친 증거능력 있는 증거에 의하여 엄격한 증명으로 증명되어야 한다.","ox":"O","m":"①","c":"A","tp":"과학적 증거"},{"y":2021,"e":"국가직 9급","qn":8,"i":"N92021-08-2","t":"유전자검사나 혈액형검사 등 과학적 증거방법은 그 전제로 하는 사실이 모두 진실임이 입증되고 그 추론의 방법이 과학적으로 정당하여 오류의 가능성이 전무하거나 무시할 정도로 극소한 것으로 인정되는 경우에는 법관이 사실인정을 함에 있어 상당한 정도로 구속력을 가진다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"국가직 9급","qn":8,"i":"N92021-08-3","t":"전문 감정인이 공인된 표준 검사기법으로 분석한 후 법원에 제출한 과학적 증거는 모든 과정에서 시료의 동일성이 인정되고 인위적인 조작·훼손·첨가가 없었음이 담보되었다면, 각 단계에서 시료에 대한 정확한 인수·인계 절차를 확인할 수 있는 기록이 유지되지 않았다 하더라도 사실인정에 있어서 상당한 정도로 구속력을 가진다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"국가직 9급","qn":8,"i":"N92021-08-4","t":"컴퓨터 디스켓에 들어 있는 문건이 증거로 사용되는 경우 그 컴퓨터 디스켓은 그 기재의 매체가 다를 뿐 실질에 있어서는 피고인 또는 피고인 아닌 자의 진술을 기재한 서류와 크게 다를 바 없고, 압수 후의 보관 및 출력과정에 조작의 가능성이 있으며, 기본적으로 반대신문의 기회가 보장되지 않는 점 등에 비추어 그 기재내용의 진실성에 관하여는 전문법칙이 적용된다.","ox":"O","m":"④","c":"A","tp":"과학적 증거"},{"y":2021,"e":"국가직 9급","qn":9,"i":"N92021-09-1","t":"증언을 거부하는 자는 거부사유를 소명하여야 한다.","ox":"O","m":"①","c":"A","tp":"증인신문"},{"y":2021,"e":"국가직 9급","qn":9,"i":"N92021-09-2","t":"증인이 들을 수 없는 때에는 서면으로 묻고, 말할 수 없는 때에는 서면으로 답하게 할 수 있다.","ox":"O","m":"②","c":"A","tp":"증인신문"},{"y":2021,"e":"국가직 9급","qn":9,"i":"N92021-09-3","t":"필요한 때에는 증인과 다른 증인 또는 피고인과 대질하게 할 수 있다.","ox":"O","m":"③","c":"A","tp":"증인신문"},{"y":2021,"e":"국가직 9급","qn":9,"i":"N92021-09-4","t":"변호인이 신청한 증인은 검사, 변호인, 재판장의 순으로 신문하며, 합의부원은 당해 증인을 신문할 수 없다.","ox":"X","m":"④","c":"A","tp":"증인신문"},{"y":2021,"e":"국가직 9급","qn":19,"i":"N92021-19","t":"형사소송법 의 내용으로 옳지 않은 것만을 모두 고르면?","c":"A","mc":{"s":"형사소송법 의 내용으로 옳지 않은 것만을 모두 고르면?","d":"ㄱ. 사법경찰관이 작성한 피의자신문조서는 적법한 절차와 방식에 따라 작성된 것으로서 공판준비 또는 공판기일에 그 피의자였던 피고인 또는 변호인이 그 내용을 인정할 때에 한하여 증거능력이 있다.\nㄴ. 공판기일에 검사는 공소장에 의하여 공소사실․죄명 및 적용법조를 낭독하여야 한다. 다만 재판장은 필요하다고 인정하는 때에는 검사에게 공소장의 낭독 또는 공소요지의 진술을 생략하도록 할 수 있다.\nㄷ. 형을 선고하는 경우 재판장은 상소할 기간뿐만 아니라 상소할 법원을 피고인에게 고지해야 한다.\nㄹ. 공판준비기일의 지정 신청에 관한 법원의 결정에 대해서는 항고할 수 있다.\nㅁ. 법원은 소송관계를 분명하게 하기 위해 직권 또는 검사, 피고인 또는 변호인의 신청으로 전문심리위원을 지정하여 소송절차에 참여하게 할 수 있으며, 이러한 전문심리위원은 재판장의 허가를 받으면 피고인, 변호인, 증인 등 소송 관계인에게 필요한 사항에 관하여 직접 질문할 수 있다.","o":["ㄱ, ㄷ","ㄴ, ㄹ","ㄴ, ㄷ, ㅁ","ㄴ, ㄹ, ㅁ"],"a":2}},{"y":2023,"e":"국가직 9급","qn":1,"i":"N92023-01-1","t":"사법경찰관이 형사소송법 제215조제2항을 위반하여 영장 없이 물건을 압수한 직후에 피압수자로부터 그 압수물에 대한 임의제출 동의서를 받은 경우, 그 압수물은 물론 임의제출동의서도 특별한 사정이 없는 한 증거능력이 인정되지 않는다.","ox":"O","m":"①","c":"A","tp":"위법수집증거배제법칙"},{"y":2023,"e":"국가직 9급","qn":1,"i":"N92023-01-2","t":"전자정보가 담긴 저장매체에 대한 압수ㆍ수색 과정에서 범위를 정하여 출력ㆍ복제하는 방법이 불가능하거나 압수의 목적을 달성하기에 현저히 곤란한 예외적인 사정이 인정되어 그 전자정보의 복제본을 수사기관 사무실 등으로 옮겨 복제ㆍ탐색ㆍ출력하는 경우, 그 과정에 피압수자나 변호인이 참여할 기회가 보장되어야 한다.","ox":"O","m":"②","c":"A","tp":"위법수집증거배제법칙"},{"y":2023,"e":"국가직 9급","qn":1,"i":"N92023-01-3","t":"범죄의 피해자인 검사가 그 사건의 수사에 관여하거나, 압수ㆍ 수색영장의 집행에 참여한 검사가 다시 수사에 관여하였다면 그 자체로서 수사는 위법하고, 그에 따른 참고인이나 피의자의 진술은 임의성이 인정되지 않는다.","ox":"X","m":"③","c":"A","tp":"위법수집증거배제법칙"},{"y":2023,"e":"국가직 9급","qn":1,"i":"N92023-01-4","t":"수사기관이 구속수감된 자에게 압수된 그의 휴대전화를 제공하여 피고인과 통화하게 하고, 피고인의 범행에 관한 통화 내용을 녹음하게 한 행위는 불법감청에 해당하므로 이를 근거로 작성된 녹취록 첨부 수사보고서는 피고인의 범행에 대해 증거능력이 없다.","ox":"O","m":"④","c":"A","tp":"위법수집증거배제법칙"},{"y":2023,"e":"국가직 9급","qn":14,"i":"N92023-14","t":"증인신문에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"증인신문에 대한 설명으로 옳지 않은 것은?","d":"","o":["다른 증거나 증인의 진술에 비추어 굳이 추가 증거조사를 할 필요가 없다는 등 특별한 사정이 없고, 소재탐지나 구인장 발부가 불가능한 것이 아님에도 불구하고 법원이 불출석한 핵심 증인에 대하여 소재탐지나 구인장 발부 없이 증인채택 결정을 취소하는 것은 재량을 벗어나는 것으로서 위법하다.","피고인의 출석을 요하는 재판에서, 법원이 공판기일에 증인을 채택하여 다음 공판기일에 증인신문을 하기로 피고인에게 고지하였는데 그 다음 공판기일에 증인은 출석하였으나 피고인이 정당한 사유 없이 출석하지 아니한 경우, 법원이 이미 출석하여 있는 증인에 대하여 공판기일 외의 신문으로서 증인신문을 하고 다음 공판기일에 그 증인신문조서에 대한 서증조사를 하는 것은 증거조사절차로서 적법하다.","증인신문에 있어서 변호인에 대한 차폐시설의 설치는 이미 인적 사항에 관하여 비밀조치가 취해진 증인이 변호인을 대면하여 진술함으로써 자신의 신분이 노출되는 것에 대하여 심한 심리적인 부담을 느끼는 등의 특별한 사정이 있는 경우에 예외적으로 허용될 수 있을 뿐이다.","형사소송법 제221조의2(증인신문의 청구)에 의한 증인신문절차 에서는 피고인ㆍ피의자 또는 변호인의 참여가 필요적 요건이므로 피고인ㆍ피의자나 변호인이 증인신문절차에 참여하지 아니하였다면 위법이다. 2023년도 국가공무원 9급 공채 필기시험 형사"],"a":4}},{"y":2023,"e":"국가직 9급","qn":18,"i":"N92023-18-1","t":"진술이 기재된 서류가 그 진술을 하였다는 사실 자체에 대한 정황증거로 사용될 것이라는 이유로 그 서류의 증거능력이 인정된 다음 그 사실을 다시 진술 내용의 진실성을 증명하는 간접사실로 사용하면 그 서류는 전문증거에 해당한다.","ox":"O","m":"①","c":"A","tp":"전문증거의 증거능력"},{"y":2023,"e":"국가직 9급","qn":18,"i":"N92023-18-2","t":"검사가 작성한 피고인 아닌 자에 대한 진술조서에 관하여 피고인이 공판정 진술과 배치되는 부분은 부동의한다고 진술하였다면, 진술조서 중 부동의한 부분을 제외한 나머지 부분에 대해서는 피고인이 그 조서를 증거로 함에 동의한다는 취지로 해석하여야 한다.","ox":"X","m":"②","c":"A","tp":"전문증거의 증거능력"},{"y":2023,"e":"국가직 9급","qn":18,"i":"N92023-18-3","t":"검사의 조사를 받은 참고인이 법정에서 증언을 거부하여 피고인이 반대신문을 하지 못한 경우라도 그 증언거부권 행사가 정당하다면 형사소송법 제314조의 ‘그 밖에 이에 준하는 사유로 인하여 진술할 수 없는 때’에 해당하므로 특별한 사정이 없는 한 참고인에 대한 검사 작성 조서는 증거능력이 인정된다.","ox":"X","m":"③","c":"A","tp":"전문증거의 증거능력"},{"y":2023,"e":"국가직 9급","qn":18,"i":"N92023-18-4","t":"참고인의 진술을 내용으로 하는 조사자의 증언은, 그 참고인이 법정에 출석하여 조사 당시의 진술을 부인하는 취지로 증언하였더라도, 그 진술이 ‘특히 신빙할 수 있는 상태하에서 행하여졌음’이 증명되면 증거능력이 인정된다.","ox":"X","m":"④","c":"A","tp":"전문증거의 증거능력"},{"y":2024,"e":"국가직 9급","qn":8,"i":"N92024-08-1","t":"형사소송법 제312조제3항은 검사 이외의 수사기관이 작성한 해당 피고인과 공범관계에 있는 다른 피고인이나 피의자에 대한 피의자신문조서를 해당 피고인에 대한 유죄의 증거로 채택할 경우에도 적용되지만, 양벌규정에 따라 처벌되는 행위자와 행위자가 아닌 법인 또는 개인 간의 관계에는 적용되지 않는다.","ox":"X","m":"①","c":"A","tp":"피의자신문조서의 증거능력"},{"y":2024,"e":"국가직 9급","qn":8,"i":"N92024-08-2","t":"검사 작성의 피고인에 대한 피의자신문조서에 피고인의 서명만 있고 날인이나 간인이 없는 경우라도, 그와 같이 작성된 이유가 피고인이 당시 날인이나 간인을 거부하였기 때문이라는 취지가 조서 말미에 기재되어 있고, 피고인이 법정에서 그 피의자신문조서의 임의성을 인정하였다면 형식적 진정성립은 긍정된다.","ox":"X","m":"②","c":"A","tp":"피의자신문조서의 증거능력"},{"y":2024,"e":"국가직 9급","qn":8,"i":"N92024-08-3","t":"피고인이 법정에서 공소사실을 부인하면서도 검사가 작성한 피의자신문조서에 대하여 자신이 진술한 대로 기재되어 있다는 점을 명확하게 밝힌 경우, 그 피의자신문조서 중 공소사실을 인정하는 취지의 진술 기재 부분은 형사소송법 제312조제1항에 따라 증거능력이 인정된다.","ox":"X","m":"③","c":"A","tp":"피의자신문조서의 증거능력"},{"y":2024,"e":"국가직 9급","qn":8,"i":"N92024-08-4","t":"A에게 필로폰을 매도한 혐의로 기소된 甲이 검사 작성의 A에 대한 피의자신문조서 사본에 대하여 내용부인의 취지로 증거로 사용함에 부동의한 경우, 그 피의자신문조서 사본은 형사소송법 제312조제1항에 따라 甲에 대한 유죄의 증거로 사용할 수 없다.","ox":"O","m":"④","c":"A","tp":"피의자신문조서의 증거능력"},{"y":2024,"e":"국가직 9급","qn":9,"i":"N92024-09-1","t":"국민의 사생활 영역에 관계된 모든 증거의 제출이 곧바로 금지 되는 것으로 볼 수는 없으므로 법원으로서는 효과적인 형사소추 및 형사소송에서 진실발견이라는 공익과 개인의 인격적 이익 등 보호이익을 비교형량하여 그 허용 여부를 결정하여야 한다.","ox":"O","m":"①","c":"A","tp":"사인(私人)에 의한 위법수집증거"},{"y":2024,"e":"국가직 9급","qn":9,"i":"N92024-09-2","t":"택시 운전기사인 피고인이 자신의 택시에 승차한 피해자들에게 질문하여 지속적인 답변을 유도하는 등의 방법으로 피해자들과의 대화를 이어나가면서 그 대화 내용을 공개한 경우, 피해자들의 발언은 피고인에 대한 관계에서 통신비밀보호법 제3조제1항에서 정한 ‘타인 간의 대화’에 해당한다고 할 수 없다.","ox":"O","m":"②","c":"A","tp":"사인(私人)에 의한 위법수집증거"},{"y":2024,"e":"국가직 9급","qn":9,"i":"N92024-09-3","t":"사문서위조ㆍ위조사문서행사 및 소송사기의 형사소추를 위해 반드시 필요한 증거인 업무일지를 제3자가 절취하였고, 이를 피해자측이 수사기관에 증거자료로 제출하기 위해 대가를 지급 하고 취득한 경우라고 할지라도 그 업무일지를 증거로 제출하는 것은 허용될 수 있다.","ox":"O","m":"③","c":"A","tp":"사인(私人)에 의한 위법수집증거"},{"y":2024,"e":"국가직 9급","qn":9,"i":"N92024-09-4","t":"제3자가 권한 없이 비밀보호조치를 해제하는 방법으로 피고인이 공공업무용 전자문서관리시스템을 이용하여 발송한 전자우편을 수집한 후, 이를 공무원의 지위를 이용한 공직선거법 위반행위인 공소사실의 증거로 제출하는 것은 관련 법률에 따라 형사처벌되는 범죄행위일 뿐만 아니라 피고인의 기본권을 침해하는 행위이므로 허용될 수 없다.","ox":"X","m":"④","c":"A","tp":"사인(私人)에 의한 위법수집증거"},{"y":2024,"e":"국가직 9급","qn":17,"i":"N92024-17-1","t":"검사, 피고인 또는 변호인은 서류나 물건을 증거로 제출할 수 있고 증인ㆍ감정인ㆍ통역인 또는 번역인의 신문을 신청할 수 있다.","ox":"O","m":"①","c":"A","tp":"증거조사의 절차"},{"y":2024,"e":"국가직 9급","qn":17,"i":"N92024-17-2","t":"검사와 달리 피고인 또는 변호인이 증거신청을 하는 때에는 그 증거와 증명하고자 하는 사실과의 관계를 구체적으로 명시해야 하는 것은 아니다.","ox":"X","m":"②","c":"A","tp":"증거조사의 절차"},{"y":2024,"e":"국가직 9급","qn":17,"i":"N92024-17-3","t":"증거신청의 채택 여부는 법원의 재량으로서 법원이 필요하지 않다고 인정할 때에는 이를 조사하지 않을 수 있다.","ox":"O","m":"③","c":"A","tp":"증거조사의 절차"},{"y":2024,"e":"국가직 9급","qn":17,"i":"N92024-17-4","t":"법원은 증거신청에 대한 결정을 보류하는 경우, 증거신청인으로부터 당해 증거서류 또는 증거물을 제출받아서는 아니 된다.","ox":"O","m":"④","c":"A","tp":"증거조사의 절차"},{"y":2024,"e":"국가직 9급","qn":19,"i":"N92024-19-1","t":"동일한 사항에 관하여 두 개의 서로 다른 내용이 기재된 공판조서가 병존하는 경우 어느 쪽이 진실한 것으로 볼 것인지는 법관의 자유로운 심증에 따를 수밖에 없다.","ox":"O","m":"①","c":"A","tp":"공판조서의 증거능력과 증명력"},{"y":2024,"e":"국가직 9급","qn":19,"i":"N92024-19-2","t":"공판조서의 기재가 명백한 오기인 경우를 제외하고 공판기일의 소송절차로서 공판조서에 기재된 것은 조서만으로써 증명이 되지만, 그 증명력은 공판조서 이외의 자료에 의한 반증이 허용 되지 않는 절대적인 것은 아니다.","ox":"X","m":"②","c":"A","tp":"공판조서의 증거능력과 증명력"},{"y":2024,"e":"국가직 9급","qn":19,"i":"N92024-19-3","t":"공판조서의 기재가 소송기록상 명백한 오기인 경우에는 공판 조서는 그 올바른 내용에 따라 증명력을 가진다.","ox":"O","m":"③","c":"A","tp":"공판조서의 증거능력과 증명력"},{"y":2024,"e":"국가직 9급","qn":19,"i":"N92024-19-4","t":"공판조서에 기재되지 않은 소송절차의 존재는 공판조서에 기재된 다른 내용이나 공판조서 이외의 자료로 증명될 수 있고, 이는 자유로운 증명의 대상이 된다.","ox":"O","m":"④","c":"A","tp":"공판조서의 증거능력과 증명력"},{"y":2025,"e":"국가직 9급","qn":10,"i":"N92025-10","t":"수사기관에서 진술한 참고인이 법정에서 증언을 거부하여 피고인이 반대신문을 하지 못한 경우에는 정당하게 증언 거부권을 행사한 것이 아니라도, 피고인이 증인의 증언거부 상황을 초래하였다는 등의 특별한 사정이 없는 한 형사 소송법 제314조의 ‘그 밖에 이에 준하는 사유로 인하여 진술할 수 없는 때’에 해당하지 않는다고 보아야 한다.","c":"A","mc":{"s":"수사기관에서 진술한 참고인이 법정에서 증언을 거부하여 피고인이 반대신문을 하지 못한 경우에는 정당하게 증언 거부권을 행사한 것이 아니라도, 피고인이 증인의 증언거부 상황을 초래하였다는 등의 특별한 사정이 없는 한 형사 소송법 제314조의 ‘그 밖에 이에 준하는 사유로 인하여 진술할 수 없는 때’에 해당하지 않는다고 보아야 한다.","d":"전문법칙에 대한 설명으로 옳은 것만을 모두 고르면?\nㄱ. 타인의 진술을 내용으로 하는 진술이 전문증거인지는 요증 사실과의 관계에서 정하여지는데, 원진술의 내용인 사실이 요증사실인 경우에는 본래증거이나, 원진술의 존재 자체가 요증사실인 경우에는 전문증거이지 본래증거가 아니다.\nㄴ. 형사소송법 은 전문진술에 대하여 제316조에서 실질상 단순한 전문의 형태를 취하는 경우에 한하여 예외적으로 그 증거능력을 인정하는 규정을 두고 있을 뿐, 재전문진술 이나 재전문진술을 기재한 조서에 대하여는 달리 그 증거 능력을 인정하는 규정을 두고 있지 아니하고 있으므로, 피고인이 증거로 하는 데 동의하지 아니하는 한 형사소송법 제310조의2의 규정에 의하여 이를 증거로 할 수 없다.\nㄷ. 법원이 구속된 피의자를 심문하고 그에 대한 피의자의 진술 등을 기재한 구속적부심문조서는 공판준비 또는 공판 기일에 피고인이나 피고인 아닌 자의 진술을 기재한 조서 로서 형사소송법 제311조가 규정한 문서에 해당한다. ㄹ.","o":["ㄹ","ㄱ, ㄷ","ㄴ, ㄹ","ㄱ, ㄴ, ㄷ"],"a":3}},{"y":2025,"e":"국가직 9급","qn":15,"i":"N92025-15-1","t":"형사소송법 제297조의 규정에 따라 재판장은 증인이 피고인의 면전에서 충분한 진술을 할 수 없다고 인정한 때에는 피고인을 퇴정하게 하고 증인신문을 진행함으로써 피고인의 직접적인 증인 대면을 제한할 수 있지만, 이러한 경우에도 피고인의 반대 신문권을 배제하는 것은 허용되지 않는다.","ox":"O","m":"①","c":"A","tp":"증인신문과 증언거부권"},{"y":2025,"e":"국가직 9급","qn":15,"i":"N92025-15-2","t":"공무원이었던 자가 그 직무에 관하여 알게 된 사실에 관하여 본인 또는 당해 공무소가 직무상 비밀에 속한 사항임을 신고한 때에는 그 소속공무소 또는 감독관공서의 승낙 없이는 증인으로 신문하지 못하고, 그 소속공무소 또는 당해 감독관공서는 국가에 중대한 이익을 해하는 경우를 제외하고는 승낙을 거부하지 못한다.","ox":"O","m":"②","c":"A","tp":"증인신문과 증언거부권"},{"y":2025,"e":"국가직 9급","qn":15,"i":"N92025-15-3","t":"형사소송법에서 증언거부권의 대상으로 규정한 ‘공소제기를 당하거나 유죄판결을 받을 사실이 드러날 염려가 있는 증언’에 자신이 범행을 한 사실은 포함되지만 자신이 범행을 한 것으로 오인되어 유죄판결을 받을 우려가 있는 사실은 포함되지 않는다.","ox":"X","m":"③","c":"A","tp":"증인신문과 증언거부권"},{"y":2025,"e":"국가직 9급","qn":15,"i":"N92025-15-4","t":"형사소송법 제148조에서 ‘형사소추’는 증인이 이미 저지른 범죄사실에 대한 것을 의미한다고 할 것이므로, 증인의 증언에 의하여 비로소 범죄가 성립하는 경우에는 형사소송법 제160조, 제148조 소정의 증언거부권 고지 대상이 된다고 할 수 없다.","ox":"O","m":"④","c":"A","tp":"증인신문과 증언거부권"},{"y":2025,"e":"국가직 9급","qn":17,"i":"N92025-17-1","t":"공연히 사실을 적시하여 사람의 명예를 훼손한 행위가 형법 제310조의 규정에 따라서 위법성이 조각되어 처벌대상이 되지 않기 위하여는 그것이 진실한 사실로서 오로지 공공의 이익에 관한 때에 해당된다는 점을 행위자가 증명해야 한다.","ox":"O","m":"①","c":"A","tp":"거증책임"},{"y":2025,"e":"국가직 9급","qn":17,"i":"N92025-17-2","t":"기록상 진술증거의 임의성에 관하여 의심할 만한 사정이 나타나 있는 경우에는 법원은 직권으로 그 임의성 여부에 관하여 조사를 하여야 하고, 검사가 그 임의성의 의문점을 없애는 증명을 하지 못한 경우에는 그 진술증거는 증거능력이 부정된다.","ox":"O","m":"②","c":"A","tp":"거증책임"},{"y":2025,"e":"국가직 9급","qn":17,"i":"N92025-17-3","t":"형사재판에서 공소가 제기된 범죄의 구성요건을 이루는 사실은 그것이 주관적 요건이든 객관적 요건이든 그 증명책임이 검사에게 있다.","ox":"O","m":"③","c":"A","tp":"거증책임"},{"y":2025,"e":"국가직 9급","qn":17,"i":"N92025-17-4","t":"임의제출물을 압수한 경우 압수물이 형사소송법 제218조에 따라 실제로 임의제출된 것인지에 관하여 다툼이 있을 때에는 임의제출의 임의성을 의심할 만한 합리적이고 구체적인 사실을 피고인이 증명해야 한다.","ox":"X","m":"④","c":"A","tp":"거증책임"},{"y":2025,"e":"국가직 9급","qn":18,"i":"N92025-18","t":"자유심증주의에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"자유심증주의에 대한 설명으로 옳지 않은 것은?","d":"","o":["자유심증주의를 규정한 형사소송법 제308조가 증거의 증명력을 법관의 자유판단에 의하도록 한 것은 그것이 실체적 진실발견에 적합하기 때문이지 법관의 자의적인 판단을 인용한다는 것은 아니므로, 증거판단에 관한 전권을 가지고 있는 사실심 법관은 사실인정에 있어 공판절차에서 획득된 인식과 조사된 증거를 남김없이 고려하여야 한다.","공동피고인 중의 1인이 다른 공동피고인들과 공동하여 범행을 하였다고 자백한 경우, 반드시 그 자백을 전부 믿어 공동피고인들 전부에 대하여 유죄를 인정하거나 그 전부를 배척하여야 하는 것은 아니고, 자유심증주의의 원칙상 법원으로서는 자백한 피고인 자신의 범행에 관한 부분만을 취신하고, 다른 공동피고인들이 범행에 관여하였다는 부분을 배척할 수 있다.","살인죄와 같이 법정형이 무거운 범죄의 경우에도 직접증거 없이 간접증거만으로도 유죄를 인정할 수 있는데, 그 경우 주요사실의 전제가 되는 간접사실의 인정은 합리적 의심을 허용하지 않을 정도의 증명이 있어야 하는 것은 아니다.","참고인 A에 대한 경찰에서의 진술조서의 기재와 당해사건의 공판정에서 이루어진 증인으로서의 A의 진술이 상반되는 경우 반드시 공판정에서의 증언에 따라야 한다는 법칙은 없고 그중 어느 것을 채용하여 사실인정의 자료로 할 것인가는 오로지 사실심법원의 자유심증에 속하는 것이다. 2025년도 국가공무원 9급 공채 필기시험 형"],"a":3}}],"2":[{"y":2015,"e":"국가직 9급","qn":7,"i":"N92015-07-1","t":"검사는 공소제기 여부와 관련된 사실관계를 분명하게 하기 위해 필요한 경우 직권이나 피의자 또는 변호인의 신청에 의하여 전문수사자문위원을 지정하여 수사절차에 참여하게 하고, 자문을 들을 수 있다.","ox":"O","m":"①","c":"A"},{"y":2015,"e":"국가직 9급","qn":7,"i":"N92015-07-2","t":"피의자는 검사의 전문수사자문위원 지정에 대하여 관할 고등 검찰청 검사장에게 이의를 제기할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2015,"e":"국가직 9급","qn":7,"i":"N92015-07-3","t":"전문심리위원은 기일에 재판장의 허가를 받아 피고인 또는 변호인, 증인 또는 감정인 등 소송관계인에게 소송관계를 분명하게 하기 위하여 필요한 사항에 관하여 직접 질문할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2015,"e":"국가직 9급","qn":7,"i":"N92015-07-4","t":"전문심리위원은 첨단분야 등에 대한 전문적 지식을 가진 자로서 법원의 지정을 받아 공판에 참여하여 의견을 진술하고, 재판의 합의에 참여한다.","ox":"X","m":"④","c":"A"},{"y":2015,"e":"국가직 9급","qn":13,"i":"N92015-13","t":"불심검문에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"불심검문에 대한 설명으로 옳지 않은 것은?","d":"","o":["경찰관이 불심검문 대상자 해당 여부를 판단할 때에는 객관적․ 합리적인 기준에 따라야 하며, 불심검문 대상자에게 형사 소송법 상 체포나 구속에 이를 정도의 혐의가 있을 것은 요하지 않는다.","검문하는 사람이 경찰관이고, 검문하는 이유가 범죄행위에 관한 것임을 피검문자가 충분히 알고 있었던 경우 검문 시 경찰관이 신분증을 제시하지 않았더라도 위법이 아니다.","경찰관은 정지시킨 장소에서 질문을 하는 것이 피검문자에게 불리하거나 교통에 방해가 된다고 인정될 때에는 질문을 하기 위하여 가까운 경찰관서로 동행할 것을 요구할 수 있으며, 이 때 피검문자는 그 동행요구를 거절할 수 있다.","피검문자가 신분증을 교부한 후 경찰관에게 큰 소리로 욕설을 하자 경찰관이 모욕죄의 현행범으로 체포하겠다고 고지하고 나서 그의 어깨를 붙잡은 것은 적법하다. 형사"],"a":4}},{"y":2016,"e":"국가직 9급","qn":2,"i":"N92016-02-1","t":"임의동행의 형식으로 수사기관에 연행된 피내사자에게는 변호인 또는 변호인이 되려는 자와의 접견교통권은 인정되지 아니한다.","ox":"X","m":"①","c":"A"},{"y":2016,"e":"국가직 9급","qn":2,"i":"N92016-02-2","t":"보석보증금을 몰수하려면 반드시 보석취소와 동시에 하여야만 하고 보석취소 후에 별도로 보증금몰수결정을 할 수는 없다.","ox":"X","m":"②","c":"A","tp":"수사"},{"y":2016,"e":"국가직 9급","qn":2,"i":"N92016-02-3","t":"위법한 함정수사에 기한 공소제기는 그 절차가 법률의 규정에 위반하여 무효인 때에 해당한다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"국가직 9급","qn":2,"i":"N92016-02-4","t":"형사소송법 제244조의5에 의해서 피의자와 신뢰관계에 있는 자가 피의자 신문에 동석하여 피의자신문조서가 작성된 경우에, 동석한 자가 피의자를 대신하여 진술한 부분은 피의자신문 조서의 증거능력의 요건을 충족하여야 증거능력이 인정된다.","ox":"X","m":"④","c":"A","tp":"수사"},{"y":2016,"e":"국가직 9급","qn":5,"i":"N92016-05-1","t":"수사기관에 의한 진술거부권 고지의 대상이 되는 피의자의 지위는 수사기관이 범죄인지서를 작성하는 등의 형식적인 사건수리 절차를 거치기 전이라도 조사대상자에 대하여 범죄의 혐의가 있다고 보아 실질적으로 수사를 개시하는 행위를 한 때에 인정된다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"국가직 9급","qn":5,"i":"N92016-05-2","t":"헌법 제12조 제2항은 진술거부권을 국민의 기본적 권리로 보장 하고 있으며, 이는 형사책임과 관련하여 비인간적인 자백의 강요와 고문을 근절하고 인간의 존엄성과 가치를 보장하려는 데에 그 취지가 있으므로, 진술거부권이 보장되는 절차에서 진술거부권을 고지받을 권리는 헌법 제12조 제2항에 의하여 바로 도출된다.","ox":"X","m":"②","c":"A"},{"y":2016,"e":"국가직 9급","qn":5,"i":"N92016-05-3","t":"사법경찰관이 피의자에게 진술거부권을 행사할 수 있음을 알려 주고 그 행사 여부를 질문하였다 하더라도, 형사소송법 제244조의3 제2항에 규정한 방식에 위반하여 진술거부권 행사 여부에 대한 피의자의 답변이 자필로 기재되어 있지 아니하거나 그 답변 부분에 피의자의 기명날인 또는 서명이 되어 있지 아니한 사법경찰관 작성의 피의자신문조서는 특별한 사정이 없는 한 증거능력이 없다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"국가직 9급","qn":5,"i":"N92016-05-4","t":"수사기관이 피의자를 신문함에 있어서 피의자에게 미리 진술 거부권을 고지하지 않은 때에는 그 피의자의 진술은 위법하게 수집된 증거로서 진술의 임의성이 인정되는 경우라도 증거 능력이 부인되어야 한다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"국가직 9급","qn":9,"i":"N92016-09","t":"고소 등에 대한 설명으로 옳은 것만을 모두 고른 것은?","c":"A","mc":{"s":"고소 등에 대한 설명으로 옳은 것만을 모두 고른 것은?","d":"(다툼이 있는 경우 판례에 의함)\nㄱ. 피해사실을 이해하고, 고소에 따른 사회생활상의 이해 관계를 알아차릴 수 있는 사실상의 의사능력이 있다 하더라도 민법상의 행위능력이 없으면 고소능력은 인정되지 않는다.\nㄴ. 친고죄에서 적법한 고소가 있었는지는 자유로운 증명의 대상이 되고, 일죄의 관계에 있는 범죄사실의 일부에 대한 고소의 효력은 일죄 전부에 대하여 미친다.\nㄷ. 반의사불벌죄에서 피해자가 사망하여 직접 처벌희망 또는 처벌불원의 의사표시를 할 수 없는 경우 제1심 판결 선고 전에 피해자의 상속인이 피해자를 대신하여 처벌불원의 의사표시를 할 수 있다.\nㄹ. 고소는 범죄의 피해자 기타 고소권자가 수사기관에 대하여 범죄사실을 신고하여 범인의 소추․처벌을 구하는 의사표시를 말하는 것으로서, 단순한 피해사실의 신고는 소추․처벌을 구하는 의사표시가 아니므로 고소가 아니다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"a":3}},{"y":2018,"e":"국가직 9급","qn":12,"i":"N92018-12","t":"함정수사에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"함정수사에 대한 설명으로 옳지 않은 것은?","d":"","o":["피고인이 본래 범의를 가지지 아니하였는데 수사기관의 사술 또는 계략으로 인해 범의를 일으켜 행위한 것으로 인정된다면 법원은 무죄판결을 하여야 한다.","구체적인 사건에서 위법한 함정수사에 해당하는지 여부는 해당 범죄의 종류와 성질, 유인자의 지위와 역할, 유인의 경위와 방법, 유인에 따른 피유인자의 반응, 피유인자의 처벌 전력 및 유인행위 자체의 위법성 등을 종합하여 판단하여야 한다.","경찰관들이 노래방 단속실적을 올리기 위하여 평소 손님들에게 도우미 알선영업을 해왔다는 자료나 첩보가 없음에도 노래방에 손님을 가장하고 들어가 도우미를 불러 줄 것을 재차 요구한 후 이를 단속하였다면 이는 위법한 함정수사에 해당한다.","수사기관과 직접 관련이 없는 사인(私人)이 피고인에게 범죄의 실행을 부탁한 경우, 그로 인하여 피고인의 범의가 유발되었다 하더라도 이는 위법한 함정수사에 해당하지 아니한다. 형사"],"a":1}},{"y":2019,"e":"국가직 9급","qn":1,"i":"N92019-01-1","t":"피고인이 증거서류의 진정성립을 묻는 검사의 질문에 대하여 진술거부권을 행사하여 진술을 거부한 경우는 형사소송법 제314조의 ‘그 밖에 이에 준하는 사유로 인하여 진술할 수 없는 때’에 해당하지 아니한다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"국가직 9급","qn":1,"i":"N92019-01-2","t":"헌법상 진술거부권이 보장되므로, 진술거부권이 보장되는 절차에서 진술거부권을 고지받을 권리를 인정하기 위하여 별도의 입법적 뒷받침이 필요한 것은 아니다.","ox":"X","m":"②","c":"A"},{"y":2019,"e":"국가직 9급","qn":1,"i":"N92019-01-3","t":"헌법상 보장된 진술거부권에 비추어 볼 때, 교통사고를 낸 차의 운전자 등의 신고의무는 사고의 규모나 당시의 구체적인 상황에 따라 피해자의 구호 및 교통질서의 회복을 위하여 당사자의 개인적인 조치를 넘어 경찰관의 조직적 조치가 필요하다고 인정되는 경우에만 있는 것이다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"국가직 9급","qn":1,"i":"N92019-01-4","t":"조사대상자의 진술내용이 자신과 제3자에게 공동으로 관련된 범죄에 관한 것이거나 제3자의 피의사실뿐만 아니라 자신의 피의사실에 관한 것이기도 하여 그 실질이 피의자신문조서의 성격을 가지는 경우에 수사기관은 그 진술을 듣기 전에 미리 진술거부권을 고지하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"국가직 9급","qn":3,"i":"N92019-03-1","t":"적법한 구속영장이 발부된 이상 수사기관으로서는 피의자신문을 위해 그 구속영장의 효력에 의하여 구금된 피의자를 조사실로 구인할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"국가직 9급","qn":3,"i":"N92019-03-2","t":"수사기관이 진술자의 성명을 가명으로 기재하여 조서를 작성 하였다고 해서 그 이유만으로 그 조서가 ‘적법한 절차와 방식’에 따라 작성되지 않았다고 할 것은 아니다.","ox":"O","m":"②","c":"A","tp":"피의자신문"},{"y":2019,"e":"국가직 9급","qn":3,"i":"N92019-03-3","t":"검사가 피고인의 공판절차에서 이미 증언을 마친 증인에게 수사기관에 출석할 것을 요구하여 그 증인을 상대로 위증의 혐의를 조사한 내용을 담은 피의자신문조서는 그 피고인이 증거로 함에 동의하더라도 증거능력이 인정되지 않는다.","ox":"X","m":"③","c":"A"},{"y":2019,"e":"국가직 9급","qn":3,"i":"N92019-03-4","t":"피의자의 진술을 영상녹화하는 경우 미리 그 사실을 알려주어야 하며, 조사의 개시부터 종료까지의 전 과정 및 객관적 정황을 영상녹화하여야 한다.","ox":"O","m":"④","c":"A","tp":"피의자신문"},{"y":2024,"e":"국가직 9급","qn":15,"i":"N92024-15","t":"경찰관의 불심검문이 적법하려면 불심검문 대상자에게 형사소송법 상 체포나 구속에 이를 정도의 혐의가 있을 것을 요한다.","c":"A","mc":{"s":"경찰관의 불심검문이 적법하려면 불심검문 대상자에게 형사소송법 상 체포나 구속에 이를 정도의 혐의가 있을 것을 요한다.","d":"불심검문에 대한 설명으로 옳은 것만을 모두 고르면?\nㄱ.\nㄴ. 검문하는 사람이 경찰관이고 검문하는 이유가 범죄행위에 관한 것임을 불심검문 대상자가 충분히 알고 있었다고 보이는 경우라도 경찰관이 그에게 신분증을 제시하지 않았다면 그 불심검문은 위법한 공무집행이다.\nㄷ. 경찰관은 불심검문하여 경찰관 직무집행법 에 따라 경찰관서로 임의동행한 사람을 6시간을 초과하여 경찰관서에 머물게 할 수 없다.\nㄹ. 경찰관이 피의자를 불심검문 대상자로 삼은 조치가 그에 대한 불심검문 당시의 구체적 상황과 자신들의 사전 지식 및 경험칙에 기초하여 객관적ㆍ합리적 판단과정을 거쳐 이루어진 것이라면, 그의 인상착의가 미리 입수된 용의자에 대한 인상착의와 일부 일치하지 않는 부분이 있더라도 그것만으로 경찰관이 그를 불심검문 대상자로 삼은 조치가 위법하다고 볼 수는 없다.","o":["ㄷ","ㄱ, ㄹ","ㄴ, ㄷ","ㄷ, ㄹ"],"a":4}},{"y":2025,"e":"국가직 9급","qn":8,"i":"N92025-08","t":"수사에 대한 설명으로 옳은 것만을 모두 고르면?","c":"A","mc":{"s":"수사에 대한 설명으로 옳은 것만을 모두 고르면?","d":"ㄱ. 구속영장 발부에 의하여 적법하게 구금된 피의자가 피의자 신문을 위한 출석요구에 응하지 아니하면서 수사기관 조사실에 출석하기를 거부하더라도 수사기관은 그 구속영장의 효력에 의하여 피의자를 조사실로 구인할 수는 없다.\nㄴ. 통신비밀보호법 의 ‘감청’이란 대상이 되는 전기통신의 송ㆍ수신과 동시에 이루어지는 경우만을 의미하고, 여기에 이미 수신이 완료된 전기통신의 내용을 지득하는 행위는 포함되지 않는다.\nㄷ. 검사 또는 사법경찰관은 형사소송법 제216조제1항제2호에 따라 압수한 물건을 계속 압수할 필요가 있는 경우에는 지체 없이 압수ㆍ수색영장을 청구하여야 한다. 이 경우 압수ㆍ수색영장의 청구는 압수한 때부터 48시간 이내에 하여야 한다.\nㄹ. 수사기관에 의한 진술거부권 고지의 대상이 되는 피의자의 지위는 수사기관이 범죄인지서를 작성하는 등의 형식적인 사건수리 절차를 거치기 전이라도 조사대상자에 대하여 범죄혐의가 있다고 보아 실질적으로 수사를 개시하는 행위를 한 때에 인정된다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"a":3}}],"3":[{"y":2015,"e":"국가직 9급","qn":8,"i":"N92015-08-1","t":"경찰관이 간호사로부터 진료 목적으로 채혈된 甲의 혈액 중 일부를 주취운전 여부에 대한 감정을 목적으로 제출받아 압수한 경우 특별한 사정이 없는 한 그 압수절차가 甲 또는 그의 가족의 동의 및 영장 없이 행하여졌더라도 적법절차의 위반이 아니다.","ox":"O","m":"①","c":"A","tp":"압수․수색"},{"y":2015,"e":"국가직 9급","qn":8,"i":"N92015-08-2","t":"수사기관이 피의자 甲의 공직선거법 위반 혐의로 발부받은 압수·수색영장의 집행과정에서 甲의 혐의사실과 무관한 乙과 丙 사이의 대화가 녹음된 파일을 압수한 경우 위 녹음파일은 위법수집증거이므로 乙과 丙의 공직선거법 위반 혐의사실을 입증하는 증거로 사용할 수 없다.","ox":"O","m":"②","c":"A","tp":"압수․수색"},{"y":2015,"e":"국가직 9급","qn":8,"i":"N92015-08-3","t":"음주운전과 관련한 도로교통법 위반죄의 수사를 위하여 미성년자인 피의자의 혈액채취가 필요한 경우 피의자에게 의사능력이 없는 때에는 법정대리인이 피의자를 대리하여 동의하면 영장 없이 혈액을 채취할 수 있다.","ox":"X","m":"③","c":"A","tp":"압수․수색"},{"y":2015,"e":"국가직 9급","qn":8,"i":"N92015-08-4","t":"경찰관이 음주운전자를 단속하면서 주취운전이라는 범죄행위로 체포·구속하지 아니한 경우에도 필요하다면 그 음주운전자의 차량열쇠는 영장 없이 압수할 수 있다.","ox":"O","m":"④","c":"A","tp":"압수․수색"},{"y":2015,"e":"국가직 9급","qn":9,"i":"N92015-09","t":"괄호 안에 들어갈 일시로 옳은 것은?","c":"A","mc":{"s":"괄호 안에 들어갈 일시로 옳은 것은?","d":"강도사건 피의자 甲은 2014. 4. 12. 09:00 체포영장이 발부되어 2014. 4. 13. 10:00 체포되었다. 이에 甲의 변호인은 체포 당일 체포적부심을 청구하였고, 2014. 4. 14. 11:00 수사 관계 서류와 증거물이 법원에 접수되어 청구기각결정 후 2014. 4. 15. 13:00 검찰청에 반환되었다. 이 때 검사가 甲에 대한 구속영장을 법원에 청구할 수 있는 일시는 ( ㉠ )까지이고, 사법경찰관이 구속영장에 의해 甲을 구속한 후 사법경찰관이 구속할 수 있는 일시는 ( ㉡ ) 까지이다.  ㉠ ㉡","o":["2014. 4. 15. 10:00 2014. 4. 22. 24:00","2014. 4. 16. 12:00 2014. 4. 22. 24:00","2014. 4. 16. 12:00 2014. 4. 24. 24:00","2014. 4. 16. 24:00 2014. 4. 24. 24:00"],"a":3}},{"y":2015,"e":"국가직 9급","qn":14,"i":"N92015-14","t":"보석에 대한 설명으로 옳은 것만을 모두 고른 것은?","c":"A","mc":{"s":"보석에 대한 설명으로 옳은 것만을 모두 고른 것은?","d":"(다툼이 있는 경우 판례에 의함)\nㄱ. 법원은 특별한 사정이 없는 한 보석청구를 받은 날부터 7일 이내에 그에 관한 결정을 하여야 한다.\nㄴ. 피고인이 보석조건을 위반한 경우 과태료 또는 감치의 제재결정을 내릴 수 있으며, 이 제재결정에 대해서는 즉시항고를 할 수 있다.\nㄷ. 범죄사실과 관련하여 피고인에 대한 새로운 중요한 증거가 발견된 경우 법원은 보석을 취소할 수 있다.\nㄹ. 보증금 몰수사건은 지방법원 단독판사의 관할이지만 소송절차 계속 중에 보석허가결정이나 그 취소결정을 본안 관할법원인 제1심 합의부가 한 경우 당해 합의부가 사물관할을 갖는다.","o":["ㄱ, ㄴ","ㄴ, ㄷ","ㄱ, ㄴ, ㄹ","ㄱ, ㄷ, ㄹ"],"a":1}},{"y":2016,"e":"국가직 9급","qn":13,"i":"N92016-13-1","t":"선거관리위원회 위원·직원이 관계인에게 진술이 녹음된다는 사실을 미리 알려 주지 아니한 채 진술을 녹음하였다면, 그와 같은 조사절차에 의하여 수집한 녹음파일 내지 그에 터잡아 작성된 녹취록은 형사소송법 제308조의2에서 정하는 ‘적법한 절차에 따르지 아니하고 수집한 증거’에 해당하여 원칙적으로 유죄의 증거로 쓸 수 없다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"국가직 9급","qn":13,"i":"N92016-13-2","t":"위법한 강제연행 상태에서 호흡측정방법에 의한 음주측정을 한 다음, 강제연행 상태로부터 시간적·장소적으로 단절되었다고 볼 수 없는 상황에서 피의자가 호흡측정결과를 탄핵하기 위하여 스스로 혈액채취방법에 의한 측정을 할 것을 요구하여 혈액채취가 이루어진 경우 그러한 혈액채취에 의한 측정 결과는 유죄 인정의 증거로 쓸 수 있다.","ox":"X","m":"②","c":"A"},{"y":2016,"e":"국가직 9급","qn":13,"i":"N92016-13-3","t":"현장에서 압수·수색을 당하는 사람이 여러 명일 경우에는 그 사람들 모두에게 개별적으로 영장을 제시해야 하는 것이 원칙이다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"국가직 9급","qn":13,"i":"N92016-13-4","t":"수사기관이 甲으로부터 乙의 마약류 관리에 관한 법률 위반 범행에 대한 진술을 듣고 추가적인 증거를 확보할 목적으로, 구속수감중인 甲에게 그의 압수된 휴대전화를 제공하여 乙과 통화하고 범행에 관한 통화 내용을 녹음하게 한 행위는 불법감청에 해당하고, 그 녹음자체는 물론 이를 근거로 작성된 녹취록 첨부 수사보고서도 증거로 사용할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"국가직 9급","qn":18,"i":"N92016-18-1","t":"수사기관 사무실 등으로 반출된 전자정보 저장매체에서 혐의 사실 관련성에 대한 구분 없이 임의로 저장된 전자정보를 문서로 출력하는 행위는 원칙적으로 영장주의 원칙에 반하는 위법한 압수가 된다.","ox":"O","m":"①","c":"A","tp":"전자정보의 압수․수색"},{"y":2016,"e":"국가직 9급","qn":18,"i":"N92016-18-2","t":"전자정보 저장매체를 수사기관 사무실 등으로 옮겨 복제·탐색·출력하는 경우에도 변호인에게 참여의 기회를 보장하지 않으면 위법하다.","ox":"O","m":"②","c":"A","tp":"전자정보의 압수․수색"},{"y":2016,"e":"국가직 9급","qn":18,"i":"N92016-18-3","t":"전자정보에 대한 압수·수색이 종료되기 전에 혐의사실과 관련된 전자정보를 적법하게 탐색하는 과정에서 별도의 범죄 혐의와 관련된 전자정보를 우연히 발견한 경우라면 따로 압수·수색영장을 발부받지 않고 이 전자정보를 적법하게 압수·수색할 수 있다.","ox":"X","m":"③","c":"A","tp":"전자정보의 압수․수색"},{"y":2016,"e":"국가직 9급","qn":18,"i":"N92016-18-4","t":"전자정보에 대한 압수·수색 과정에서 이루어진 현장에서의 저장매체 압수·이미징·탐색·복제 및 출력행위 등 수사 기관의 처분은 하나의 영장에 의한 압수·수색 과정에서 이루어지므로, 당해 압수·수색 과정 전체를 하나의 절차로 파악하여 그 과정에서 나타난 위법이 압수·수색 절차 전체를 위법하게 할 정도로 중대한지 여부에 따라 전체적으로 압수·수색 처분을 취소할 것인지를 판단하여야 한다.","ox":"O","m":"④","c":"A","tp":"전자정보의 압수․수색"},{"y":2017,"e":"국가직 9급","qn":2,"i":"N92017-02-1","t":"피의자가 마약투약을 하였다고 의심할 만한 상당한 이유가 있었더라도, 경찰관이 이미 피의자의 신원과 주거지 및 전화 번호 등을 모두 파악하고 있었고 당시 증거가 급속하게 소멸될 상황도 아니었다면 긴급체포의 요건으로 미리 체포영장을 받을 시간적 여유가 없었던 경우에 해당하지 않는다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"국가직 9급","qn":2,"i":"N92017-02-2","t":"긴급체포 후 석방된 자 또는 그 변호인·법정대리인·배우자·직계친족·형제자매는 통지서 및 관련 서류를 열람하거나 등사할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"국가직 9급","qn":2,"i":"N92017-02-3","t":"수사기관이 긴급체포된 자에 대하여 구속영장을 청구하지 아니하거나 발부받지 못한 때에는 피의자를 즉시 석방하여야 하고, 이 경우 석방된 자는 영장 없이는 동일한 범죄사실에 관하여 체포하지 못한다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"국가직 9급","qn":2,"i":"N92017-02-4","t":"사법경찰관이 검사에게 긴급체포된 피의자에 대한 승인 건의와 함께 구속영장을 신청한 경우 검사는 긴급체포의 합당성이나 구속영장 청구에 필요한 사유를 보강하기 위하여 긴급체포한 피의자를 검찰청으로 출석시켜 직접 대면 조사할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2017,"e":"국가직 9급","qn":10,"i":"N92017-10","t":"다음 사법경찰관의 압수․수색 중 적법하지 않은 것은?","c":"A","mc":{"s":"다음 사법경찰관의 압수․수색 중 적법하지 않은 것은?","d":"","o":["음주운전 중 교통사고를 당하여 의식불명 상태에 빠져 병원에 후송된 피의자에 대해 사법경찰관이 수사의 목적으로 피의자의 가족으로부터 동의를 받고 의료진에게 요청하여 피의자의 혈액을 채취하였으나 사후 압수․수색영장을 발부받지 않았다.","음란물유포의 범죄혐의를 이유로 압수․수색영장을 발부받은 사법경찰관이 피의자의 주거지를 수색하는 과정에서 대마를 발견하자 피의자를 마약류관리에관한법률위반죄의 현행범으로 체포하면서 대마를 압수하고 그 다음 날 피의자를 석방하면서 압수한 대마에 대해 사후 압수․수색영장을 발부받았다.","사법경찰관이 현행범 체포의 현장에서 소지자로부터 임의로 제출하는 물건을 영장 없이 압수하고 사후에 압수․수색 영장을 발부받지 않았다.","사법경찰관은 2017.3.1. 10 : 00 보이스피싱 혐의로 피의자를 긴급체포하고 그 다음 날인 3.2. 09 : 00 피의자가 보관하고 있던 다른 사람의 주민등록증을 발견하고 압수한 다음, 그것을 계속 압수할 필요가 있다고 판단하여 곧바로 검사에게 사후 영장 청구를 신청하였고 검사는 같은 날 11 : 00 사후영장을 청구하였다."],"a":1}},{"y":2018,"e":"국가직 9급","qn":1,"i":"N92018-01","t":"다음 사례에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"다음 사례에 대한 설명으로 옳지 않은 것은?","d":"(다툼이 있는 경우 판례에 의함) 경찰관은 절도범을 현행범으로 체포하면서 상의 주머니와 소지품을 수색하여 지갑과 노트북 1대를 압수하였다. 그 이후 노트북은 피의자의 소유인 것으로 확인하여 돌려주었다가, 추가 수사의 목적으로 다시 임의제출 받았다.","o":["노트북 1대를 임의제출 받는 과정에서 제출에 임의성이 있었다는 점에 대해서는 검사가 입증해야 한다.","지갑이 체포범죄사실과 관련성이 있다면 압수영장 없이 압수했더라도 적법하다.","현행범 체포과정에서 적법하게 압수한 것이라도 계속 압수할 필요성이 있으면 압수한 때로부터 48시간 내에 사후압수영장을 받아야 한다.","현행범으로 체포하면서 현장에서 범인의 상의 주머니를 수색한 행위는 적법하다."],"a":3}},{"y":2018,"e":"국가직 9급","qn":3,"i":"N92018-03-1","t":"법원으로부터 감정처분허가장이 아닌 혈액에 대한 압수영장을 발부받아 피의자의 신체로부터 혈액을 채취하는 행위는 위법한 강제수사이다.","ox":"X","m":"①","c":"A","tp":"수사의 적법성"},{"y":2018,"e":"국가직 9급","qn":3,"i":"N92018-03-2","t":"검찰수사관이 피의자신문에 참여한 변호인에게 피의자 후방에 앉으라고 요구한 행위는 이를 정당화할 특별한 사정이 없는 한 변호인의 변호권을 침해하므로 헌법에 위배된다.","ox":"O","m":"②","c":"A","tp":"수사의 적법성"},{"y":2018,"e":"국가직 9급","qn":3,"i":"N92018-03-3","t":"응급구호가 필요한 자살기도자를 영장 없이 24시간을 초과하지 아니하는 범위에서 경찰서에 설치되어 있는 보호실에 유치한 것은 위법한 강제수사가 아니다.","ox":"O","m":"③","c":"A","tp":"수사의 적법성"},{"y":2018,"e":"국가직 9급","qn":3,"i":"N92018-03-4","t":"수사기관이 범행 중 또는 직후에 증거보전의 필요성, 긴급성이 있어서 상당한 방법으로 사진을 촬영한 경우라면 영장 없는 사진촬영도 위법한 수사가 아니다.","ox":"O","m":"④","c":"A","tp":"수사의 적법성"},{"y":2018,"e":"국가직 9급","qn":17,"i":"N92018-17-1","t":"피고인이 사형, 무기 또는 장기 10년이 넘는 징역이나 금고에 해당하는 죄를 범한 경우에도 법원이 직권으로 보석을 허가할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"국가직 9급","qn":17,"i":"N92018-17-2","t":"구속된 피고인 외에도 그 변호인·법정대리인·배우자·직계친족·형제자매·가족·동거인·고용주가 보석을 청구할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"국가직 9급","qn":17,"i":"N92018-17-3","t":"법원은 보석청구자 이외의 자에게 보증금의 납입을 허가할 수 있고, 유가증권으로써 보증금에 갈음함을 허가할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"국가직 9급","qn":17,"i":"N92018-17-4","t":"보석으로 석방된 피고인이 재판 중 법원의 소환에 불응한 경우 법원은 직권 또는 검사의 청구에 따라 결정으로 보증금의 전부 또는 일부를 몰수하여야 한다.","ox":"X","m":"④","c":"A"},{"y":2018,"e":"국가직 9급","qn":20,"i":"N92018-20-1","t":"체포적부심을 신청한 피의자에 대하여 법원은 직권으로 보증금 납입조건부 석방결정을 할 수 있다.","ox":"X","m":"①","c":"A","tp":"체포․구속적부심사제도"},{"y":2018,"e":"국가직 9급","qn":20,"i":"N92018-20-2","t":"심사청구 후 검사가 전격 기소한 경우에도 법원은 심사청구에 대한 판단을 해야 한다.","ox":"O","m":"②","c":"A","tp":"체포․구속적부심사제도"},{"y":2018,"e":"국가직 9급","qn":20,"i":"N92018-20-3","t":"구속영장을 발부한 법관도 구속적부심사의 심문, 조사, 결정에 관여할 수 있는 경우가 있다.","ox":"O","m":"③","c":"A","tp":"체포․구속적부심사제도"},{"y":2018,"e":"국가직 9급","qn":20,"i":"N92018-20-4","t":"법원은 공동피의자의 연속적인 심사청구가 수사방해의 목적임이 명백한 경우에는 심문 없이 기각할 수 있다.","ox":"O","m":"④","c":"A","tp":"체포․구속적부심사제도"},{"y":2019,"e":"국가직 9급","qn":8,"i":"N92019-08","t":"형사소송법 제33조제1항은 국선변호인을 반드시 선정 해야 하는 사유를 정하고 있는데, 그 제1호에서 정한 ‘피고인이 구속된 때’라고 함에는 피고인이 별건으로 구속된 경우가 제외되는 것은 아니다.","c":"A","mc":{"s":"형사소송법 제33조제1항은 국선변호인을 반드시 선정 해야 하는 사유를 정하고 있는데, 그 제1호에서 정한 ‘피고인이 구속된 때’라고 함에는 피고인이 별건으로 구속된 경우가 제외되는 것은 아니다.","d":"체포 및 구속에 대한 설명으로 옳은 것만을 모두 고르면? (다툼이 있는 경우 판례에 의함)\nㄱ. 긴급체포의 요건을 갖추었는지 여부는 사후에 밝혀진 사정을 기초로 판단하는 것이 아니라 체포 당시의 상황을 기초로 판단하여야 한다.\nㄴ. 구속집행 당시 영장이 제시되지는 않았으나, 피고인이 청구한 구속적부심사절차에서 영장을 제시받아 그 기재된 범죄사실을 숙지하고 있으며, 구속 중 이루어진 법정 진술의 임의성 등을 다투지 않고 오히려 변호인과의 충분한 상의를 거친 후 공소사실 전부에 대하여 자백한 경우라면, 그 자백을 증거로 할 수 있다.\nㄷ. 현행범인 체포의 적법성과 관련하여 체포사유의 판단은 현행범인체포서에 기재된 죄명에 의하여야만 한다. ㄹ.","o":["ㄱ, ㄴ","ㄱ, ㄹ","ㄴ, ㄷ","ㄷ, ㄹ"],"a":1}},{"y":2020,"e":"국가직 9급","qn":5,"i":"N92020-05","t":"구속에 대한 설명으로 옳은 것은?","c":"A","mc":{"s":"구속에 대한 설명으로 옳은 것은?","d":"","o":["구속기간의 만료로 피고인에 대한 구속의 효력이 상실된 후 항소법원이 판결을 선고하면서 피고인을 구속한 것은 실질적으로 재구속 또는 이중구속에 해당되므로 위법하다.","법원이 구속된 피고인의 구속집행정지의 결정을 함에 있어서 급속을 요하는 경우가 아닌 한 검사의 의견을 물어야 하지만, 구속집행정지결정에 대한 검사의 즉시항고는 허용되지 않는다.","구속의 사유가 소멸된 때에는 법원은 직권 또는 검사, 피고인, 변호인 등의 청구에 의하여 결정으로 구속을 취소하여야 하므로, 구속중인 피고인에 대하여 자유형(실형)의 판결이 확정된 때에는 법원은 구속의 취소 결정을 하여야 한다.","수사 당시 긴급체포되었다가 수사기관의 조치로 석방된 피의자를 동일한 범죄사실에 관하여 법원이 발부한 구속영장에 의하여 수사기관이 다시 구속하는 것은 위법하다. 2020년도 국가공무원 9급 공채 필기시험 형사"],"a":2}},{"y":2020,"e":"국가직 9급","qn":9,"i":"N92020-09","t":"형법 의 강도죄를 범한 자와 관련하여 형사소송법 의 기간의 적용에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"형법 의 강도죄를 범한 자와 관련하여 형사소송법 의 기간의 적용에 대한 설명으로 옳지 않은 것은?","d":"(기간 연장은 고려하지 않음)","o":["2020년 6월 1일(월) 23시에 피의자를 구속한 경찰관은 2020년 6월 10일(수) 24시까지 피의자를 검사에게 인치하여야 한다.","2020년 6월 2일(화) 17시에 공소가 제기된 피고인에 대한 제1심의 구속기간은 2020년 8월 1일(토) 24시까지이다.","2020년 6월 2일(화) 14시에 제1심 공판정에 출석하여 유죄 판결을 선고받은 피고인은 2020년 6월 8일(월) 24시까지 항소를 제기할 수 있다.","2020년 6월 1일(월) 14시에 항소장을 받은 원심법원은 항소를 기각하는 경우가 아닌 한 2020년 6월 15일(월) 24시까지 소송기록과 증거물을 항소법원에 송부하여야 한다."],"a":3}},{"y":2020,"e":"국가직 9급","qn":19,"i":"N92020-19-1","t":"압수의 대상은 압수·수색영장의 범죄사실 자체와 직접적으로 연관된 물건에 한정되지 않으므로, 압수·수색영장의 범죄사실과 기본적 사실관계가 동일한 범행 또는 동종·유사의 범행과 관련된다고 의심할 만한 상당한 이유가 있는 범위 내에서는 압수를 실시할 수 있다.","ox":"O","m":"①","c":"A","tp":"압수와 수색"},{"y":2020,"e":"국가직 9급","qn":19,"i":"N92020-19-2","t":"압수·수색영장의 집행에 있어서 여관, 음식점 기타 야간에 공중이 출입할 수 있는 장소는 공개한 시간 내에 한하여 야간집행의 제한을 받지 않는다.","ox":"O","m":"②","c":"A","tp":"압수와 수색"},{"y":2020,"e":"국가직 9급","qn":19,"i":"N92020-19-3","t":"전자정보에 대한 압수·수색이 종료되기 전에 혐의사실과 관련된 전자정보를 적법하게 탐색하는 과정에서 별도의 범죄혐의와 관련된 전자정보를 우연히 발견한 경우라면, 수사기관은 더 이상의 추가 탐색을 중단하고 법원에서 별도의 범죄혐의에 대한 압수·수색영장을 발부받은 경우에 한하여 그 정보에 대하여 적법하게 압수·수색을 할 수 있다.","ox":"O","m":"③","c":"A","tp":"압수와 수색"},{"y":2020,"e":"국가직 9급","qn":19,"i":"N92020-19-4","t":"검사 또는 사법경찰관은 현행범 체포현장이나 범죄장소에서 소지자 등이 임의로 제출하는 물건을 영장 없이 압수할 수 있다. 다만, 이 경우에 검사나 사법경찰관은 사후에 영장을 받아야 한다.","ox":"X","m":"④","c":"A","tp":"압수와 수색"},{"y":2021,"e":"국가직 9급","qn":5,"i":"N92021-05-1","t":"증거물을 압수하였을 때에는 압수조서 및 압수목록을 작성 하여야 하지만, 수색한 결과 증거물이 없는 경우에는 그 취지의 증명서를 교부할 필요는 없다.","ox":"X","m":"①","c":"A","tp":"압수․수색"},{"y":2021,"e":"국가직 9급","qn":5,"i":"N92021-05-2","t":"수사기관이 압수·수색영장을 제시하고 압수·수색을 실시하여 그 집행을 종료하였다 하더라도 영장의 유효기간이 남아 있다면 아직 그 영장의 효력이 상실되지 않았으므로, 동일한 장소에 대하여 다시 압수·수색할 수 있다.","ox":"X","m":"②","c":"A","tp":"압수․수색"},{"y":2021,"e":"국가직 9급","qn":5,"i":"N92021-05-3","t":"수사기관이 압수·수색영장 집행과정에서 영장발부의 사유인 범죄혐의사실과 무관한 별개의 증거를 압수하였다가 피압수자에게 환부하고 후에 이를 다시 임의제출받아 압수한 경우, 검사가 위 압수물 제출의 임의성을 합리적인 의심을 배제할 수 있을 정도로 증명하여 임의성이 인정된다면 이를 유죄 인정의 증거로 사용할 수 있다.","ox":"O","m":"③","c":"A","tp":"압수․수색"},{"y":2021,"e":"국가직 9급","qn":5,"i":"N92021-05-4","t":"압수·수색할 전자정보가 영장에 기재된 수색장소에 있는 정보처리장치에 있지 않고 그 정보처리장치와 정보통신망으로 연결되어 제3자가 관리하고 있는 원격지의 저장매체에 저장 되어 있는 경우, 수사기관이 압수·수색영장에 기재되어 있는 압수할 물건을 적법한 절차와 집행방법에 따라 수색장소의 정보처리장치를 이용하여 원격지의 저장매체에 접속하였다 하더라도 이와 같은 압수·수색은 형사소송법에 위반된다.","ox":"X","m":"④","c":"A","tp":"압수․수색"},{"y":2021,"e":"국가직 9급","qn":11,"i":"N92021-11-1","t":"불구속으로 기소된 피고인이 도망하거나 증거인멸의 염려가 있는 경우 검사는 지방법원판사에게 구속영장을 청구하여 발부받아 피고인을 구속할 수 있다.","ox":"X","m":"①","c":"A","tp":"공소가 제기된 이후 당해 피고인"},{"y":2021,"e":"국가직 9급","qn":11,"i":"N92021-11-2","t":"검사 작성의 피고인에 대한 진술조서가 공소제기 후에 작성된 것이라는 이유만으로 곧 그 증거능력이 없다고 할 수는 없다.","ox":"O","m":"②","c":"A","tp":"공소가 제기된 이후 당해 피고인"},{"y":2021,"e":"국가직 9급","qn":11,"i":"N92021-11-3","t":"수사기관은 수소법원 이외의 지방법원판사로부터 압수·수색 영장을 청구하여 발부받아 피고사건에 관하여 압수·수색을 할 수 있다.","ox":"X","m":"③","c":"A","tp":"공소가 제기된 이후 당해 피고인"},{"y":2021,"e":"국가직 9급","qn":11,"i":"N92021-11-4","t":"피고인에 대한 수소법원의 구속영장을 집행하는 경우 필요한 때에도 수사기관은 그 집행현장에서 영장 없이는 압수·수색·검증을 할 수 없다.","ox":"X","m":"④","c":"A","tp":"공소가 제기된 이후 당해 피고인"},{"y":2021,"e":"국가직 9급","qn":13,"i":"N92021-13-1","t":"‘범죄의 중대성, 재범의 위험성, 피해자 및 중요 참고인 등에 대한 위해우려 등’은 독립된 구속사유가 아니라 구속사유를 심사함에 있어서 필요적 고려사항이다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"국가직 9급","qn":13,"i":"N92021-13-2","t":"지방법원판사가 구속영장청구를 기각한 경우에 검사는 지방 법원판사의 기각결정에 대하여 항고 또는 준항고의 방법으로 불복할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"국가직 9급","qn":13,"i":"N92021-13-3","t":"긴급체포된 피의자를 구속전 피의자심문을 하는 경우 구속기간은 구속영장 발부시가 아닌 피의자를 체포한 날부터 기산하며, 법원이 구속영장청구서·수사 관계 서류 및 증거물을 접수한 날부터 구속영장을 발부하여 검찰청에 반환한 날까지의 기간은 구속기간에 산입하지 않는다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"국가직 9급","qn":13,"i":"N92021-13-4","t":"구속영장 발부에 의하여 적법하게 구금된 피의자가 피의자신문을 위한 출석요구에 응하지 아니하면서 수사기관 조사실에 출석을 거부하는 경우에도 수사기관은 구속영장의 효력에 의하여 피의자를 조사실로 구인할 수 없다.","ox":"X","m":"④","c":"A"},{"y":2021,"e":"국가직 9급","qn":17,"i":"N92021-17","t":"형사절차에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"형사절차에 대한 설명으로 옳지 않은 것은?","d":"","o":["체포․구속적부심사에 대한 법원의 기각결정에 대하여는 항고하지 못하지만, 보증금납입조건부 석방결정에 대하여는 항고할 수 있다.","법원은 피고인이 도망하거나 죄증을 인멸할 염려가 있다고 믿을 만한 충분한 이유가 있는 때에는 직권으로 보석을 취소할 수 있으며, 이러한 보석취소결정에 대하여는 항고할 수 있다.","수사기관이 법원으로부터 영장 또는 감정처분허가장을 발부받지 아니한 채 피의자의 동의 없이 피의자의 신체로부터 혈액을 채취하고 사후에도 지체 없이 영장을 발부받지 아니한 채 혈액 중 알코올농도에 관한 감정을 의뢰하였더라도, 이러한 과정을 거쳐 얻은 감정의뢰회보 등은 피고인이나 변호인의 동의가 있다면 유죄의 증거로 사용할 수 있다.","압수․수색의 방법으로 소변을 채취하는 경우 압수대상물인 피의자의 소변을 확보하기 위한 수사기관의 노력에도 불구하고, 피의자가 소변 채취에 적합한 인근 병원 등으로 이동하는 것에 저항하는 등 임의동행을 기대할 수 없는 사정이 있는 때에는, 수사기관으로서는 소변 채취에 적합한 장소로 피의자를 데려가기 위해서 필요 최소한의 유형력을 행사하는 것이 허용된다. 2021년도 국가공무원 9급 공채 필기시험 형사"],"a":3}},{"y":2023,"e":"국가직 9급","qn":8,"i":"N92023-08","t":"형사소송법 이 명시적으로 규정하고 있는 검사의 권한에 속하지 않는 것은?","c":"A","mc":{"s":"형사소송법 이 명시적으로 규정하고 있는 검사의 권한에 속하지 않는 것은?","d":"","o":["피고인의 구속취소 청구","피고인의 구속집행정지 신청","피의자의 감정유치 청구","재심의 청구"],"a":2}},{"y":2023,"e":"국가직 9급","qn":12,"i":"N92023-12","t":"강제수사에 대한 설명으로 옳은 것만을 모두 고르면?","c":"A","mc":{"s":"강제수사에 대한 설명으로 옳은 것만을 모두 고르면?","d":"ㄱ. 현행범인 체포의 요건을 갖추었는지 여부는 체포 당시의 상황을 기초로 판단하여야 하고, 체포 당시의 상황으로 볼 때 그 요건의 충족 여부에 관한 검사나 사법경찰관 등의 판단이 경험칙에 비추어 현저히 합리성을 잃은 경우에는 그 체포는 위법하다.\nㄴ. 구속기간연장허가결정이 있은 경우에 그 연장기간은 구속기간이 만료된 날로부터 기산한다.\nㄷ. 피의자, 피의자의 변호인ㆍ법정대리인ㆍ배우자ㆍ직계친족ㆍ 형제자매ㆍ가족ㆍ동거인 또는 고용주는 구속된 피의자의 보석을 법원에 청구할 수 있다.\nㄹ. 수사기관이 압수ㆍ수색영장에 적힌 ‘수색할 장소’에 있는 컴퓨터 등 정보처리장치에 저장된 전자정보 외에 원격지 서버에 저장된 전자정보를 압수ㆍ수색하기 위해서는 압수ㆍ 수색영장에 적힌 ‘압수할 물건’에 별도로 원격지 서버 저장 전자정보가 특정되어 있어야 한다.","o":["ㄱ, ㄴ","ㄱ, ㄹ","ㄴ, ㄷ","ㄷ, ㄹ"],"a":2}},{"y":2023,"e":"국가직 9급","qn":16,"i":"N92023-16-1","t":"보증금 납입을 조건으로 석방된 피의자가 주거의 제한이나 그 밖에 법원이 정한 조건을 위반한 때에는 동일한 범죄사실로 재차 체포하거나 구속할 수 있다.","ox":"O","m":"①","c":"A","tp":"재체포ㆍ재구속"},{"y":2023,"e":"국가직 9급","qn":16,"i":"N92023-16-2","t":"체포 또는 구속 적부심사결정에 의하여 석방된 피의자가 도망하거나 범죄의 증거를 인멸할 염려가 있다고 믿을 만한 충분한 이유가 있는 때에는 동일한 범죄사실로 재차 체포하거나 구속할 수 있다.","ox":"X","m":"②","c":"A","tp":"재체포ㆍ재구속"},{"y":2023,"e":"국가직 9급","qn":16,"i":"N92023-16-3","t":"보증금 납입을 조건으로 석방된 피의자가 피해자, 당해 사건의 재판에 필요한 사실을 알고 있다고 인정되는 자 또는 그 친족의 생명ㆍ신체ㆍ재산에 해를 가하거나 가할 염려가 있다고 믿을 만한 충분한 이유가 있는 때에는 동일한 범죄사실로 재차 체포하거나 구속할 수 있다.","ox":"X","m":"③","c":"A","tp":"재체포ㆍ재구속"},{"y":2023,"e":"국가직 9급","qn":16,"i":"N92023-16-4","t":"검사 또는 사법경찰관에 의하여 영장에 의해 체포되었다가 석방된 자는 다른 중요한 증거를 발견한 경우를 제외하고는 동일한 범죄사실로 재차 체포하지 못한다.","ox":"X","m":"④","c":"A","tp":"재체포ㆍ재구속"},{"y":2024,"e":"국가직 9급","qn":3,"i":"N92024-03-1","t":"구속기간의 만료로 피고인에 대한 구속의 효력이 상실된 후 항소법원이 피고인에 대한 판결을 선고하면서 피고인을 구속 하였다면 이는 형사소송법 제208조의 규정에 위배되는 재구속 또는 이중구속에 해당한다.","ox":"X","m":"①","c":"A","tp":"구속제도"},{"y":2024,"e":"국가직 9급","qn":3,"i":"N92024-03-2","t":"구속기간이 만료될 무렵에 종전 구속영장에 기재된 범죄사실과는 다른 범죄사실로 피고인을 구속하였다는 사정만으로도 이는 위법한 구속이다.","ox":"X","m":"②","c":"A","tp":"구속제도"},{"y":2024,"e":"국가직 9급","qn":3,"i":"N92024-03-3","t":"구속전피의자심문에서 피의자에게 변호인이 없는 때에는 지방법원 판사는 직권으로 변호인을 선정하여야 하고, 이 경우 변호인의 선정은 피의자에 대한 구속영장 청구가 기각되어 효력이 소멸한 경우를 제외하고는 제1심까지 효력이 있다.","ox":"O","m":"③","c":"A","tp":"구속제도"},{"y":2024,"e":"국가직 9급","qn":3,"i":"N92024-03-4","t":"형사소송법 제70조제2항이 정한 범죄의 중대성, 재범의 위험성, 피해자 및 중요 참고인 등에 대한 위해우려는 동법 제70조제1항에서 정한 주거부정, 증거인멸의 염려, 도망 또는 도망할 염려 등의 구속사유에 새로운 구속사유를 추가한 것이다.","ox":"X","m":"④","c":"A","tp":"구속제도"},{"y":2024,"e":"국가직 9급","qn":16,"i":"N92024-16-1","t":"통신비밀보호법에 따라 검사 또는 사법경찰관은 수사를 위해 필요한 경우 법원의 허가를 받아 정보통신망에 접속된 정보통신 기기의 위치를 확인할 수 있는 발신기지국의 위치추적자료의 제공을 요청할 수 있다.","ox":"O","m":"①","c":"A","tp":"대물적 강제처분"},{"y":2024,"e":"국가직 9급","qn":16,"i":"N92024-16-2","t":"전자정보가 담긴 저장매체 또는 하드카피ㆍ이미징 등 형태를 수사기관 사무실 등으로 옮겨 복제ㆍ탐색ㆍ출력을 통하여 압수 ㆍ수색영장을 집행하는 경우에도 그 과정에서 피압수자 또는 변호인에게 참여의 기회를 보장하여야 한다.","ox":"O","m":"②","c":"A","tp":"대물적 강제처분"},{"y":2024,"e":"국가직 9급","qn":16,"i":"N92024-16-3","t":"압수ㆍ수색영장에 기재된 ‘압수할 물건’에 별도로 원격지 서버 저장 전자정보가 특정되어 있지 않은 채 컴퓨터 등 정보처리장치 저장 전자정보만 기재되어 있더라도 컴퓨터 등 정보처리장치를 이용하여 원격지 서버 저장 전자정보를 압수할 수 있다.","ox":"X","m":"③","c":"A","tp":"대물적 강제처분"},{"y":2024,"e":"국가직 9급","qn":16,"i":"N92024-16-4","t":"피해자 등 제3자가 피의자의 소유ㆍ관리에 속하는 정보저장매체를 영장에 의하지 않고 피의자의 동의없이 임의제출한 경우에는 실질적 피압수자인 피의자가 수사기관으로 하여금 그 전자정보 전부를 무제한 탐색하는 데 동의한 것으로 보기 어렵다.","ox":"O","m":"④","c":"A","tp":"대물적 강제처분"},{"y":2025,"e":"국가직 9급","qn":2,"i":"N92025-02-1","t":"유류물 압수ㆍ수색에 대해서는 원칙적으로 영장에 의한 압수ㆍ 수색ㆍ검증에 관하여 적용되는 형사소송법상 관련성의 제한이 적용되며, 참여권자의 참여가 필수적으로 요구된다.","ox":"X","m":"①","c":"A","tp":"압수ㆍ수색과 참여권"},{"y":2025,"e":"국가직 9급","qn":2,"i":"N92025-02-2","t":"임의제출에 따른 압수의 경우에도 압수물에 대한 수사기관의 점유 취득이 제출자의 의사에 따라 이루어진다는 점에서만 차이가 있을 뿐 범죄혐의를 전제로 한 수사 목적이나 압수의 효력은 영장에 의한 압수와 동일하므로 수사기관은 영장에 의한 압수와 마찬가지로 압수목록을 신속하게 작성ㆍ교부할 의무를 부담한다.","ox":"O","m":"②","c":"A","tp":"압수ㆍ수색과 참여권"},{"y":2025,"e":"국가직 9급","qn":2,"i":"N92025-02-3","t":"형사소송법 제219조, 제123조제2항, 제3항에 따라 압수ㆍ 수색절차에 주거주 등 또는 이웃 등이 참여하였다고 하더라도 그 참여자에게 최소한 압수ㆍ수색절차의 의미를 이해할 수 있는 정도의 능력이 없거나 부족한 경우에는 압수ㆍ수색절차의 적법 요건이 갖추어졌다고 볼 수 없으므로 그러한 압수ㆍ수색영장의 집행은 위법한 것이 된다.","ox":"O","m":"③","c":"A","tp":"압수ㆍ수색과 참여권"},{"y":2025,"e":"국가직 9급","qn":2,"i":"N92025-02-4","t":"영장에 의한 압수 및 그 대상물에 대한 확인조치가 끝나면 그것으로 압수절차는 종료되고, 압수물과 혐의사실과의 관련성 여부에 관한 평가 및 그에 필요한 추가 수사는 압수절차 종료 이후의 사정에 불과하므로 이를 이유로 압수 직후 이루어져야 하는 압수목록 작성ㆍ교부의무를 해태ㆍ거부할 수 없다.","ox":"O","m":"④","c":"A","tp":"압수ㆍ수색과 참여권"},{"y":2025,"e":"국가직 9급","qn":20,"i":"N92025-20-1","t":"압수ㆍ수색의 방법으로 소변을 채취하는 경우 압수대상물인 피의자의 소변을 확보하기 위한 수사기관의 노력에도 불구하고, 피의자가 인근 병원 응급실 등 소변 채취에 적합한 장소로 이동 하는 것에 동의하지 않거나 저항하는 등 임의동행을 기대할 수 없는 사정이 있는 때에는 수사기관으로서는 소변 채취에 적합한 장소로 피의자를 데려가기 위해서 필요 최소한의 유형력을 행사 하는 것이 허용된다.","ox":"O","m":"①","c":"A","tp":"수사기관의 압수ㆍ수색"},{"y":2025,"e":"국가직 9급","qn":20,"i":"N92025-20-2","t":"소유자, 소지자 또는 보관자가 아닌 자로부터 제출받은 물건을 영장없이 압수한 경우 그 ‘압수물’ 및 ‘압수물을 찍은 사진’은 피고인이나 변호인이 이를 증거로 함에 동의하였다고 하더라도 유죄 인정의 증거로 사용할 수 없다.","ox":"O","m":"②","c":"A","tp":"수사기관의 압수ㆍ수색"},{"y":2025,"e":"국가직 9급","qn":20,"i":"N92025-20-3","t":"검사는 증거에 사용할 압수물에 대하여 가환부의 청구가 있는 경우 가환부를 거부할 수 있는 특별한 사정이 없는 한 가환부에 응하여야 한다.","ox":"O","m":"③","c":"A","tp":"수사기관의 압수ㆍ수색"},{"y":2025,"e":"국가직 9급","qn":20,"i":"N92025-20-4","t":"수사기관이 압수ㆍ수색에 착수하면서 그 장소의 관리책임자에게 영장을 제시하였다면, 그 장소에서 물건을 소지하고 있는 다른 사람으로부터 이를 압수하고자 하는 경우라도 그 사람에게 따로 영장을 제시할 필요는 없다.","ox":"X","m":"④","c":"A","tp":"수사기관의 압수ㆍ수색"}],"8":[{"y":2015,"e":"국가직 9급","qn":10,"i":"N92015-10-1","t":"항소심이 항소이유에 포함되지 아니한 사유를 직권으로 심리 하여 제1심 판결을 파기하고 자판할 경우 항소이유의 당부에 대한 판단도 명시하여야 한다.","ox":"X","m":"①","c":"A"},{"y":2015,"e":"국가직 9급","qn":10,"i":"N92015-10-2","t":"피고인이 항소심 공판기일에 출정하지 않아서 다시 정해진 기일에도 정당한 사유 없이 출정하지 않은 경우 피고인의 진술 없이 판결할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2015,"e":"국가직 9급","qn":10,"i":"N92015-10-3","t":"항소심이 피고인의 항소에 대하여 양형부당을 이유로 제1심 판결을 파기·자판하면서 피고인에 대한 범죄사실을 모두 유죄로 인정한 경우 사실오인의 항소이유에 대해서는 배척한 것으로 볼 수 있다.","ox":"O","m":"③","c":"A"},{"y":2015,"e":"국가직 9급","qn":10,"i":"N92015-10-4","t":"항소법원은 제1심의 공소기각 판결이 위법한 경우 제1심 판결을 파기하고 사건을 제1심 법원에 환송하여야 한다.","ox":"O","m":"④","c":"A","tp":"항소심"},{"y":2015,"e":"국가직 9급","qn":20,"i":"N92015-20-1","t":"파기판결의 기속력은 파기판결을 행한 상고법원에 대하여서는 미치지 아니한다.","ox":"X","m":"①","c":"A","tp":"상고심의 파기판결의 기속력(구속력)"},{"y":2015,"e":"국가직 9급","qn":20,"i":"N92015-20-2","t":"환송받은 법원은 환송 후의 심리과정에서 새로운 증거가 제시되어 기속적 판단의 기초가 된 증거관계에 변동이 생긴 때에는 상고법원이 파기이유로 한 사실상 및 법률상의 판단에 기속되지 않는다.","ox":"O","m":"②","c":"A","tp":"상고심의 파기판결의 기속력(구속력)"},{"y":2015,"e":"국가직 9급","qn":20,"i":"N92015-20-3","t":"몰수형 부분의 위법을 이유로 원심판결 전부가 파기환송된 경우 환송받은 법원은 환송 전 원심이 피고인의 항소를 기각한 것과 달리 피고인의 양형부당의 항소이유를 받아들여 주형을 변경하여 선고할 수 있다.","ox":"O","m":"③","c":"A","tp":"상고심의 파기판결의 기속력(구속력)"},{"y":2015,"e":"국가직 9급","qn":20,"i":"N92015-20-4","t":"환송받은 법원에서 공소사실이 변경된 경우 환송받은 법원은 파기판결이 한 사실판단에 기속될 필요가 없다.","ox":"O","m":"④","c":"A","tp":"상고심의 파기판결의 기속력(구속력)"},{"y":2016,"e":"국가직 9급","qn":7,"i":"N92016-07-1","t":"제1심판결에 대하여 피고인만이 항소한 사건에서 항소심이 검사의 공소장변경신청을 받아들여 그 변경된 적용법률에 따라 판결을 선고한 경우에는 그 선고된 항소심의 형이 제1심의 그것보다 무겁다고 하더라도 불이익변경금지의 원칙에 위배 되지 아니한다.","ox":"X","m":"①","c":"A"},{"y":2016,"e":"국가직 9급","qn":7,"i":"N92016-07-2","t":"피고인만이 항소한 사건에서 항소심법원이 제1심판결을 파기하고 새로운 형을 선고함에 있어 피고인에 대한 주형에서 그 형기를 감축하고 제1심판결이 선고하지 아니한 압수장물을 피해자에게 환부하는 선고를 추가하였더라도 그것만으로는 피고인에 대한 형이 제1심판결보다 불이익하게 변경되었다고 할 수 없다.","ox":"O","m":"②","c":"A","tp":"불이익변경금지의 원칙"},{"y":2016,"e":"국가직 9급","qn":7,"i":"N92016-07-3","t":"제1심의 징역형의 선고유예의 판결에 대하여 피고인만이 항소한 경우에 제2심이 벌금형을 선고한 것은 불이익변경 금지의 원칙에 위배되지 아니한다.","ox":"X","m":"③","c":"A"},{"y":2016,"e":"국가직 9급","qn":7,"i":"N92016-07-4","t":"형벌인 몰수에는 불이익변경금지의 원칙이 적용되지만 몰수에 대신하는 처분인 추징에 대해서는 불이익변경금지의 원칙이 적용되지 아니한다.","ox":"X","m":"④","c":"A"},{"y":2016,"e":"국가직 9급","qn":12,"i":"N92016-12","t":"즉결심판절차에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"즉결심판절차에 대한 설명으로 옳지 않은 것은?","d":"","o":["즉결심판절차에서는 형사소송법 제310조의 자백의 보강 법칙이 적용되지 않는다.","판사는 피고인에게 피고사건의 내용과 형사소송법 제283조의2에 규정된 진술거부권이 있음을 알리고 변명할 기회를 주어야 한다.","정식재판을 청구하고자 하는 피고인은 즉결심판의 선고․ 고지를 받은 날부터 7일 이내에 정식재판청구서를 경찰서장 에게 제출하여야 한다.","즉결심판을 받은 피고인이 정식재판청구를 함으로써 공판 절차가 개시된 경우에는 통상의 공판절차와 달리 국선변호인의 선정에 관한 형사소송법 제283조의 규정이 적용되지 않는다. 형사소송법개론 2 책형 3 쪽"],"a":4}},{"y":2016,"e":"국가직 9급","qn":15,"i":"N92016-15-1","t":"공소장부본을 송달받은 날부터 7일 이내에 의사확인서를 제출하지 아니한 피고인도 제1회 공판기일이 열리기 전까지는 국민참여재판 신청을 할 수 있고, 법원은 그 의사를 확인하여 국민참여재판으로 진행할 수 있다.","ox":"O","m":"①","c":"A","tp":"국민의 형사재판 참여"},{"y":2016,"e":"국가직 9급","qn":15,"i":"N92016-15-2","t":"국민의 형사재판 참여에 관한 법률 제42조 제2항은 재판장의 공판기일에서의 최초 설명의무를 규정하고 있는데, 원칙적으로 설명의 대상에 검사가 아직 공소장에 의하여 낭독하지 아니한 공소사실 등은 포함된다고 볼 수 없다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"국가직 9급","qn":15,"i":"N92016-15-3","t":"공판절차가 개시된 후 새로 재판에 참여하는 배심원 또는 예비배심원이 있는 때에는 공판절차를 갱신하여야 한다.","ox":"O","m":"③","c":"A","tp":"국민의 형사재판 참여"},{"y":2016,"e":"국가직 9급","qn":15,"i":"N92016-15-4","t":"국민참여재판을 받을 권리는 헌법 제27조 제1항에서 규정한 재판을 받을 권리의 보호범위에 속한다.","ox":"X","m":"④","c":"A","tp":"국민의 형사재판 참여"},{"y":2016,"e":"국가직 9급","qn":16,"i":"N92016-16-1","t":"경합범 중 일부에 대하여 무죄, 일부에 대하여 유죄를 선고한 제1심판결에 대하여 검사만이 무죄 부분에 대하여 항소를 한 경우, 피고인과 검사가 항소하지 아니한 유죄판결 부분은 항소기간이 지남으로써 확정되므로, 항소심에서 이를 파기할 때에는 유죄부분만을 파기하여야 한다.","ox":"X","m":"①","c":"A","tp":"일부상소"},{"y":2016,"e":"국가직 9급","qn":16,"i":"N92016-16-2","t":"수개의 범죄사실에 대하여 항소심이 일부는 유죄, 일부는 무죄의 판결을 하고, 그 판결에 대하여 피고인 및 검사 쌍방이 상고를 제기하였으나, 유죄 부분에 대한 피고인의 상고는 이유 없고 무죄 부분에 대한 검사의 상고만 이유 있는 경우, 항소심이 유죄로 인정한 죄와 무죄로 인정한 죄가 형법 제37조 전단의 경합범 관계에 있다면 항소심판결의 유죄 부분도 무죄 부분과 함께 파기되어야 한다.","ox":"O","m":"②","c":"A","tp":"일부상소"},{"y":2016,"e":"국가직 9급","qn":16,"i":"N92016-16-3","t":"제1심이 단순일죄의 관계에 있는 공소사실의 일부에 대하여만 유죄로 인정한 경우에 피고인만이 항소하여도 그 항소는 그 일죄의 전부에 미쳐서 항소심은 무죄부분에 대하여도 심판할 수 있다.","ox":"O","m":"③","c":"A","tp":"일부상소"},{"y":2016,"e":"국가직 9급","qn":16,"i":"N92016-16-4","t":"형법 제37조 전단의 경합범 관계에 있는 죄에 대하여 일부는 유죄, 일부는 무죄를 선고한 원심판결에 대하여 피고인은 상소하지 아니하고, 검사만이 무죄부분에 한정하지 아니하고 전체에 대하여 상소한 경우에 무죄부분에 대한 검사의 상소만 이유 있는 때에도 원심판결의 유죄부분은 무죄부분과 함께 파기되어야 하므로 상소심으로서는 원심판결 전부를 파기 하여야 한다.","ox":"O","m":"④","c":"A","tp":"일부상소"},{"y":2016,"e":"국가직 9급","qn":20,"i":"N92016-20-1","t":"‘무죄 등을 인정할 명백한 증거’에 해당하는지 여부는 새로 발견된 증거만을 독자적·고립적으로 고찰하여 그 증거가치만으로 판단하여야 한다.","ox":"X","m":"①","c":"A","tp":"재심"},{"y":2016,"e":"국가직 9급","qn":20,"i":"N92016-20-2","t":"약식명령에 대하여 정식재판 청구가 이루어지고 그 후 진행된 정식재판 절차에서 유죄판결이 선고되어 확정된 경우, 재심 사유가 존재한다고 주장하는 피고인은 약식명령을 대상으로 재심을 청구하여야 한다.","ox":"X","m":"②","c":"A"},{"y":2016,"e":"국가직 9급","qn":20,"i":"N92016-20-3","t":"자신에 대한 유죄판결이 확정된 증인이 공범에 대한 피고사건에서 증언할 당시 앞으로 재심을 청구할 예정이라면, 이를 이유로 증인에게 형사소송법 제148조에 의한 증언거부권이 인정된다.","ox":"X","m":"③","c":"A"},{"y":2016,"e":"국가직 9급","qn":20,"i":"N92016-20-4","t":"재심이 개시된 사건에서 형벌에 관한 법령이 재심판결 당시 폐지되었다 하더라도 그 폐지가 당초부터 헌법에 위배되어 효력이 없는 법령에 대한 것이었다면 형사소송법 제325조 전단이 규정하는 ‘범죄로 되지 아니한 때’의 무죄사유에 해당한다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"국가직 9급","qn":9,"i":"N92017-09-1","t":"수사기관의 압수물환부에 관한 처분의 취소를 구하는 준항고에서는 통상의 항고소송과 마찬가지로 그 이익이 있을 것을 요한다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"국가직 9급","qn":9,"i":"N92017-09-2","t":"법원이 사건을 국민참여재판으로 진행하기로 하는 결정 또는 배제하기로 하는 결정에 대해서는 즉시항고를 할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2017,"e":"국가직 9급","qn":9,"i":"N92017-09-3","t":"검사의 체포영장 또는 구속영장 청구에 대한 지방법원판사의 재판은 항고나 준항고의 대상이 되지 않는다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"국가직 9급","qn":9,"i":"N92017-09-4","t":"재정신청사건에서 고등법원의 공소제기결정에 대하여는 재항고가 허용되지 아니하므로, 공소제기결정에 대하여 재항고가 제기된 경우에는 고등법원이 결정으로 이를 기각하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"국가직 9급","qn":11,"i":"N92017-11-1","t":"검사의 항소이유가 실질적으로 구두변론을 거쳐 심리되지 않았다고 평가될 경우 항소심법원이 검사의 항소이유 주장을 받아들여 피고인에게 불리하게 제1심 판결을 변경하는 것은 허용되지 않는다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"국가직 9급","qn":11,"i":"N92017-11-2","t":"검사가 공소제기 후 수소법원 이외의 지방법원판사에게 청구 하여 발부받은 영장에 의하여 압수·수색을 하였다면, 그와 같이 수집된 증거는 적법한 절차에 따르지 않은 것으로서 원칙적으로 유죄의 증거로 삼을 수 없다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"국가직 9급","qn":11,"i":"N92017-11-3","t":"헌법은 “누구든지 체포 또는 구속을 당한 때에는 즉시 변호인의 조력을 받을 권리를 가진다”라고 규정하고 있으므로 집행 유예가 선고된 제1심 판결에 대해 검사만이 양형부당을 이유로 항소하고 항소심에서 형을 선고하는 경우에는 공판심리 단계에서 국선변호인을 선정하는 것보다 판결 선고 후 피고인을 법정구속한 뒤에 국선변호인을 선정하는 것이 바람직하다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"국가직 9급","qn":11,"i":"N92017-11-4","t":"검사는 성폭력범죄의 처벌 등에 관한 특례법상 성폭력범죄의 피해자에게 변호사가 없는 경우 국선변호사를 선정하여 형사 절차에서 피해자의 권익을 보호할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"국가직 9급","qn":15,"i":"N92017-15","t":"국민참여재판에서 공소사실의 일부 철회 또는 변경으로 인하여 대상사건에 해당하지 아니하게 된 경우, 법원은 절차를 정지하고 결정으로 당해 사건을 지방법원 본원 합의부로 하여금 국민참여재판에 의하지 아니하고 심판 하게 하여야 한다.","c":"A","mc":{"s":"국민참여재판에서 공소사실의 일부 철회 또는 변경으로 인하여 대상사건에 해당하지 아니하게 된 경우, 법원은 절차를 정지하고 결정으로 당해 사건을 지방법원 본원 합의부로 하여금 국민참여재판에 의하지 아니하고 심판 하게 하여야 한다.","d":"국민참여재판에 대한 설명으로 옳은 것만을 모두 고른 것은?\nㄱ.\nㄴ. 국민참여재판에서는 피고인이 법정에서 자백하는 경우 에도 간이공판절차 규정을 적용하지 아니한다.\nㄷ. 심리에 관여한 배심원은 유․무죄에 관하여 평의하고 평결이 유죄인 경우 양형에 관하여 토의하고 그에 관한 의견을 개진하며, 평의 및 양형에 관한 토의에는 심리에 관여한 판사가 참여할 수 없다.\nㄹ. 배심원이 9인인 경우 검사와 변호인은 각자 5인의 범위 내에서 배심원후보자에 대하여 이유를 제시하지 아니하는 기피신청을 할 수 있다.","o":["ㄱ, ㄹ","ㄴ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"a":3}},{"y":2017,"e":"국가직 9급","qn":18,"i":"N92017-18","t":"재심에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"재심에 대한 설명으로 옳지 않은 것은?","d":"","o":["경합범 관계에 있는 수개의 범죄사실을 유죄로 인정하여 한 개의 형을 선고한 불가분의 확정판결에서 그 중 일부의 범죄사실에 대해서만 재심청구의 이유가 있는 것으로 인정된 경우에는 그 일부에 대해서만 재심개시의 결정을 하여야 하고 양형을 위해 필요한 범위에 한하여 나머지 범죄사실을 심리할 수 있다.","항소심의 유죄판결에 대하여 상고가 제기되어 상고심 재판이 계속되던 중 피고인이 사망하여 공소기각결정이 확정된 경우는 재심절차의 전제가 되는 유죄의 확정판결이 존재하는 경우에 해당하지 않는다.","재심청구의 대상이 된 원판결의 심리에 관여한 법관이 재심 청구사건을 심판하더라도 제척 또는 기피사유에 해당하지 않는다.","특별사면으로 형선고의 효력이 상실된 유죄의 확정판결에 대하여 재심개시결정이 이루어져 재심심판법원이 심급에 따라 다시 심판한 결과 무죄로 인정되는 경우에는 무죄판결을 선고하여야 한다. 형사"],"a":1}},{"y":2017,"e":"국가직 9급","qn":19,"i":"N92017-19-1","t":"두 개의 벌금형을 선고한 환송 전 원심판결에 대하여 피고인만이 상고하여 파기 환송되었는데, 환송 후 원심이 징역형의 집행유예와 사회봉사명령을 선고한 것은 불이익변경금지의 원칙에 위배된다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"국가직 9급","qn":19,"i":"N92017-19-2","t":"피고인이 약식명령에 대하여 정식재판을 청구한 사건과 다른 사건이 병합된 경우, 심리 결과 하나의 벌금형으로 처단하면서 약식명령의 형보다 중한 벌금형을 선고한 것은 불이익변경금지의 원칙에 위배된다.","ox":"X","m":"②","c":"A"},{"y":2017,"e":"국가직 9급","qn":19,"i":"N92017-19-3","t":"제1심에서 징역형의 집행유예를 선고한 데 대하여 피고인만이 항소한 경우 제2심이 징역형의 형기를 단축하여 실형을 선고 하는 것은 불이익변경금지의 원칙에 위배된다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"국가직 9급","qn":19,"i":"N92017-19-4","t":"피고인만이 항소한 사건에서 항소심이 제1심 판결을 직권으로 파기하고 다른 형은 동일하게 선고하면서 위치추적전자장치 부착명령의 기간만을 제1심 판결보다 장기의 기간으로 부과한 것은 불이익변경금지의 원칙에 위배된다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"국가직 9급","qn":2,"i":"N92018-02-1","t":"법원은 검사의 청구가 있는 때에는 공판절차 없이 약식명령으로 피고인을 벌금, 구류 또는 과료에 처할 수 있다.","ox":"X","m":"①","c":"A","tp":"약식절차"},{"y":2018,"e":"국가직 9급","qn":2,"i":"N92018-02-2","t":"약식절차에서 자백배제법칙은 적용되지만 자백보강법칙과 전문법칙은 적용되지 않는다.","ox":"X","m":"②","c":"A"},{"y":2018,"e":"국가직 9급","qn":2,"i":"N92018-02-3","t":"벌금형이 고지된 약식명령에 대해 피고인만이 정식재판을 청구한 경우 법원은 벌금액을 상향하여 선고할 수 있다.","ox":"O","m":"③","c":"A","tp":"약식절차"},{"y":2018,"e":"국가직 9급","qn":2,"i":"N92018-02-4","t":"약식명령에 대한 정식재판청구가 있으면 약식명령은 효력을 상실한다.","ox":"X","m":"④","c":"A","tp":"약식절차"},{"y":2018,"e":"국가직 9급","qn":7,"i":"N92018-07-1","t":"피고인만 상고한 상고심에서 항소심판결을 파기하고 사건을 항소심에 환송한 경우에 그 항소심에서는 파기된 항소심판결보다 중한 형을 선고할 수 없다.","ox":"O","m":"①","c":"A","tp":"불이익변경금지의 원칙"},{"y":2018,"e":"국가직 9급","qn":7,"i":"N92018-07-2","t":"피고인만 항소한 항소심판결에 대해 검사만 상고한 경우 상고심에서도 불이익변경금지의 원칙이 적용된다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"국가직 9급","qn":7,"i":"N92018-07-3","t":"제1심에서 사문서위조죄로 벌금형의 선고를 받은 피고인만 항소한 항소심에서 동일한 공소사실에 대해 법정형에 벌금형이 없는 사서명위조죄가 인정되었다면 항소심법원은 불이익변경 금지의 원칙에도 불구하고 벌금형을 선고할 수는 없다.","ox":"X","m":"③","c":"A"},{"y":2018,"e":"국가직 9급","qn":7,"i":"N92018-07-4","t":"징역형의 집행유예가 확정된 사건에 대한 재심에서 원판결보다 주형을 경하게 하면서 집행유예를 없앤 경우에는 불이익변경 금지의 원칙에 위배된다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"국가직 9급","qn":10,"i":"N92019-10-1","t":"재판장은 여러 공판기일을 일괄하여 지정할 수 없다.","ox":"X","m":"①","c":"A","tp":"공판 및 상소절차"},{"y":2019,"e":"국가직 9급","qn":10,"i":"N92019-10-2","t":"간이공판절차로 진행된 제1심에서 형사소송법 제318조의3에 의하여 증거동의가 의제되어 증거능력이 인정된 증거라도 피고인이 항소심에서 진술을 번복하여 범행을 부인한다면 그 증거능력은 그대로 유지될 수 없다.","ox":"X","m":"②","c":"A","tp":"공판 및 상소절차"},{"y":2019,"e":"국가직 9급","qn":10,"i":"N92019-10-3","t":"제1심이 위법한 공시송달결정에 터 잡아 피고인의 진술 없이 심리·판단하였다면, 항소심은 검사만이 양형부당을 이유로 항소한 경우라도 직권으로 제1심의 위법을 시정하는 조치를 취하여야 한다.","ox":"O","m":"③","c":"A","tp":"공판 및 상소절차"},{"y":2019,"e":"국가직 9급","qn":10,"i":"N92019-10-4","t":"준항고의 청구는 재판의 고지 있는 날로부터 5일 이내에 하여야 한다.","ox":"X","m":"④","c":"A","tp":"공판 및 상소절차"},{"y":2019,"e":"국가직 9급","qn":13,"i":"N92019-13-1","t":"제1심 법원이 피고인의 의사에 따라 국민참여재판으로 진행 하기로 결정한 경우, 위 결정에 대해 검사는 항고할 수 있다.","ox":"X","m":"①","c":"A","tp":"국민의 형사재판 참여"},{"y":2019,"e":"국가직 9급","qn":13,"i":"N92019-13-2","t":"국민참여재판에서 배심원이 만장일치 의견으로 내린 무죄의 평결을 존중하여 제1심 법원이 무죄판결을 내린 경우, 검사는 항소를 제기할 수 없다.","ox":"X","m":"②","c":"A","tp":"국민의 형사재판 참여"},{"y":2019,"e":"국가직 9급","qn":13,"i":"N92019-13-3","t":"피고인은 공소장 부본을 송달받은 날부터 7일이 경과한 후에는 국민참여재판 신청을 할 수 없다.","ox":"X","m":"③","c":"A","tp":"국민의 형사재판 참여"},{"y":2019,"e":"국가직 9급","qn":13,"i":"N92019-13-4","t":"법원은 국민참여재판으로 진행하는 것이 적절하지 아니하다고 인정되는 경우, 공소제기 후부터 공판준비기일이 종결된 다음날까지 국민참여재판 배제결정을 할 수 있다.","ox":"O","m":"④","c":"A","tp":"국민의 형사재판 참여"},{"y":2019,"e":"국가직 9급","qn":19,"i":"N92019-19-1","t":"공소기각의 재판이 있으면 피고인은 유죄판결의 위험으로부터 벗어나는 것이므로 그 재판은 피고인에게 불이익한 재판이라고 할 수 없어서 이에 대하여 피고인은 상소권이 없다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"국가직 9급","qn":19,"i":"N92019-19-2","t":"공판기일에 출석한 피고인이 변호인의 상소취하에 대한 동의 여부를 묻는 재판장의 질문에 특별히 의사를 표시하지 않았다면 상소취하에 동의한 것으로 볼 수 있다.","ox":"X","m":"②","c":"A"},{"y":2019,"e":"국가직 9급","qn":19,"i":"N92019-19-3","t":"형법 제37조 전단의 경합범 관계에 있는 죄에 대하여 일부는 유죄, 일부는 무죄를 선고한 원심판결 전체에 대하여 검사만이 상소한 경우, 무죄 부분에만 상소이유가 있더라도 상소심은 원심판결 전부를 파기하여야 한다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"국가직 9급","qn":19,"i":"N92019-19-4","t":"검사와 피고인 쌍방이 항소하였으나 검사가 항소이유서를 제출하지 아니하여 검사의 항소를 기각하여야 하는 경우에는 불이익변경금지의 원칙이 적용된다.","ox":"O","m":"④","c":"A","tp":"상소"},{"y":2019,"e":"국가직 9급","qn":20,"i":"N92019-20-1","t":"법원이 판결의 선고 전에 피고인이 이미 사망한 사실을 알지 못하여 공소기각의 결정을 하지 않고 실체판결에 나아감으로써 법령위반의 결과를 초래한 경우, 이에 대한 검찰총장의 비상 상고는 적법하다.","ox":"X","m":"①","c":"A","tp":"형사절차"},{"y":2019,"e":"국가직 9급","qn":20,"i":"N92019-20-2","t":"피고인이 정식재판을 청구한 사건에 대하여는 약식명령의 형보다 중한 종류의 형을 선고하지 못하고, 약식명령의 형보다 중한 형을 선고하는 경우에는 판결서에 양형의 이유를 적어야 한다.","ox":"O","m":"②","c":"A","tp":"형사절차"},{"y":2019,"e":"국가직 9급","qn":20,"i":"N92019-20-3","t":"피의자는 미리 증거를 보전하지 아니하면 그 증거를 사용하기 곤란한 사정이 있는 때에는 제1회 공판기일 전이라도 판사에게 증인신문을 청구할 수 있는데, 판사가 이를 기각하는 결정에 대하여는 3일 이내에 항고할 수 있다.","ox":"O","m":"③","c":"A","tp":"형사절차"},{"y":2019,"e":"국가직 9급","qn":20,"i":"N92019-20-4","t":"甲이 수사기관에서 조사를 받을 때 乙의 성명, 주소, 본적 등 인적 사항을 모용하였기 때문에 검사가 이를 오인하여 乙의 표시로 공소를 제기한 경우, 검사가 공소제기 후 피고인표시 정정을 함으로써 그 모용관계가 바로 잡혔다고 볼만한 사정이 없는 이상이 공소는 형사소송법 제254조의 공소제기의 방식에 관한 규정에 위반하여 무효로 된다.","ox":"O","m":"④","c":"A","tp":"형사절차"},{"y":2020,"e":"국가직 9급","qn":6,"i":"N92020-06-1","t":"재심심판절차에서 재심의 판결을 선고하고 그 재심판결이 확정된 때에 종전의 유죄의 확정판결은 효력을 상실한다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"국가직 9급","qn":6,"i":"N92020-06-2","t":"재심심판절차에서는 특별한 사정이 없는 한 재심사건에 다른 사건의 공소사실을 추가하는 공소장변경을 하거나 다른 일반 사건을 병합하여 함께 심판하는 것이 허용되지 않는다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"국가직 9급","qn":6,"i":"N92020-06-3","t":"원판결의 증거가 된 증언이 나중에 확정판결에 의하여 허위임이 증명되더라도 허위증언 부분을 제외하고 다른 증거에 의하여 그 범죄사실이 유죄로 인정될 개연성이 있으면 재심사유는 인정되지 않는다.","ox":"X","m":"③","c":"A"},{"y":2020,"e":"국가직 9급","qn":6,"i":"N92020-06-4","t":"재심이 개시된 사건에 적용되어야 할 형벌에 관한 법령이 헌법재판소의 위헌결정으로 소급하여 그 효력을 상실하였다면 재심사건에 대하여 무죄를 선고하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"국가직 9급","qn":7,"i":"N92020-07-1","t":"피고인이 상소를 포기한 후 그 포기의 무효를 주장하기 위해서는 상소제기 기간이 경과하기 전이라도 상소권회복청구를 하여야 한다.","ox":"X","m":"①","c":"A","tp":"상소의 포기 또는 취하"},{"y":2020,"e":"국가직 9급","qn":7,"i":"N92020-07-2","t":"피고인은 사형 또는 무기징역이나 무기금고가 선고된 판결에 대하여는 상소의 포기를 할 수 없다.","ox":"O","m":"②","c":"A","tp":"상소의 포기 또는 취하"},{"y":2020,"e":"국가직 9급","qn":7,"i":"N92020-07-3","t":"변호인의 상소취하에 피고인의 동의가 없다면 상소취하의 효력은 발생하지 아니한다.","ox":"O","m":"③","c":"A","tp":"상소의 포기 또는 취하"},{"y":2020,"e":"국가직 9급","qn":7,"i":"N92020-07-4","t":"피고인의 상소취하가 착오에 기인한 경우, 그 착오에 관하여 피고인에게 과실이 있으면 피고인이 착오를 일으키게 된 과정에 교도관의 과실이 개입되었더라도 상소취하는 무효로 되지 않는다.","ox":"O","m":"④","c":"A","tp":"상소의 포기 또는 취하"},{"y":2020,"e":"국가직 9급","qn":10,"i":"N92020-10","t":"항고에 대한 설명으로 옳은 것만을 모두 고르면?","c":"A","mc":{"s":"항고에 대한 설명으로 옳은 것만을 모두 고르면?","d":"(다툼이 있는 경우 판례에 의함)\nㄱ. 판사가 증거보전청구( 형사소송법 제184조)를 기각한 결정에 대해서는 항고할 수 없다.\nㄴ. 압수물에 대하여 몰수의 선고가 없어 압수가 해제된 것으로 간주되었음( 형사소송법 제332조)에도 불구하고 검사가 그 해제된 압수물의 인도를 거부하는 조치에 대해서는 준항고로 불복할 수 없다.\nㄷ. 약식명령에 대한 정식재판청구를 기각하는 결정에 대해서는 즉시항고할 수 있다.\nㄹ. 국민의 형사재판 참여에 관한 법률 에 따라 사건을 국민참여재판으로 진행 또는 배제하기로 하는 법원의 결정에 대해서는 즉시항고할 수 있다.","o":["ㄱ, ㄴ","ㄴ, ㄷ","ㄴ, ㄹ","ㄱ, ㄷ, ㄹ"],"a":2}},{"y":2020,"e":"국가직 9급","qn":20,"i":"N92020-20","t":"피의자의 지위에 있지 아니한 자가 한 진술은 수사기관에 의하여 진술거부권이 고지되지 아니하였더라도 증거능력을 부정할 것은 아니다.","c":"A","mc":{"s":"피의자의 지위에 있지 아니한 자가 한 진술은 수사기관에 의하여 진술거부권이 고지되지 아니하였더라도 증거능력을 부정할 것은 아니다.","d":"다음 설명 중 옳은 것만을 모두 고르면? (다툼이 있는 경우 판례에 의함)\nㄱ. 국가는 무죄판결이 확정되어 당해 사건의 피고인이었던 자에 대하여 그 재판에 소요된 비용을 보상할 경우에 그 비용의 보상은 피고인이었던 자의 청구에 따라 무죄판결을 선고한 법원의 합의부에서 결정으로 한다. 다만, 이 청구는 무죄판결이 확정된 사실을 안 날부터 3년, 무죄판결이 확정된 때부터 5년 이내에 하여야 한다.\nㄴ.\nㄷ. 사법경찰관이 피의자에게 진술거부권을 행사할 수 있음을 알려 주고 그 행사 여부를 질문하였더라도, 진술거부권 행사 여부에 대한 피의자의 답변이 자필로 기재되어 있지 아니하거나 그 답변 부분에 피의자의 기명날인 또는 서명이 되어 있지 아니한 사법경찰관 작성의 피의자신문조서는 특별한 사정이 없는 한 적법한 절차와 방식에 따라 작성된 조서라 할 수 없으므로 증거능력이 인정되지 않는다.\nㄹ. 음주운전자가 정당한 이유 없이 상당한 시간이 경과한 후에야 경찰관의 호흡측정 결과에 이의를 제기하면서 2차 호흡측정 또는 혈액채취의 방법에 의한 측정을 요구하는 경우에, 경찰공무원이 2차 호흡측정 또는 혈액채취의 방법에 의한 측정을 실시하지 않았다고 하더라도 1차 호흡측정기에 의한 측정의 결과만으로 음주운전 사실을 증명할 수 있다.","o":["ㄱ, ㄴ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":4}},{"y":2021,"e":"국가직 9급","qn":10,"i":"N92021-10-1","t":"피고인만 항소한 경우 제1심법원이 소송비용의 부담을 명하는 재판을 하지 않았음에도 항소심법원이 제1심의 소송비용에 관하여 피고인에게 부담하도록 재판을 하였다면 불이익변경 금지원칙에 위배된다.","ox":"X","m":"①","c":"A"},{"y":2021,"e":"국가직 9급","qn":10,"i":"N92021-10-2","t":"경합범 관계에 있는 수 개의 범죄사실을 유죄로 인정하여 한 개의 형을 선고한 불가분의 확정판결에서 그 중 일부의 범죄사실에 대하여만 재심청구의 이유가 있는 것으로 인정 되었으나 그 판결 전부에 대하여 재심개시의 결정을 한 경우, 불이익변경금지원칙이 적용되어 원판결의 형보다 중한 형을 선고하지 못한다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"국가직 9급","qn":10,"i":"N92021-10-3","t":"피고인이 항소심 선고 이전에 19세에 도달하여 제1심에서 선고한 부정기형을 파기하고 정기형을 선고함에 있어 불이익 변경금지원칙 위반 여부를 판단하는 기준은 부정기형의 장기와 단기의 중간형이 되어야 한다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"국가직 9급","qn":10,"i":"N92021-10-4","t":"벌금형의 환형유치기간이 징역형의 기간을 초과한다고 하더라도, 벌금형이 징역형보다 경한 형이라고 보아야 한다.","ox":"O","m":"④","c":"A","tp":"불이익변경금지원칙"},{"y":2021,"e":"국가직 9급","qn":14,"i":"N92021-14-1","t":"즉시항고의 제기기간은 7일로 한다.","ox":"O","m":"①","c":"A","tp":"상소"},{"y":2021,"e":"국가직 9급","qn":14,"i":"N92021-14-2","t":"항소를 함에는 항소장을 원심법원에 제출하여야 한다.","ox":"O","m":"②","c":"A","tp":"상소"},{"y":2021,"e":"국가직 9급","qn":14,"i":"N92021-14-3","t":"형사소송에서는 판결등본이 당사자에게 송달되는 여부에 관계 없이 공판정에서 판결이 선고된 날부터 상소기간이 기산되며, 이는 피고인이 불출석한 상태에서 재판을 하는 경우에도 마찬가지이다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"국가직 9급","qn":14,"i":"N92021-14-4","t":"항고는 즉시항고 외에는 재판의 집행을 정지하는 효력이 없으므로 원심법원 또는 항고법원이 결정으로 항고에 대한 결정이 있을 때까지 집행을 정지할 수 없다.","ox":"X","m":"④","c":"A","tp":"상소"},{"y":2021,"e":"국가직 9급","qn":20,"i":"N92021-20-1","t":"미결구금을 당하여 이 법에 따라 보상을 청구할 수 있는 자가 그 청구를 하지 아니하고 사망한 경우, 그 상속인이 이를 청구할 수 있다.","ox":"O","m":"①","c":"A","tp":"형사보상 및 명예회복"},{"y":2021,"e":"국가직 9급","qn":20,"i":"N92021-20-2","t":"1개의 재판으로 경합범의 일부에 대하여 무죄재판을 받고 다른 부분에 대하여 유죄재판을 받았던 경우에는 법원은 재량으로 보상청구의 전부 또는 일부를 기각할 수 있다.","ox":"O","m":"②","c":"A","tp":"형사보상 및 명예회복"},{"y":2021,"e":"국가직 9급","qn":20,"i":"N92021-20-3","t":"형사보상을 받을 자가 다른 법률에 따라 손해배상을 청구하는 것은 금지된다.","ox":"X","m":"③","c":"A","tp":"형사보상 및 명예회복"},{"y":2021,"e":"국가직 9급","qn":20,"i":"N92021-20-4","t":"보상청구가 이유있을 때에는 보상결정을 하여야 하며, 이러한 보상결정에 대하여는 1주일 이내에 즉시항고할 수 있다.","ox":"O","m":"④","c":"A","tp":"형사보상 및 명예회복"},{"y":2023,"e":"국가직 9급","qn":4,"i":"N92023-04-1","t":"약식명령에 대한 정식재판 절차에서 유죄판결을 확정받은 자가 재심을 청구할 경우, 재심청구의 대상은 유죄의 확정판결이 아니라 약식명령이다.","ox":"X","m":"①","c":"A","tp":"상소 및 특별절차"},{"y":2023,"e":"국가직 9급","qn":4,"i":"N92023-04-2","t":"공소시효가 완성된 사실을 간과한 채 피고인에 대하여 약식명령을 발령하여 확정된 경우는 판결에 관한 법령의 위반에 해당하므로 비상상고의 대상이 된다.","ox":"O","m":"②","c":"A","tp":"상소 및 특별절차"},{"y":2023,"e":"국가직 9급","qn":4,"i":"N92023-04-3","t":"제1심법원이 결정으로 인정한 사실에 대해 법령을 적용하지 않았거나 법령의 적용에 착오가 있는 경우, 그 결정은 비약적 상고의 대상이 된다.","ox":"X","m":"③","c":"A","tp":"상소 및 특별절차"},{"y":2023,"e":"국가직 9급","qn":4,"i":"N92023-04-4","t":"약식명령을 발부한 법관이 그 정식재판 절차의 항소심 판결에 관여한 경우, 이는 제척사유인 ‘법관이 사건에 관하여 전심재판 또는 그 기초되는 조사, 심리에 관여한 때’에 해당하지 않는다.","ox":"X","m":"④","c":"A","tp":"상소 및 특별절차"},{"y":2023,"e":"국가직 9급","qn":9,"i":"N92023-09-1","t":"항소심에서는 검사의 공소취소가 허용되지 않는다.","ox":"O","m":"①","c":"A","tp":"형사절차"},{"y":2023,"e":"국가직 9급","qn":9,"i":"N92023-09-2","t":"종국재판이 외부적으로 성립한 경우 종국재판을 한 법원은 그 재판을 철회하거나 변경할 수 없다.","ox":"O","m":"②","c":"A","tp":"형사절차"},{"y":2023,"e":"국가직 9급","qn":9,"i":"N92023-09-3","t":"재판장의 재판에 대한 준항고의 청구는 재판의 고지있는 날로부터 7일 이내에 하여야 한다.","ox":"O","m":"③","c":"A","tp":"형사절차"},{"y":2023,"e":"국가직 9급","qn":9,"i":"N92023-09-4","t":"피고인과 공범관계에 있는 다른 피의자에 대한 사법경찰관 작성 피의자신문조서는 형사소송법 제312조제4항의 요건을 갖추면 피고인이 공판기일에 그 조서의 내용을 부인하더라도 이를 유죄 인정의 증거로 사용할 수 있다.","ox":"X","m":"④","c":"A","tp":"형사절차"},{"y":2023,"e":"국가직 9급","qn":20,"i":"N92023-20-1","t":"재심사유 중 ‘무죄 등을 인정할 명백한 증거’에 해당하는지 여부는 새로 발견된 증거만을 독립적ㆍ고립적으로 고찰하여 그 증거가치만으로 판단하여야 한다.","ox":"X","m":"①","c":"A"},{"y":2023,"e":"국가직 9급","qn":20,"i":"N92023-20-2","t":"재심심판절차에서는 특별한 사정이 없는 한 재심대상사건과 별개의 공소사실을 추가하는 내용의 공소장변경을 하거나 일반 절차로 진행 중인 별개의 형사사건을 병합하여 심리할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"국가직 9급","qn":20,"i":"N92023-20-3","t":"특별사면으로 형 선고의 효력이 상실된 유죄확정판결에 대하여 재심개시결정이 확정된 경우, 재심심판절차에서는 그 심급에 따라 다시 심판하여 특별사면을 이유로 면소판결을 하여야 한다.","ox":"X","m":"③","c":"A"},{"y":2023,"e":"국가직 9급","qn":20,"i":"N92023-20-4","t":"경합범 관계에 있는 수개의 범죄사실을 유죄로 인정하여 1개의 형을 선고한 불가분의 확정판결에서 그 중 일부의 범죄사실에 대하여만 재심청구의 이유가 인정되는 경우, 그 부분에 대해서만 재심개시결정을 하여야 한다.","ox":"X","m":"④","c":"A"},{"y":2024,"e":"국가직 9급","qn":5,"i":"N92024-05-1","t":"국민참여재판에서 피고인이 공판정에서 공소사실에 대하여 자백한 경우에도 간이공판절차를 적용할 수는 없다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"국가직 9급","qn":5,"i":"N92024-05-2","t":"법원에서 피고인이 국민참여재판을 원하는지에 관한 의사 확인 절차를 거치지 아니한 채 통상의 공판절차로 재판을 진행한 경우, 이는 피고인의 국민참여재판을 받을 권리에 대한 중대한 침해로서 그 절차는 위법하고 이러한 위법한 공판절차에서 이루어진 소송행위도 무효이며, 이러한 하자는 어떠한 경우에도 치유될 수 없다.","ox":"X","m":"②","c":"A"},{"y":2024,"e":"국가직 9급","qn":5,"i":"N92024-05-3","t":"피고인은 국민참여재판 배제결정에 대하여 즉시항고를 할 수 있고, 검사는 국민참여재판으로 진행하기로 하는 결정에 대하여 보통항고를 할 수 있다.","ox":"X","m":"③","c":"A"},{"y":2024,"e":"국가직 9급","qn":5,"i":"N92024-05-4","t":"성폭력범죄의 처벌 등에 관한 특례법 제2조의 성폭력범죄 사건에서 피해자 또는 법정대리인이 국민참여재판을 원하지 아니하는 경우, 법원은 국민참여재판으로 진행할 수 없다.","ox":"X","m":"④","c":"A"},{"y":2024,"e":"국가직 9급","qn":10,"i":"N92024-10-1","t":"피고인이 질병으로 병원에 입원하였거나 기거불능이었기 때문에 상소를 하지 못하였다는 것은 상소권회복의 사유에 해당하지 않는다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"국가직 9급","qn":10,"i":"N92024-10-2","t":"피고인이 형사소송이 계속 중인 사실을 알면서도 법원에 거주지 변경신고를 하지 않아서 공시송달절차에 의하여 재판이 진행된 경우, 비록 소송촉진 등에 관한 특례법에 위배된 공시송달에 터 잡아 피고인의 출석없이 판결의 선고가 이루어지고 상소제기 기간이 도과하였더라도 상소권회복청구가 허용될 수는 없다.","ox":"X","m":"②","c":"A"},{"y":2024,"e":"국가직 9급","qn":10,"i":"N92024-10-3","t":"교도소 담당직원이 피고인에게 상소권회복청구를 할 수 없다고 하면서 형사소송규칙 제177조에 따른 편의를 제공하지 않았다고 해도, 이것은 상소권자의 책임질 수 없는 사유로 상소하지 못한 것이라고 보기 어렵다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"국가직 9급","qn":10,"i":"N92024-10-4","t":"피고인이 공동피고인의 기망에 의하여 항소권을 포기하였음을 항소제기 기간이 도과한 뒤에야 비로소 알게 되었다 하더라도 이러한 사정은 피고인이 책임질 수 없는 사유에 해당한다고 볼 수 없다.","ox":"O","m":"④","c":"A","tp":"상소권회복"},{"y":2024,"e":"국가직 9급","qn":11,"i":"N92024-11-1","t":"상소는 재판의 일부에 대하여 할 수 있으며, 일부에 대한 상소는 그 일부와 불가분의 관계에 있는 부분에 대하여도 효력이 미친다.","ox":"O","m":"①","c":"A","tp":"일부상소"},{"y":2024,"e":"국가직 9급","qn":11,"i":"N92024-11-2","t":"포괄일죄에 대하여 일부유죄, 일부무죄의 판결이 선고된 경우에 검사만이 무죄부분에 대하여 상고를 하고 피고인은 상고하지 않은 경우, 유죄부분도 상고심에 이전되어 심판의 대상이 된다.","ox":"O","m":"②","c":"A","tp":"일부상소"},{"y":2024,"e":"국가직 9급","qn":11,"i":"N92024-11-3","t":"포괄일죄의 일부만이 유죄로 된 경우 그 유죄부분에 대하여 피고인만이 항소하고 공소기각으로 판단된 부분에 대하여 검사는 항소하지 않은 경우, 공소기각으로 판단된 부분도 항소심의 심판 대상이 되므로 항소심은 그 부분에까지 나아가 판단해야 한다.","ox":"X","m":"③","c":"A","tp":"일부상소"},{"y":2024,"e":"국가직 9급","qn":11,"i":"N92024-11-4","t":"제1심이 경합범에 대하여 일부무죄ㆍ일부유죄로 판결한 것에 대하여 검사만이 무죄부분에 대하여 항소한 경우, 피고인과 검사가 항소하지 아니한 유죄부분은 항소기간이 지남에 따라 확정되어 무죄부분만이 항소심의 심판대상이 되므로 항소심에서 파기할 때에는 무죄부분만을 파기하여야 한다.","ox":"O","m":"④","c":"A","tp":"일부상소"},{"y":2024,"e":"국가직 9급","qn":12,"i":"N92024-12-1","t":"공소취소에 의한 공소기각의 결정이 확정된 때에는 공소취소 후 그 범죄사실에 대한 다른 중요한 증거를 발견한 경우에 한하여 다시 공소를 제기할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"국가직 9급","qn":12,"i":"N92024-12-2","t":"상습범으로 유죄의 확정판결을 받은 사람이 그 후 동일한 습벽에 의해 후행범죄를 범하였는데 유죄의 확정판결에 대하여 재심이 개시된 경우, 동일한 습벽에 의한 후행범죄가 재심대상판결에 대한 재심판결 선고 전에 범하여졌다면 재심판결의 기판력이 후행범죄에 미친다.","ox":"X","m":"②","c":"A"},{"y":2024,"e":"국가직 9급","qn":12,"i":"N92024-12-3","t":"피고인에게 불리한 증거인 증인이 주신문의 경우와 달리 반대신문에 대하여는 답변을 하지 아니하는 등 진술 내용의 모순이나 불합리를 그 증인신문 과정에서 드러내어 이를 탄핵하는 것이 사실상 곤란하였고, 그것이 피고인 또는 변호인에게 책임 있는 사유에 기인한 것이 아닌 경우, 이를 정당화할 수 있는 특별한 사정이 존재하지 않는 이상 증인의 법정진술은 위법한 증거로서 증거능력을 인정하기 어렵다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"국가직 9급","qn":12,"i":"N92024-12-4","t":"이미 선고된 판결의 내용을 실질적으로 변경하는 것은 형사소송 규칙에서 예정하고 있는 경정의 범위를 벗어나는 것으로서 허용되지 않으며, 경정결정은 이를 주문에 기재하여야 하고, 판결 이유에만 기재한 경우 경정결정이 이루어졌다고 할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"국가직 9급","qn":6,"i":"N92025-06","t":"상소에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"상소에 대한 설명으로 옳지 않은 것은?","d":"","o":["피고인만이 항소한 사건에서 항소심이 피고인에 대하여 제1심이 인정한 범죄사실의 일부를 무죄로 인정하면서도 제1심과 동일한 형을 선고하였다면, 이는 형사소송법 제368조 소정의 불이익 변경금지 원칙에 위배된다.","상고심으로부터 사건을 환송받은 법원이 상고법원이 파기이유로 한 사실상 및 법률상의 판단에 대하여 심리하는 과정에서 새로운 증거가 제시되어 기속적 판단의 기초가 된 증거관계에 변동이 생기면 상고법원의 파기이유와 달리 판단할 수 있다.","항소심 판결이 선고된 사건에 대하여 항소권회복청구가 제기된 경우, 그 청구를 받은 법원은 항소권회복청구의 원인에 관한 판단에 나아갈 필요 없이 결정으로 이를 기각하여야 한다.","피고인에 대하여 공시송달의 방법에 따라 공소장 등이 송달되고 피고인이 불출석한 가운데 판결이 선고되어 확정된 후 검거되어 수용된 경우, 특별한 사정이 없으면 그 판결에 의한 형의 집행으로 수용된 날부터 상소 제기 기간 내에 상소권회복청구를 하지 않았다면 그 상소권회복청구는 방식을 위배한 것으로서 허가될 수 없다. 2025년도 국가공무원 9급 공채 필기시험 형"],"a":1}},{"y":2025,"e":"국가직 9급","qn":7,"i":"N92025-07-1","t":"재심청구인이 재심의 청구를 한 후 청구에 관한 결정이 확정되기 전에 사망한 경우에 재심청구절차는 재심청구인의 사망으로 종료한다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"국가직 9급","qn":7,"i":"N92025-07-2","t":"당사자가 법원에 재심청구의 이유에 관한 사실조사신청을 한 경우에 법원은 사실조사신청에 대하여 재판을 할 필요는 없지만, 만일 법원이 사실조사신청을 배척하는 경우에는 당사자에게 이러한 배척 사실을 고지하여야 한다.","ox":"X","m":"②","c":"A"},{"y":2025,"e":"국가직 9급","qn":7,"i":"N92025-07-3","t":"형사소송법 제420조제5호에 따르면 형의 선고를 받은 자에 대하여 ‘원판결이 인정한 죄보다 가벼운 죄’를 인정할 명백한 증거가 새로 발견된 때에는 재심을 청구할 수 있는바, ‘원판결이 인정한 죄보다 가벼운 죄’란 원판결이 인정한 죄와는 별개의 죄로서 그 법정형이 가벼운 죄를 말하므로, 같은 죄에 대하여 공소기각을 선고받을 수 있는 경우는 여기에서의 ‘가벼운 죄’에 해당하지 않는다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"국가직 9급","qn":7,"i":"N92025-07-4","t":"형사소송법 제420조에 따르면 소정의 이유가 있는 경우에 ‘유죄의 확정판결’에 대하여 그 선고를 받은 자의 이익을 위하여 재심을 청구할 수 있는바, ‘유죄의 확정판결’에는 특별사면으로 형 선고의 효력을 잃은 유죄의 확정판결도 포함된다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"국가직 9급","qn":9,"i":"N92025-09-1","t":"재판부가 당사자의 증거신청을 채택하지 않았다는 사유만으로는 재판의 공평을 기대하기 어려운 객관적인 사정이 있다고 할 수 없다.","ox":"O","m":"①","c":"A","tp":"법원의 판단이나 조치"},{"y":2025,"e":"국가직 9급","qn":9,"i":"N92025-09-2","t":"교도소 재소자인 재정신청인이 재정신청 기각결정에 대한 재항고장을 제출한 경우, 그 재항고장이 재항고 제기기간 내에 교도소장에게 제출된 이상 재항고장이 법원에 도달한 시기와 상관없이 형사소송법 제344조제1항에 따른 재소자에 대한 특칙을 준용하여 적법한 기간 내에 제기된 것으로 보아야 한다.","ox":"X","m":"②","c":"A","tp":"법원의 판단이나 조치"},{"y":2025,"e":"국가직 9급","qn":9,"i":"N92025-09-3","t":"경합범 중 일부에 대하여 무죄, 일부에 대하여 유죄를 선고한 제1심 판결에 대하여 검사만이 무죄 부분에 대하여 항소를 한 경우, 항소심에서 이를 파기할 때 파기의 범위는 무죄 부분에 한정된다.","ox":"O","m":"③","c":"A","tp":"법원의 판단이나 조치"},{"y":2025,"e":"국가직 9급","qn":9,"i":"N92025-09-4","t":"항소심이 제1심의 공소기각 판결이 법률에 어긋난다고 판단한 경우에는 본안에 들어가 심리할 것이 아니라 제1심 판결을 파기 하고 사건을 제1심 법원에 환송하여야 한다.","ox":"O","m":"④","c":"A","tp":"법원의 판단이나 조치"}],"7":[{"y":2015,"e":"국가직 9급","qn":17,"i":"N92015-17-1","t":"상상적 경합관계에 있는 수죄 중 1죄에 대한 확정판결의 기판력은 다른 죄에도 미친다.","ox":"O","m":"①","c":"A","tp":"상상적 경합범의 소송법적 효과"},{"y":2015,"e":"국가직 9급","qn":17,"i":"N92015-17-2","t":"하나의 행위가 허위공문서작성죄와 직무유기죄의 구성요건을 동시에 충족하는 경우 검사가 직무유기죄로만 기소하더라도 적법하다.","ox":"O","m":"②","c":"A","tp":"상상적 경합범의 소송법적 효과"},{"y":2015,"e":"국가직 9급","qn":17,"i":"N92015-17-3","t":"수죄 중 일부만이 친고죄일 때 친고죄 부분에 대하여 고소가 없거나 취소된 경우 친고죄가 중한 죄이더라도 경한 비친고죄의 처벌에 영향을 미치지 아니한다.","ox":"O","m":"③","c":"A","tp":"상상적 경합범의 소송법적 효과"},{"y":2015,"e":"국가직 9급","qn":17,"i":"N92015-17-4","t":"상상적 경합관계에 있는 수죄 전부에 대하여 무죄가 선고되었고, 검사가 상고하면서 그 중 일부 무죄 부분에 대하여 상고이유로 삼지 않았다고 하더라도 상고심에서는 그 무죄 부분까지 전부 판단하여야 한다.","ox":"X","m":"④","c":"A","tp":"상상적 경합범의 소송법적 효과"},{"y":2015,"e":"국가직 9급","qn":18,"i":"N92015-18","t":"면소판결의 대상에 해당하는 것은?","c":"A","mc":{"s":"면소판결의 대상에 해당하는 것은?","d":"","o":["범의유발형 함정수사에 기하여 공소가 제기된 때","소년법 상 보호처분을 받은 사건과 동일한 사건에 대하여 공소가 제기된 때","즉결심판으로 확정된 경범죄처벌법 위반의 범죄사실과 기본적 사실관계에 있어서 동일한 사실에 대하여 상해치사죄로 공소가 제기된 때","검사가 상습범으로서 포괄일죄의 관계에 있는 여러 개의 범죄사실 중 일부를 단순일죄로 기소하여 그에 대한 유죄판결이 확정된 후 그 확정판결의 사실심판결 선고 전에 저질러진 나머지 범죄에 대하여 공소가 제기된 때"],"a":3}},{"y":2015,"e":"국가직 9급","qn":19,"i":"N92015-19-1","t":"유죄판결을 선고하면서 판결이유에 범죄사실, 증거의 요지, 법령의 적용 중 어느 하나를 전부 누락한 경우 판결에 영향을 미친 법률위반에 해당한다.","ox":"O","m":"①","c":"A","tp":"유죄판결에 명시될 이유의 기재"},{"y":2015,"e":"국가직 9급","qn":19,"i":"N92015-19-2","t":"사기죄의 법률적용에 있어서 형법 제347조만을 적시하고 그것이 동조 제1항에 해당하는 범죄인지 제2항에 해당하는 범죄인지를 밝히지 않았다면 위법이다.","ox":"X","m":"②","c":"A","tp":"유죄판결에 명시될 이유의 기재"},{"y":2015,"e":"국가직 9급","qn":19,"i":"N92015-19-3","t":"사실인정에 배치되는 증거에 대한 판단을 반드시 판결이유에 기재하여야 하는 것은 아니므로 피고인의 알리바이를 내세우는 증인들의 증언에 관한 판단을 하지 아니하였더라도 위법이 아니다.","ox":"O","m":"③","c":"A","tp":"유죄판결에 명시될 이유의 기재"},{"y":2015,"e":"국가직 9급","qn":19,"i":"N92015-19-4","t":"항소심에서 제1심 형량이 적절하다고 판단하여 항소기각의 판결을 선고하는 경우 양형의 조건이 되는 사유는 판결에 일일이 명시하지 아니하여도 위법이 아니다.","ox":"O","m":"④","c":"A","tp":"유죄판결에 명시될 이유의 기재"},{"y":2017,"e":"국가직 9급","qn":7,"i":"N92017-07-1","t":"정식재판청구기간을 도과한 약식명령에 기하여 피고인을 노역장에 유치한 후 정식재판청구권회복결정에 따라 사건을 공판절차에 의하여 심리하는 경우, 법원은 노역장 유치기간을 미결구금일수로 보아 이를 본형에 산입할 수 있다.","ox":"X","m":"①","c":"A","tp":"미결구금일수의 산입"},{"y":2017,"e":"국가직 9급","qn":7,"i":"N92017-07-2","t":"판결선고 후 판결확정 전 구금일수는 판결선고 당일의 구금 일수를 포함하여 전부를 본형에 산입한다.","ox":"O","m":"②","c":"A","tp":"미결구금일수의 산입"},{"y":2017,"e":"국가직 9급","qn":7,"i":"N92017-07-3","t":"기피신청에 의하여 소송진행이 정지된 기간은 미결구금일수에 산입되지 않는다.","ox":"X","m":"③","c":"A","tp":"미결구금일수의 산입"},{"y":2017,"e":"국가직 9급","qn":7,"i":"N92017-07-4","t":"피고인에 대한 감정유치기간은 미결구금일수에 산입되지 않는다.","ox":"X","m":"④","c":"A","tp":"미결구금일수의 산입"},{"y":2017,"e":"국가직 9급","qn":8,"i":"N92017-08-1","t":"유죄판결을 함에 있어서 형의 가중 또는 감면의 이유되는 사실의 진술이 있는 때에는 이에 대한 판단을 명시해야 하므로, 임의적 감경사유인 자수의 주장에 대하여 판단을 하지 아니하는 것은 위법하다.","ox":"X","m":"①","c":"A","tp":"재판"},{"y":2017,"e":"국가직 9급","qn":8,"i":"N92017-08-2","t":"상습범으로서 포괄일죄의 관계에 있는 여러 개의 범죄사실 중 일부에 대하여 유죄판결이 확정되어 상습범으로 처단된 후 그 확정판결의 사실심선고 전에 저질러진 나머지 범행에 대해 공소가 제기된 때에는 면소판결을 선고하여야 한다.","ox":"O","m":"②","c":"A","tp":"재판"},{"y":2017,"e":"국가직 9급","qn":8,"i":"N92017-08-3","t":"포괄일죄의 일부에 대하여는 유죄의 증거가 없고 나머지 부분에 대하여 공소시효가 완성된 경우에는 주문에 무죄를 표시하고 면소부분은 판결이유에서 설명하면 된다.","ox":"O","m":"③","c":"A","tp":"재판"},{"y":2017,"e":"국가직 9급","qn":8,"i":"N92017-08-4","t":"공소사실에 대해서 모두 공소시효가 완성되었다는 이유로 면소판결이 선고된 경우 피고인은 범죄혐의가 없음을 이유로 무죄판결을 구하는 상소를 제기할 수 없다.","ox":"O","m":"④","c":"A","tp":"재판"},{"y":2018,"e":"국가직 9급","qn":13,"i":"N92018-13-1","t":"과태료를 납부한 후에 다시 형사처벌을 하는 것은 일사부재리의 원칙에 반하는 것이 아니다.","ox":"O","m":"①","c":"A","tp":"기판력 또는 일사부재리의 효력"},{"y":2018,"e":"국가직 9급","qn":13,"i":"N92018-13-2","t":"피고인이 성명을 모용한 경우 기판력은 피모용자에게 미치지 않는다.","ox":"O","m":"②","c":"A","tp":"기판력 또는 일사부재리의 효력"},{"y":2018,"e":"국가직 9급","qn":13,"i":"N92018-13-3","t":"면소판결이 확정된 경우에는 일사부재리의 효력이 인정된다.","ox":"O","m":"③","c":"A","tp":"기판력 또는 일사부재리의 효력"},{"y":2018,"e":"국가직 9급","qn":13,"i":"N92018-13-4","t":"약식명령에 대한 기판력의 시간적 범위는 약식명령의 도달시를 기준으로 한다.","ox":"X","m":"④","c":"A","tp":"기판력 또는 일사부재리의 효력"},{"y":2019,"e":"국가직 9급","qn":11,"i":"N92019-11","t":"자수에 대한 설명으로 옳은 것은?","c":"A","mc":{"s":"자수에 대한 설명으로 옳은 것은?","d":"","o":["피고인이 자수하였음에도 불구하고 법원이 형법 제52조제1항에 따른 자수감경을 하지 않거나 자수감경 주장에 대하여 판단을 하지 않았더라도 위법하지 않다.","수사기관에의 자발적 신고 내용이 범행을 부인하는 등 범죄 성립요건을 갖추지 아니한 경우에는 자수는 성립하지 않지만, 그 후 수사과정에서 범행을 시인하였다면 새롭게 자수가 성립될 여지가 있다.","수사기관의 직무상의 질문 또는 조사에 응하여 범죄사실을 진술하는 경우라도 자수가 인정될 수 있다.","범인이 수사기관에 뇌물수수의 범죄사실을 자발적으로 신고 하였다면, 특정범죄 가중처벌 등에 관한 법률 의 적용을 피하기 위해 그 수뢰액을 실제보다 적게 신고한 것일지라도 자수는 성립한다. 2019년도 국가공무원 9급 공채 필기시험 형사"],"a":1}},{"y":2020,"e":"국가직 9급","qn":1,"i":"N92020-01-1","t":"형사사건으로 외국에서 미결구금되었다가 무죄판결을 받은 경우, 그 미결구금일수를 국내에서 같은 행위로 인하여 선고받는 형에 산입하지 않더라도 위법하지 않다.","ox":"O","m":"①","c":"A","tp":"형사절차"},{"y":2020,"e":"국가직 9급","qn":1,"i":"N92020-01-2","t":"불심검문 당시 여러 사정들을 종합적으로 고려하여 검문자가 경찰관이고 검문이유가 범죄행위에 관한 것임을 검문대상자가 충분히 알고 있었다고 보이는 경우라도, 검문자가 신분증을 제시하지 않았다면 위법하다.","ox":"X","m":"②","c":"A","tp":"형사절차"},{"y":2020,"e":"국가직 9급","qn":1,"i":"N92020-01-3","t":"판결의 선고는 변론을 종결한 기일에 하여야 하고, 특별한 사정이 있는 때라도 그 선고기일은 변론종결 후 14일 이내로 지정되어야 한다.","ox":"O","m":"③","c":"A","tp":"형사절차"},{"y":2020,"e":"국가직 9급","qn":1,"i":"N92020-01-4","t":"법원은 피고인의 신청이 없으면 토지관할에 관하여 관할위반의 선고를 할 수 없고, 피고인은 피고사건에 대한 진술 후에는 토지관할위반의 신청을 할 수 없다.","ox":"O","m":"④","c":"A","tp":"형사절차"},{"y":2020,"e":"국가직 9급","qn":14,"i":"N92020-14","t":"면소판결을 할 수 있는 것은?","c":"A","mc":{"s":"면소판결을 할 수 있는 것은?","d":"","o":["피고인이 유죄판결에 대하여 상고하였는데, 그 후에 헌법 재판소가 처벌의 근거가 된 법률조항에 대해 헌법불합치결정을 선고하면서 개정시한을 정하여 입법개선을 촉구하였는데도 위 시한까지 법률 개정이 이루어지지 아니한 경우","유죄판결 확정 후 피고인에 대하여 형 선고의 효력을 상실케 하는 특별사면이 있었는데, 이후 재심개시결정이 확정되어 재심심판절차를 진행하게 된 경우","피고인이 외국에서 유죄판결을 받고 판결이 확정된 후 우리나라에서 같은 행위로 다시 기소된 경우","구 형법 상 혼인빙자간음죄(제304조)로 기소되었는데, 그 후 해당 조문의 혼인빙자간음죄 부분이 헌법재판소의 결정에 의하여 위헌으로 판단되었고, 이를 삭제하는 형법 개정을 하면서 부칙 등에서 그 시행 전 행위에 대한 벌칙의 적용에 관하여 아무런 경과규정을 두지 아니한 경우"],"a":4}},{"y":2020,"e":"국가직 9급","qn":18,"i":"N92020-18-1","t":"공소기각의 판결은 피고인에게 불이익한 재판이라고 할 수 없으므로 이에 대하여 피고인은 상소권이 없다.","ox":"O","m":"①","c":"A","tp":"기소와 재판"},{"y":2020,"e":"국가직 9급","qn":18,"i":"N92020-18-2","t":"공소사실의 동일성이 인정되지 아니하고 실체적 경합관계에 있는 수 개의 공소사실의 전부 또는 일부를 철회하는 공소취소에 따라 공소기각의 결정이 확정된 때와 마찬가지로, 포괄일죄로 기소된 공소사실 중 일부에 대하여 공소장변경의 방식으로 이루어진 공소사실의 일부 철회가 있는 경우에 그 범죄사실에 대하여도 다른 중요한 증거가 발견되지 않는 한 재기소할 수 없다.","ox":"X","m":"②","c":"A","tp":"기소와 재판"},{"y":2020,"e":"국가직 9급","qn":18,"i":"N92020-18-3","t":"무죄의 제1심판결에 대하여 검사가 채증법칙 위배 등을 들어 항소하였으나 공소기각의 사유가 있다고 인정될 경우, 항소심 법원은 직권으로 판단하여 제1심판결을 파기하고 피고인에 대한 공소사실에 관하여 유·무죄의 판단을 하기에 앞서 공소기각의 판결을 선고하여야 한다.","ox":"O","m":"③","c":"A","tp":"기소와 재판"},{"y":2020,"e":"국가직 9급","qn":18,"i":"N92020-18-4","t":"위법한 함정수사에 기한 공소제기는 그 절차가 법률의 규정에 위반하여 무효인 때에 해당하여 공소기각의 판결을 하여야 한다.","ox":"O","m":"④","c":"A","tp":"기소와 재판"},{"y":2021,"e":"국가직 9급","qn":18,"i":"N92021-18-1","t":"공소가 취소된 경우 법원은 결정으로 공소를 기각하여야 한다.","ox":"O","m":"①","c":"A","tp":"재판"},{"y":2021,"e":"국가직 9급","qn":18,"i":"N92021-18-2","t":"항고의 제기가 법률상의 방식에 위반하거나 항고권 소멸 후인 것이 명백한 때에는 원심법원은 결정으로 항고를 기각하여야 한다.","ox":"O","m":"②","c":"A","tp":"재판"},{"y":2021,"e":"국가직 9급","qn":18,"i":"N92021-18-3","t":"판결선고 전 미결구금일수는 그 전부가 법률상 당연히 본형에 산입되므로 판결에서 별도로 미결구금일수 산입에 관한 사항을 판단할 필요가 없다.","ox":"O","m":"③","c":"A","tp":"재판"},{"y":2021,"e":"국가직 9급","qn":18,"i":"N92021-18-4","t":"상습범으로서 포괄적 일죄의 관계에 있는 여러 개의 범죄사실 중 일부에 대하여 유죄판결이 확정된 경우에, 그 확정판결의 사실심판결 선고 전에 저질러진 나머지 범죄에 대하여 새로이 공소가 제기되었다면 판결로 공소를 기각하여야 한다.","ox":"X","m":"④","c":"A","tp":"재판"},{"y":2023,"e":"국가직 9급","qn":13,"i":"N92023-13","t":"상습범으로서 포괄일죄의 관계에 있는 여러 개의 사기범죄사실 중 일부에 대해 기소된 피고인에게 단순사기죄의 유죄판결이 확정된 후, 확정판결의 사실심판결 선고 전에 피고인이 범한 나머지 범죄에 대해 검사가 상습사기죄로 추가 기소를 한 경우 법원은 어떠한 재판을 해야 하는가?","c":"A","mc":{"s":"상습범으로서 포괄일죄의 관계에 있는 여러 개의 사기범죄사실 중 일부에 대해 기소된 피고인에게 단순사기죄의 유죄판결이 확정된 후, 확정판결의 사실심판결 선고 전에 피고인이 범한 나머지 범죄에 대해 검사가 상습사기죄로 추가 기소를 한 경우 법원은 어떠한 재판을 해야 하는가?","d":"","o":["공소제기가 법률의 규정에 위반하여 무효인 경우에 해당하므로 공소기각의 판결을 하여야 한다.","확정판결이 있은 때에 해당하므로 면소판결을 하여야 한다.","단순사기죄의 기판력은 추가 기소된 상습사기죄에 미치지 않으므로 실체판결을 하여야 한다.","이미 기소가 된 사건에 대해 다시 기소가 된 이중기소에 해당하므로 공소기각의 판결을 하여야 한다."],"a":3}},{"y":2023,"e":"국가직 9급","qn":19,"i":"N92023-19-1","t":"대한민국헌법 제13조제1항에서 규정하고 있는 이중처벌금지의 원칙에서 ‘처벌’은 원칙적으로 범죄에 대한 형벌 부과를 의미하고, 국가가 행하는 일체의 제재나 불이익처분이 모두 여기에 포함되는 것은 아니다.","ox":"O","m":"①","c":"A","tp":"재판"},{"y":2023,"e":"국가직 9급","qn":19,"i":"N92023-19-2","t":"항소심이 제1심의 재판서에 대한 경정 결정을 하면서 제1심이 선고한 판결의 내용을 실질적으로 변경하는 것은 허용되지 않는다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"국가직 9급","qn":19,"i":"N92023-19-3","t":"공소제기 후 판결의 확정이 없이 공소를 제기한 때로부터 25년이 경과한 때에는 면소판결을 하여야 한다.","ox":"O","m":"③","c":"A","tp":"재판"},{"y":2023,"e":"국가직 9급","qn":19,"i":"N92023-19-4","t":"간통사건에 대한 유죄판결이 간통죄에 대한 헌법재판소의 종전 합헌결정 이전에 확정된 경우, 이 판결에 대한 재심개시결정이 간통죄에 대한 헌법재판소의 위헌결정일 이후에 확정되었다면 재심심판법원은 무죄판결을 하여야 한다.","ox":"X","m":"④","c":"A"},{"y":2024,"e":"국가직 9급","qn":20,"i":"N92024-20-1","t":"검사가 서면인 공소장에 전자문서나 저장매체를 첨부하는 방식으로 공소를 제기한 경우, 서면인 공소장에 기재된 부분만으로는 공소사실이 특정되지 않고 검사가 법원의 특정요구에 응하지 않으면 그 부분에 대해 공소기각의 판결을 선고하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"국가직 9급","qn":20,"i":"N92024-20-2","t":"공소를 제기할 수 없는 법률상의 사유가 있어 공소기각의 판결을 하여야 할 사건에서 그 사건의 실체에 관한 심리가 이미 완료되어 무죄로 판명된 경우라도 무죄의 실체판결을 선고하는 것은 위법하다.","ox":"X","m":"②","c":"A"},{"y":2024,"e":"국가직 9급","qn":20,"i":"N92024-20-3","t":"피고인이 공소를 기각한 제1심판결에 대해 무죄를 주장하며 항소한 경우, 공소기각 판결에 대하여 피고인에게 상소권이 인정 되지 않으므로 이 항소는 법률상의 방식에 위반한 것이 명백한 때에 해당한다.","ox":"O","m":"③","c":"A","tp":"공소기각의 판결"},{"y":2024,"e":"국가직 9급","qn":20,"i":"N92024-20-4","t":"기소 당시에는 이중기소된 위법이 있었다 하여도 그 후 공소사실과 적용법조가 적법하게 변경되어 새로운 사실의 소송계속상태가 있게 된 때에는 공소기각의 판결을 하여야 할 위법상태가 계속 존재한다고 할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"국가직 9급","qn":1,"i":"N92025-01-1","t":"형사소송법 제328조제1항제4호에 규정된 ‘공소장에 기재된 사실이 진실하다 하더라도 범죄가 될 만한 사실이 포함되지 아니하는 때’란 공소장 기재사실 자체에 대한 판단으로 그 사실 자체가 죄가 되지 아니함이 명백한 경우를 말한다.","ox":"O","m":"①","c":"A","tp":"재판"},{"y":2025,"e":"국가직 9급","qn":1,"i":"N92025-01-2","t":"피고인에 대하여 무죄판결을 선고하는 때에도 공소사실에 부합 하는 증거를 배척하는 이유까지 일일이 설시할 필요는 없다고 하더라도, 그 증거들을 배척한 취지를 합리적인 범위 내에서 기재하여야 한다.","ox":"O","m":"②","c":"A","tp":"재판"},{"y":2025,"e":"국가직 9급","qn":1,"i":"N92025-01-3","t":"형사판결은 국가주권의 일부분인 형벌권 행사에 기초한 것이어서 피고인이 외국에서 형사처벌을 과하는 확정판결을 받았더라도 그 외국 판결은 우리나라 법원을 기속할 수 없고 우리나라에서는 기판력도 없어 일사부재리의 원칙이 적용되지 않는다.","ox":"O","m":"③","c":"A","tp":"재판"},{"y":2025,"e":"국가직 9급","qn":1,"i":"N92025-01-4","t":"형벌에 관한 법령의 폐지가 당초부터 헌법에 위배되어 효력이 없는 법령에 대한 것이었다면 당해 법령을 적용하여 공소가 제기된 피고사건은 형사소송법 제326조제4호에서 정한 면소 사유에 해당하는 것이지, 형사소송법 제325조 전단이 규정하는 ‘범죄로 되지 아니한 때’의 무죄사유에 해당한다고 할 수 없다.","ox":"X","m":"④","c":"A","tp":"재판"}],"5":[{"y":2017,"e":"국가직 9급","qn":4,"i":"N92017-04-1","t":"재판장은 효율적이고 집중적인 심리를 위하여 사건을 공판준비 절차에 부칠 수 있으며, 피고인이 국민참여재판을 원하는 의사를 표시한 경우에는 법원이 배제결정을 하는 때를 제외 하고는 사건을 공판준비절차에 부쳐야 한다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"국가직 9급","qn":4,"i":"N92017-04-2","t":"법원은 공판준비절차에서 공소사실 또는 적용법조의 추가·철회 또는 변경을 허가할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"국가직 9급","qn":4,"i":"N92017-04-3","t":"검사와 변호인은 공판준비기일에 출석하여야 하나, 피고인은 법원이 필요하다고 인정하여 소환한 때에 한하여 출석할 수 있고 법원의 소환이 없는 때에는 공판준비기일에 출석할 수 없다.","ox":"X","m":"③","c":"A","tp":"공판준비절차"},{"y":2017,"e":"국가직 9급","qn":4,"i":"N92017-04-4","t":"공판준비기일에 신청하지 못한 증거는 그 신청으로 인하여 소송을 현저히 지연시키지 아니하거나 중대한 과실 없이 공판 준비기일에 제출하지 못하는 등 부득이한 사유를 소명한 경우에 한하여 공판기일에 증거로 신청할 수 있다.","ox":"O","m":"④","c":"A","tp":"공판준비절차"},{"y":2017,"e":"국가직 9급","qn":17,"i":"N92017-17","t":"이에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"이에 대한 설명으로 옳지 않은 것은?","d":"피고인 甲이 제1심 재판의 모두진술에서 공소사실을 인정함에 따라 법원은 간이공판절차에 의하여 심판할 것을 결정하였다.  (다툼이 있는 경우 판례에 의함)","o":["만약 甲이 법정에서 “공소사실은 모두 사실과 다름없다”고 하면서 술에 만취되어 기억이 없다는 취지로 진술한 경우라면 간이공판절차에 의하여 심판할 대상에 해당되지 않는다.","간이공판절차 개시결정은 판결 전 소송절차에 관한 결정이므로 항고할 수 없고, 간이공판절차의 요건을 구비하지 못하였음 에도 불구하고 간이공판절차에 의하여 심판한 경우에는 판결 자체에 대해 상소할 수 있다.","검사가 甲에 대해 작성한 피의자신문조서는 甲이나 그의 변호인의 이의가 없는 한 증거동의가 있는 것으로 간주된다.","간이공판절차에서는 甲 또는 그의 변호인이 증거신청을 하거나 증거조사에 대해 이의신청을 할 수 없다."],"a":4}},{"y":2018,"e":"국가직 9급","qn":9,"i":"N92018-09-1","t":"법원의 개시결정에도 불구하고 검사가 피고인에게 유리한 증거서류의 열람·등사를 거부한 것은 피고인의 신속하고 공정한 재판을 받을 권리와 변호인의 조력을 받을 권리를 침해한 것으로 헌법에 위반된다.","ox":"O","m":"①","c":"A","tp":"증거개시제도"},{"y":2018,"e":"국가직 9급","qn":9,"i":"N92018-09-2","t":"피고인 또는 변호인은 검사가 서류 등의 열람·등사 또는 서면의 교부를 거부하거나 그 범위를 제한한 때에는 법원에 그 서류 등의 열람·등사 또는 서면의 교부를 허용하도록 할 것을 신청할 수 있다.","ox":"O","m":"②","c":"A","tp":"증거개시제도"},{"y":2018,"e":"국가직 9급","qn":9,"i":"N92018-09-3","t":"검사는 공소제기된 사건에 관한 서류 또는 물건의 목록에 대하여는 국가안보, 증인보호의 필요성 등의 중대한 사유가 있는 경우를 제외하고, 열람 또는 등사를 거부할 수 없다.","ox":"X","m":"③","c":"A","tp":"증거개시제도"},{"y":2018,"e":"국가직 9급","qn":9,"i":"N92018-09-4","t":"검사가 열람·등사 등에 관한 법원의 결정을 지체 없이 이행하지 아니하는 때에는 해당 증인 및 서류 등에 대한 증거신청을 할 수 없다.","ox":"O","m":"④","c":"A","tp":"증거개시제도"},{"y":2019,"e":"국가직 9급","qn":2,"i":"N92019-02","t":"공판기일의 절차 진행을 순서대로 바르게 나열한 것은?","c":"A","mc":{"s":"공판기일의 절차 진행을 순서대로 바르게 나열한 것은?","d":"","o":["인정신문－진술거부권 고지－모두절차－피고인신문－증거조사","인정신문－모두절차－진술거부권 고지－증거조사－피고인신문","진술거부권 고지－인정신문－모두절차－증거조사－피고인신문","진술거부권 고지－인정신문－모두절차－피고인신문－증거조사"],"a":3}},{"y":2019,"e":"국가직 9급","qn":4,"i":"N92019-04-1","t":"공판준비기일에 신청하지 못한 증거는 원칙적으로 공판기일에 신청할 수 없으나, 법원은 실체적 진실발견을 위하여 공판 절차에서 직권으로 증거를 조사할 수 있다.","ox":"O","m":"①","c":"A","tp":"공판준비기일의 절차"},{"y":2019,"e":"국가직 9급","qn":4,"i":"N92019-04-2","t":"공판준비기일에 변호인의 출석은 필수요건이지만 피고인의 출석은 필수사항이 아니므로 피고인이 출석한 경우에도 재판장은 피고인에게 진술거부권을 고지할 필요가 없다.","ox":"X","m":"②","c":"A","tp":"공판준비기일의 절차"},{"y":2019,"e":"국가직 9급","qn":4,"i":"N92019-04-3","t":"공판준비기일은 공개하지 않지만, 재판의 공정성을 위해서 필요한 경우에는 공개할 수 있다.","ox":"X","m":"③","c":"A","tp":"공판준비기일의 절차"},{"y":2019,"e":"국가직 9급","qn":4,"i":"N92019-04-4","t":"검사, 피고인 또는 변호인은 법원에 대하여 공판준비기일의 지정을 신청할 수 있고, 이 경우 당해 신청에 관한 법원의 결정에 대하여는 불복할 수 있다.","ox":"X","m":"④","c":"A","tp":"공판준비기일의 절차"},{"y":2019,"e":"국가직 9급","qn":12,"i":"N92019-12-1","t":"피고인에게 변호인이 있는 경우에는 피고인은 열람·등사만을 신청할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2019,"e":"국가직 9급","qn":12,"i":"N92019-12-2","t":"서류등에는 컴퓨터용 디스크나 그 밖에 정보를 담기 위하여 만들어진 물건으로서 문서가 아닌 특수매체는 포함되지 않는다.","ox":"X","m":"②","c":"A"},{"y":2019,"e":"국가직 9급","qn":12,"i":"N92019-12-3","t":"검사는 열람·등사 또는 서면의 교부를 거부하거나 그 범위를 제한하는 때에는 48시간 이내에 그 이유를 서면으로 통지하여야 한다.","ox":"X","m":"③","c":"A"},{"y":2019,"e":"국가직 9급","qn":12,"i":"N92019-12-4","t":"검사는 서류등의 목록에 대하여는 열람 또는 등사를 거부할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"국가직 9급","qn":2,"i":"N92020-02","t":"공판절차에 대한 설명으로 옳은 것만을 모두 고르면?","c":"A","mc":{"s":"공판절차에 대한 설명으로 옳은 것만을 모두 고르면?","d":"(다툼이 있는 경우 판례에 의함)\nㄱ. 공판준비기일에는 검사와 변호인이 출석하여야 하며, 법원은 공판준비기일이 지정된 사건에 관하여 변호인이 없는 때에는 직권으로 변호인을 선정하여야 한다.\nㄴ. 형사소송법 제33조제1항의 규정에 따라 법원이 직권으로 국선변호인을 선정해야 하는 사건이라도 판결만을 선고 하는 경우라면 변호인 없이 개정할 수 있다.\nㄷ. 피고인에게 변호인이 있는 경우에 피고인은 검사에게 공소제기된 사건에 관한 서류 또는 물건의 목록과 공소사실의 인정 또는 양형에 영향을 미칠 수 있는 서류 또는 물건의 열람만을 신청할 수 있다.\nㄹ. 제1심에서 합의부 관할사건에 관하여 단독판사 관할 사건으로 죄명과 적용법조를 변경하는 공소장변경허가 신청서가 제출된 경우, 사건을 배당받은 합의부는 공소장 변경을 허가하는 결정을 하였더라도 단독판사에게 재배당할 것이 아니라 사건의 실체에 대하여 심판하여야 한다.","o":["ㄱ, ㄷ","ㄴ, ㄹ","ㄱ, ㄴ, ㄷ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":4}},{"y":2020,"e":"국가직 9급","qn":16,"i":"N92020-16-1","t":"간이공판절차에서의 증거조사에서 증거방법을 표시하고 증거 조사내용을 “증거조사함”이라고 표시하는 방법으로 하였다면 법원이 인정 채택한 상당한 증거방법이라고 인정할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"국가직 9급","qn":16,"i":"N92020-16-2","t":"상습폭행죄로 기소된 사건에서 피고인이 폭행사실을 인정한 경우에는 상습성을 부인하더라도 간이공판절차에 의하여 심판할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2020,"e":"국가직 9급","qn":16,"i":"N92020-16-3","t":"피고인이 피의자 신분으로 수사기관에서 공소사실에 대하여 자백하였다면 법원은 간이공판절차를 명할 수 있다.","ox":"X","m":"③","c":"A"},{"y":2020,"e":"국가직 9급","qn":16,"i":"N92020-16-4","t":"간이공판절차의 개시 요건인 자백은 공소장 기재사실을 인정하는 것일 뿐만 아니라 명시적으로 유죄임을 자인하는 진술이어야 한다.","ox":"X","m":"④","c":"A"},{"y":2021,"e":"국가직 9급","qn":1,"i":"N92021-01-1","t":"피고인이 출석하지 아니하면 개정하지 못하는 경우에는 구속된 피고인이 정당한 사유없이 공판정 출석을 거부하고, 교도관에 의한 인치가 불가능하거나 현저히 곤란하다고 인정되는 때에도 피고인의 출석 없이 공판절차를 진행하였다면 위법하다.","ox":"X","m":"①","c":"A"},{"y":2021,"e":"국가직 9급","qn":1,"i":"N92021-01-2","t":"항소심 공판기일에 증거조사가 종료되자 변호인이 피고인을 신문하겠다는 의사를 표시하였으나, 재판장이 일체의 피고인 신문을 불허하고 변호인에게 주장할 내용을 변론요지서로 제출할 것을 명령하면서 변론을 종결한 것은 위법하다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"국가직 9급","qn":1,"i":"N92021-01-3","t":"검사가 공판기일의 통지를 2회 이상 받고 출석하지 아니하거나 판결만을 선고하는 때에는 검사의 출석없이 개정할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"국가직 9급","qn":1,"i":"N92021-01-4","t":"법원은 공소의 제기가 있는 때에는 지체없이, 늦어도 제1회 공판기일 전 5일까지 공소장부본을 피고인 또는 변호인에게 송달하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"국가직 9급","qn":15,"i":"N92021-15-1","t":"피고인이 공판정에서 공소사실에 대하여 자백한 때에는 법원은 그 공소사실에 한하여 간이공판절차에 의하여 심판할 것을 결정할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"국가직 9급","qn":15,"i":"N92021-15-2","t":"법원은 간이공판절차에 의하여 심판할 것을 결정한 사건에 대하여 피고인의 자백이 신빙할 수 없다고 인정되거나 간이 공판절차로 심판하는 것이 현저히 부당하다고 인정할 때에는 검사의 의견을 들어 그 결정을 취소하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"국가직 9급","qn":15,"i":"N92021-15-3","t":"간이공판절차 개시결정이 있는 경우 전문법칙이 적용되는 증거에 대하여 동의가 있는 것으로 간주되므로 피고인 또는 변호인은 이를 증거로 함에 이의를 제기할 수 없다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"국가직 9급","qn":15,"i":"N92021-15-4","t":"간이공판절차 개시결정이 취소된 때에는 공판절차를 갱신하여야 하지만 검사, 피고인 또는 변호인이 이의가 없는 때에는 그러하지 아니하다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"국가직 9급","qn":6,"i":"N92023-06-1","t":"형사재판에서 유죄로 인정하기 위한 심증형성의 정도는 합리적인 의심을 할 여지가 없을 정도이어야 하고, 여기서 ‘합리적 의심’이란 논리와 경험칙에 기하여 요증사실과 양립할 수 없는 사실의 개연성에 대한 합리성 있는 의문을 의미한다.","ox":"O","m":"①","c":"A","tp":"공판절차"},{"y":2023,"e":"국가직 9급","qn":6,"i":"N92023-06-2","t":"검사, 피고인 또는 변호인은 공판절차상 재판장의 처분이 법령에 위반하거나 상당하지 아니한 때에는 이를 이유로 이의신청을 할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"국가직 9급","qn":6,"i":"N92023-06-3","t":"형사재판에서 이와 관련된 다른 형사사건의 확정판결에서 인정된 사실은 특별한 사정이 없는 한 유력한 증거자료가 되는 것이나, 당해 형사재판에서 제출된 다른 증거 내용에 비추어 관련 형사사건 확정판결의 사실판단을 그대로 채택하기 어렵다고 인정될 경우에는 이를 배척할 수 있다.","ox":"O","m":"③","c":"A","tp":"공판절차"},{"y":2023,"e":"국가직 9급","qn":6,"i":"N92023-06-4","t":"공소장 기재의 방식에 관하여 피고인 측으로부터 이의가 제기되지 아니하였고, 법원 역시 범죄사실의 실체를 파악하는 데 지장이 없다고 판단하여 그대로 공판절차를 진행한 결과 증거조사절차가 마무리되어 법관의 심증형성이 이루어진 단계에서는 더 이상 공소장 일본주의 위배를 주장하여 이미 진행된 소송절차의 효력을 다툴 수 없다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"국가직 9급","qn":15,"i":"N92023-15-1","t":"전문심리위원은 공판기일에 한하여 재판장의 허가를 받아 피고인 또는 변호인, 증인 또는 감정인 등 소송관계인에게 소송관계를 분명하게 하기 위하여 필요한 사항에 관하여 의견을 진술하거나 직접 질문할 수 있지만 재판의 합의에 참여하는 것은 허용되지 않는다.","ox":"X","m":"①","c":"A"},{"y":2023,"e":"국가직 9급","qn":15,"i":"N92023-15-2","t":"법원은 전문심리위원이 제출한 서면이나 전문심리위원의 설명 또는 의견의 진술에 관하여 검사, 피고인 또는 변호인에게 구술 또는 서면에 의한 의견진술의 기회를 주어야 한다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"국가직 9급","qn":15,"i":"N92023-15-3","t":"제척 또는 기피 신청이 있는 전문심리위원은 그 신청에 관한 결정이 확정될 때까지 그 신청이 있는 사건의 소송절차에 참여할 수 없다. 이 경우 전문심리위원은 해당 제척 또는 기피 신청에 대하여 의견을 진술할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"국가직 9급","qn":15,"i":"N92023-15-4","t":"법원은 전문심리위원에 관한 규정들을 지켜야 하고, 이를 준수함에 있어서도 전문심리위원과 관련된 절차 진행 등에 관한 사항을 당사자에게 적절한 방법으로 적시에 통지하여 당사자의 참여 기회가 실질적으로 보장될 수 있도록 세심한 배려를 하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"국가직 9급","qn":7,"i":"N92024-07","t":"피고인의 공판정출석에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"피고인의 공판정출석에 대한 설명으로 옳지 않은 것은?","d":"","o":["피고인의 출정없이 증거조사를 할 수 있는 경우, 대리인 또는 변호인이 출정하였더라도 피고인이 출정하지 아니하였다면 증거로 할 수 있음에 동의한 것으로 간주된다.","피고인이 공판기일에 출석하지 아니한 때에는 특별한 규정이 없으면 개정하지 못하나, 피고인이 법인인 경우에는 대리인을 출석하게 할 수 있다.","다액 500만 원 이하의 벌금 또는 과료에 해당하는 사건인 경우, 피고인의 출석을 요하지 아니하고 피고인은 대리인을 출석하게 할 수 있다.","피고인이 질병으로 출정할 수 없는 경우에도 무죄, 면소, 형의 면제 또는 공소기각의 재판을 할 것으로 명백한 때에는 피고인의 출정없이 재판할 수 있다. 2024년도 국가공무원 9급 공채 필기시험 형"],"a":1}},{"y":2024,"e":"국가직 9급","qn":18,"i":"N92024-18-1","t":"국민참여재판에서는 공판준비기일이 필수적 절차이지만, 일반 형사재판에서는 공판준비기일이 필수적 절차가 아니다.","ox":"O","m":"①","c":"A","tp":"공판준비절차"},{"y":2024,"e":"국가직 9급","qn":18,"i":"N92024-18-2","t":"공판준비기일에는 피고인의 출석이 필수적인 요건이 아니다.","ox":"O","m":"②","c":"A","tp":"공판준비절차"},{"y":2024,"e":"국가직 9급","qn":18,"i":"N92024-18-3","t":"공판준비기일이 지정된 사건에 관해 피고인에게 변호인이 없어도 법원이 직권으로 국선변호인을 선정할 필요는 없다.","ox":"X","m":"③","c":"A","tp":"공판준비절차"},{"y":2024,"e":"국가직 9급","qn":18,"i":"N92024-18-4","t":"재판장은 공판준비기일에 출석한 피고인에게 진술을 거부할 수 있음을 알려주어야 한다.","ox":"O","m":"④","c":"A","tp":"공판준비절차"},{"y":2025,"e":"국가직 9급","qn":3,"i":"N92025-03-1","t":"재판의 심리와 판결은 공개한다. 다만, 심리는 국가의 안전보장, 안녕질서 또는 선량한 풍속을 해칠 우려가 있는 경우에는 결정으로 공개하지 아니할 수 있다.","ox":"O","m":"①","c":"A","tp":"공판절차"},{"y":2025,"e":"국가직 9급","qn":3,"i":"N92025-03-2","t":"법정 안에서의 촬영에 대한 신청이 있는 경우 재판장은 피고인의 동의가 있는 때에 한하여 이를 허가할 수 있지만, 피고인의 동의 여부에도 불구하고 촬영을 허가함이 공공의 이익을 위하여 상당 하다고 인정되는 경우에는 그러하지 아니하다.","ox":"O","m":"②","c":"A","tp":"공판절차"},{"y":2025,"e":"국가직 9급","qn":3,"i":"N92025-03-3","t":"법원조직법상 공개금지사유가 없음에도 불구하고 재판의 심리에 관한 공개를 금지한 경우, 그 절차에 의하여 이루어진 증인의 증언은 변호인의 반대신문권이 보장되었다면 증거능력이 있다.","ox":"X","m":"③","c":"A","tp":"공판절차"},{"y":2025,"e":"국가직 9급","qn":3,"i":"N92025-03-4","t":"직접주의는 법관에게 정확한 심증을 형성할 수 있게 할 뿐 아니라, 피고인에게 증거에 관하여 직접적인 의견진술의 기회를 부여함으로써 방어권의 충실한 보장에 기여할 수 있다.","ox":"O","m":"④","c":"A","tp":"공판절차"},{"y":2025,"e":"국가직 9급","qn":16,"i":"N92025-16-1","t":"법원은 간이공판절차의 결정을 한 사건에 대하여 간이공판절차로 심판하는 것이 현저히 부당하다고 인정할 때에는 피고인 또는 변호인의 의견을 들어 그 결정을 취소하여야 한다.","ox":"X","m":"①","c":"A"},{"y":2025,"e":"국가직 9급","qn":16,"i":"N92025-16-2","t":"제1심 법원에서 간이공판절차에 의하여 심판하기로 하여 형사 소송법 제318조의3 규정에 따라 증거능력이 있는 증거는, 항소심에 이르러 피고인이 범행을 부인하면 증거능력이 유지되지 않으므로 다시 증거조사를 해야 한다.","ox":"X","m":"②","c":"A"},{"y":2025,"e":"국가직 9급","qn":16,"i":"N92025-16-3","t":"간이공판절차의 결정이 취소된 때에는 공판절차를 갱신하여야 한다. 단, 검사, 피고인 또는 변호인이 이의가 없는 때에는 그러하지 아니하다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"국가직 9급","qn":16,"i":"N92025-16-4","t":"피고인이 공소사실에 대하여 검사가 신문할 때에 공소사실을 모두 사실과 다름없다고 진술하였다면 변호인이 신문할 때는 범의나 공소사실을 부인하더라도 그 공소사실은 간이공판절차에 의하여 심판할 대상에 해당한다.","ox":"X","m":"④","c":"A"}]};
window.PAIRS=[{"n":1,"s":0.358,"o":{"i":"N92021-04-1","t":"단독판사의 관할사건이 공소장변경에 의하여 합의부 관할 사건으로 변경된 경우에 법원은 결정으로 사건을 관할권이 있는 법원에 이송하여야 한다.","y":2021,"e":"국가직 9급"},"x":{"i":"N92015-02-4","t":"제1심 공판절차에서 합의부 관할사건이 공소장변경에 의하여 단독판사 관할사건으로 변경된 경우 사건을 단독판사에게 재배당하여야 한다.","y":2015,"e":"국가직 9급"}},{"n":1,"s":0.326,"o":{"i":"N92025-13-2","t":"항소심에서 공소장변경에 따라 단독판사 관할사건이 합의부 관할사건으로 변경된 경우, 그 합의부 관할사건에 대한 관할권이 있는 법원은 고등법원이라고 보아야 한다.","y":2025,"e":"국가직 9급"},"x":{"i":"N92025-13-3","t":"제1심에서 합의부 관할사건이 공소장변경에 따라 단독판사 관할 사건으로 변경된 경우, 사건을 배당받은 합의부는 이를 단독판사에게 재배당해야 한다.","y":2025,"e":"국가직 9급"}},{"n":1,"s":0.319,"o":{"i":"N92016-01-4","t":"기피신청을 받은 법관이 형사소송법 제22조에 위반하여 본안의 소송절차를 정지하지 않은 채 그대로 소송을 진행 하여서 한 소송행위는 그 효력이 없고, 이는 그 후 그 기피 신청에 대한 기각결정이 확정되었다고 하더라도 마찬가지이다.","y":2016,"e":"국가직 9급"},"x":{"i":"N92019-05-1","t":"기피신청을 받은 법관이 소송진행 정지에 대한 예외 사유가 없음에도 불구하고 본안의 소송절차를 정지하지 않은 채 그대로 진행한 소송행위는 효력이 없지만, 그 후 기피신청에 대한 기각결정이 확정되었다면 유효하다.","y":2019,"e":"국가직 9급"}},{"n":1,"s":0.312,"o":{"i":"N92024-01-2","t":"약식명령을 한 법관이 그 정식재판 절차의 항소심 판결에 관여한 경우, 이는 형사소송법상 제척사유에 해당한다.","y":2024,"e":"국가직 9급"},"x":{"i":"N92024-01-1","t":"공소제기 전에 검사의 증거보전청구에 의하여 증인신문을 한 법관이 공소제기 후 제1심 법관으로 관여한 경우, 이는 형사소송법상 제척사유에 해당한다.","y":2024,"e":"국가직 9급"}},{"n":4,"s":0.674,"o":{"i":"N92021-03-3","t":"공범 중 1인에 대해 약식명령이 확정된 후 그에 대한 정식재판 청구권회복결정이 있었다고 하더라도 그 사이의 기간 동안에는 특별한 사정이 없는 한 다른 공범자에 대한 공소시효는 정지함이 없이 계속 진행한다.","y":2021,"e":"국가직 9급"},"x":{"i":"N92017-13-3","t":"공범 중 1인에 대해 약식명령이 확정된 후 그에 대한 정식재판 청구권회복결정이 있었다면 그 사이의 기간 동안에는 특별한 사정이 없는 한 다른 공범자에 대한 공소시효가 정지된다.","y":2017,"e":"국가직 9급"}},{"n":4,"s":0.529,"o":{"i":"N92016-11-3","t":"법원은 재정신청서를 송부받은 때에는 송부받은 날부터 10일 이내에 피의자에게 그 사실을 통지하여야 한다.","y":2016,"e":"국가직 9급"},"x":{"i":"N92023-10-1","t":"법원은 재정신청서를 송부받은 때에는 송부받은 날부터 7일 이내에 피의자에게 그 사실을 통지하여야 하고, 재정신청서를 송부받은 날부터 3개월 이내에 항고의 절차에 준하여 결정한다.","y":2023,"e":"국가직 9급"}},{"n":4,"s":0.48,"o":{"i":"N92021-03-2","t":"범인이 국외에서 범죄를 저지르고 형사처분을 면할 목적으로 국외에서 체류를 계속하는 경우에도 공소시효는 정지된다.","y":2021,"e":"국가직 9급"},"x":{"i":"N92016-03-3","t":"공소시효의 정지사유인 ‘범인이 형사처분을 면할 목적으로 국외에 있는 경우’에는 범인이 국외에서 범죄를 저지르고 형사처분을 면할 목적으로 국외에서 체류를 계속하는 경우가 포함되지 아니한다.","y":2016,"e":"국가직 9급"}},{"n":4,"s":0.397,"o":{"i":"N92025-19-4","t":"공범의 1인에 대한 공소제기에 따른 시효정지는 다른 공범자에게도 효력이 있고, 당해 사건의 재판이 확정된 때로부터 진행한다.","y":2025,"e":"국가직 9급"},"x":{"i":"N92016-03-2","t":"공범의 1인에 대한 공소시효의 정지는 다른 공범자에게 효력이 미치고, 당해 사건의 최종행위가 종료한 때로부터 진행한다.","y":2016,"e":"국가직 9급"}},{"n":6,"s":0.587,"o":{"i":"N92016-08-4","t":"피고인이 범행 후 피해자에게 전화를 걸어오자 피해자가 증거를 수집하려고 그 전화내용을 녹음한 경우 그것이 피고인 모르게 녹음된 것이라 하여 이를 위법하게 수집된 증거라고 할 수 없다.","y":2016,"e":"국가직 9급"},"x":{"i":"N92019-18-4","t":"피고인이 범행 후 피해자에게 전화를 걸어오자 피해자가 증거를 수집하려고 그 전화내용을 녹음한 경우, 그 녹음테이프가 피고인 모르게 녹음된 것이면 그 녹음테이프는 위법하게 수집된 증거이다.","y":2019,"e":"국가직 9급"}},{"n":6,"s":0.338,"o":{"i":"N92020-13-2","t":"탄핵증거는 진술의 증명력을 감쇄하기 위하여 인정되는 것이고, 범죄사실 또는 그 간접사실을 인정하는 증거로는 허용되지 않는다.","y":2020,"e":"국가직 9급"},"x":{"i":"N92017-03-3","t":"탄핵증거는 진술의 증명력을 감쇄하기 위해서 뿐만 아니라 범죄사실 또는 그 간접사실의 인정증거로서도 허용된다.","y":2017,"e":"국가직 9급"}},{"n":3,"s":0.568,"o":{"i":"N92020-19-3","t":"전자정보에 대한 압수·수색이 종료되기 전에 혐의사실과 관련된 전자정보를 적법하게 탐색하는 과정에서 별도의 범죄혐의와 관련된 전자정보를 우연히 발견한 경우라면, 수사기관은 더 이상의 추가 탐색을 중단하고 법원에서 별도의 범죄혐의에 대한 압수·수색영장을 발부받은 경우에 한하여 그 정보에 대하여 적법하게 압수·수색을 할 수 있다.","y":2020,"e":"국가직 9급"},"x":{"i":"N92016-18-3","t":"전자정보에 대한 압수·수색이 종료되기 전에 혐의사실과 관련된 전자정보를 적법하게 탐색하는 과정에서 별도의 범죄 혐의와 관련된 전자정보를 우연히 발견한 경우라면 따로 압수·수색영장을 발부받지 않고 이 전자정보를 적법하게 압수·수색할 수 있다.","y":2016,"e":"국가직 9급"}},{"n":8,"s":0.615,"o":{"i":"N92023-09-3","t":"재판장의 재판에 대한 준항고의 청구는 재판의 고지있는 날로부터 7일 이내에 하여야 한다.","y":2023,"e":"국가직 9급"},"x":{"i":"N92019-10-4","t":"준항고의 청구는 재판의 고지 있는 날로부터 5일 이내에 하여야 한다.","y":2019,"e":"국가직 9급"}},{"n":8,"s":0.442,"o":{"i":"N92025-09-3","t":"경합범 중 일부에 대하여 무죄, 일부에 대하여 유죄를 선고한 제1심 판결에 대하여 검사만이 무죄 부분에 대하여 항소를 한 경우, 항소심에서 이를 파기할 때 파기의 범위는 무죄 부분에 한정된다.","y":2025,"e":"국가직 9급"},"x":{"i":"N92016-16-1","t":"경합범 중 일부에 대하여 무죄, 일부에 대하여 유죄를 선고한 제1심판결에 대하여 검사만이 무죄 부분에 대하여 항소를 한 경우, 피고인과 검사가 항소하지 아니한 유죄판결 부분은 항소기간이 지남으로써 확정되므로, 항소심에서 이를 파기할 때에는 유죄부분만을 파기하여야 한다.","y":2016,"e":"국가직 9급"}},{"n":8,"s":0.43,"o":{"i":"N92021-10-2","t":"경합범 관계에 있는 수 개의 범죄사실을 유죄로 인정하여 한 개의 형을 선고한 불가분의 확정판결에서 그 중 일부의 범죄사실에 대하여만 재심청구의 이유가 있는 것으로 인정 되었으나 그 판결 전부에 대하여 재심개시의 결정을 한 경우, 불이익변경금지원칙이 적용되어 원판결의 형보다 중한 형을 선고하지 못한다.","y":2021,"e":"국가직 9급"},"x":{"i":"N92023-20-4","t":"경합범 관계에 있는 수개의 범죄사실을 유죄로 인정하여 1개의 형을 선고한 불가분의 확정판결에서 그 중 일부의 범죄사실에 대하여만 재심청구의 이유가 인정되는 경우, 그 부분에 대해서만 재심개시결정을 하여야 한다.","y":2023,"e":"국가직 9급"}},{"n":8,"s":0.333,"o":{"i":"N92017-19-3","t":"제1심에서 징역형의 집행유예를 선고한 데 대하여 피고인만이 항소한 경우 제2심이 징역형의 형기를 단축하여 실형을 선고 하는 것은 불이익변경금지의 원칙에 위배된다.","y":2017,"e":"국가직 9급"},"x":{"i":"N92016-07-3","t":"제1심의 징역형의 선고유예의 판결에 대하여 피고인만이 항소한 경우에 제2심이 벌금형을 선고한 것은 불이익변경 금지의 원칙에 위배되지 아니한다.","y":2016,"e":"국가직 9급"}},{"n":7,"s":0.457,"o":{"i":"N92017-08-2","t":"상습범으로서 포괄일죄의 관계에 있는 여러 개의 범죄사실 중 일부에 대하여 유죄판결이 확정되어 상습범으로 처단된 후 그 확정판결의 사실심선고 전에 저질러진 나머지 범행에 대해 공소가 제기된 때에는 면소판결을 선고하여야 한다.","y":2017,"e":"국가직 9급"},"x":{"i":"N92021-18-4","t":"상습범으로서 포괄적 일죄의 관계에 있는 여러 개의 범죄사실 중 일부에 대하여 유죄판결이 확정된 경우에, 그 확정판결의 사실심판결 선고 전에 저질러진 나머지 범죄에 대하여 새로이 공소가 제기되었다면 판결로 공소를 기각하여야 한다.","y":2021,"e":"국가직 9급"}},{"n":5,"s":0.495,"o":{"i":"N92021-15-2","t":"법원은 간이공판절차에 의하여 심판할 것을 결정한 사건에 대하여 피고인의 자백이 신빙할 수 없다고 인정되거나 간이 공판절차로 심판하는 것이 현저히 부당하다고 인정할 때에는 검사의 의견을 들어 그 결정을 취소하여야 한다.","y":2021,"e":"국가직 9급"},"x":{"i":"N92025-16-1","t":"법원은 간이공판절차의 결정을 한 사건에 대하여 간이공판절차로 심판하는 것이 현저히 부당하다고 인정할 때에는 피고인 또는 변호인의 의견을 들어 그 결정을 취소하여야 한다.","y":2025,"e":"국가직 9급"}}];
